      aiMapId: origin.mapId,
      aiCardId: origin.cardId,
      aiAttributionToken: origin.attributionToken,
      aiEditorId: origin.editorId,
      aiType: origin.aiType,
      aiModel: origin.aiModel,
      timeoutMs: 60_000,
      body: JSON.stringify({ instruction, sourceRevision }),
