      if (url.protocol === 'http:' || url.protocol === 'https:') {
        url.search = ''
        url.hash = ''
        return url.toString().replace(/\/+$/, '')
      }
    } catch {
      console.warn('[Mind & Progress] MNP_PUBLIC_URL이 올바르지 않아 자동 감지 주소를 사용합니다.')
    }
  }
  return `http://${detectedPublicIpv4()}:${webPort}`
}

