// 메인 머신 ID는 MnP가 실행되는 PC를 가리킨다. 호스트명이 바뀌어도 등록을 유지하려면 MNP_MACHINE_ID로 고정한다.
function mainMachineDescriptor() {
  const configured = String(process.env.MNP_MACHINE_ID ?? '').trim()
  const derived = configured || hostname()
  const machineId = derived.toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 64)
  return {
    machineId: machineId || 'main',
    label: String(process.env.MNP_MACHINE_LABEL ?? '').trim() || hostname() || '메인 머신',
    platform: process.platform,
  }
}

function persistMachineRegistry() {
  const storedMachines = serializeMachineRegistry(machineRegistry)
  machineRegistryWriteQueue = machineRegistryWriteQueue.catch(() => {})
    .then(() => writeStoredArray(machineRegistryFile, storedMachines))
  return machineRegistryWriteQueue
}

function persistDistributedWorkSettings() {
  const storedSettings = [...distributedWorkSettings.entries()]
    .sort(([firstUserId], [secondUserId]) => firstUserId.localeCompare(secondUserId))
    .map(([userId, settings]) => ({ userId, ...settings }))
  distributedWorkSettingsWriteQueue = distributedWorkSettingsWriteQueue.catch(() => {})
    .then(() => writeStoredArray(distributedWorkSettingsFile, storedSettings))
  return distributedWorkSettingsWriteQueue
}

async function loadMachineRegistry() {
  machineRegistry = ensureMainMachine(
    normalizeMachineRegistry(await readStoredArray(machineRegistryFile)),
    mainMachineDescriptor(),
  )
  await persistMachineRegistry()
}

async function loadDistributedWorkSettings() {
  const storedSettings = await readStoredArray(distributedWorkSettingsFile)
  for (const settings of storedSettings) {
    if (typeof settings?.userId !== 'string' || !users.some((user) => user.id === settings.userId)) continue
    distributedWorkSettings.set(settings.userId, normalizeDistributedWorkSettings(settings))
  }
  await persistDistributedWorkSettings()
}

// Runner는 하트비트와 오퍼레이션 대기마다 접속 시각을 남긴다.
// 하트비트 기본 간격이 60초, long-poll이 25초이므로 이 정도면 정상 동작 중에는 끊김으로 보이지 않는다.
const runnerOnlineWithinMs = 150_000

function isLoopbackHostname(value) {
  const normalized = String(value ?? '').trim().toLowerCase().replace(/^\[|\]$/g, '')
  return normalized === 'localhost' || normalized === '::1' || normalized.startsWith('127.')
}

// Runner는 브라우저와 같은 공개 주소를 쓴다.
// 개발 서버가 0.0.0.0에 바인딩되어 /api를 로컬 API로 프록시하므로 API 포트를 LAN에 열 필요가 없다.
// 프록시에 timeout을 설정하지 않았기 때문에 long-poll도 그대로 통과한다.
const runnerApiBaseUrl = publicBaseUrl
const runnerApiLanReachable = (() => {
  try {
    return !isLoopbackHostname(new URL(runnerApiBaseUrl).hostname)
  } catch {
    return false
  }
})()

function machineViewer(user) {
  return { userId: user.id, isAdmin: user.role === 'admin' }
}

function userDistributedWork(user) {
  return resolveDistributedWorkSettings(distributedWorkSettings.get(user.id), machineRegistry, machineViewer(user))
}

// 소유자 표시와 접속 상태는 화면에서만 쓰므로 순수 모듈이 아니라 응답 단계에서 붙인다.
function machineRegistryResponse(user) {
  const registry = publicMachineRegistry(machineRegistry)
  const now = Date.now()
  return {
    ...registry,
    runner: {
      apiUrl: runnerApiBaseUrl,
      lanReachable: runnerApiLanReachable,
      onlineWithinMs: runnerOnlineWithinMs,
    },
    machines: registry.machines.map((machine) => ({
      ...machine,
      ownerName: users.find((candidate) => candidate.id === machine.ownerUserId)?.name ?? null,
      manageable: machineManageableBy(machineRegistry, machine.machineId, machineViewer(user)),
      // 메인 머신은 Runner 없이 루프백으로 직접 호출하므로 접속 상태가 없다.
      online: machine.role === 'main'
        ? null
        : machine.lastSeenAt !== null && now - Date.parse(machine.lastSeenAt) <= runnerOnlineWithinMs,
    })),
  }
}

function requireRunnerMachine(request, response, machineId) {
  const token = runnerBearerToken(request)
  if (!token || !verifyMachineToken(machineRegistry, machineId, token)) {
    sendJson(response, 401, { error: 'Runner 인증에 실패했습니다.' })
    return null
  }
  return findMachine(machineRegistry, machineId)
}

function runnerBearerToken(request) {
  const authorization = String(request.headers.authorization ?? '')
  return authorization.startsWith('Bearer ') ? authorization.slice(7).trim() : ''
}

async function decommissionEditorMachines(editorId, { remove = false } = {}) {
  const machineIds = machineRegistry.machines
    .filter((machine) => machine.machineId !== machineRegistry.mainMachineId && machine.ownerUserId === editorId)
    .map((machine) => machine.machineId)
  if (machineIds.length === 0) return

  const machineIdSet = new Set(machineIds)
  const now = new Date().toISOString()
  machineRegistry = {
    ...machineRegistry,
    machines: remove
      ? machineRegistry.machines.filter((machine) => !machineIdSet.has(machine.machineId))
      : machineRegistry.machines.map((machine) => (
        machineIdSet.has(machine.machineId)
          ? { ...machine, enabled: false, tokenHash: null, updatedAt: now }
          : machine
      )),
  }
  for (const machineId of machineIds) {
    clearRunnerRuntimeRouting(machineId)
    machineOperationQueue.cancelMachine(
      machineId,
      remove ? '머신 소유자 계정이 삭제되었습니다.' : '머신 소유자 계정이 비활성화되었습니다.',
    )
  }
  for (const [userId, settings] of distributedWorkSettings) {
    if (!machineIdSet.has(settings.defaultMachineId)) continue
    distributedWorkSettings.set(userId, { ...settings, defaultMachineId: null })
  }
  await Promise.all([persistMachineRegistry(), persistDistributedWorkSettings()])
}

// 하트비트와 오퍼레이션 조회는 자주 오므로 실제 값이 바뀔 때만 저장한다.
async function noteMachineSeen(machineId) {
  const previous = findMachine(machineRegistry, machineId)?.lastSeenAt
  const updated = touchMachine(machineRegistry, machineId)
  if (updated === machineRegistry) return
  machineRegistry = updated
  if (previous && Date.now() - Date.parse(previous) < 60_000) return
  await persistMachineRegistry()
}

async function loadAiAttributions() {
  const now = Date.now()
  const storedAttributions = await readStoredArray(aiAttributionsFile)
  for (const attribution of storedAttributions) {
    if (!/^[a-f0-9]{64}$/.test(String(attribution?.tokenHash ?? ''))) continue
    if (!Number.isFinite(attribution?.expiresAt) || attribution.expiresAt <= now) continue
    const hasDocumentScope = isValidMapId(attribution?.mapId) && typeof attribution?.cardId === 'string' && attribution.cardId
    const hasConversationScope = validAiConversationId(attribution?.conversationId)
    if (!hasDocumentScope && !hasConversationScope) continue
    if (typeof attribution?.authorName !== 'string' || !attribution.authorName.trim()) continue
    const { tokenHash, ...value } = attribution
    aiAttributions.set(tokenHash, value)
  }
  await persistAiAttributions()
}

async function loadAiConversationAttributions() {
  const storedAttributions = await readStoredArray(aiConversationAttributionsFile)
  for (const attribution of storedAttributions) {
    if (!isValidMapId(attribution?.mapId) || typeof attribution?.cardId !== 'string' || !attribution.cardId) continue
    if (typeof attribution?.conversationId !== 'string' || !attribution.conversationId) continue
    if (typeof attribution?.authorName !== 'string' || !attribution.authorName.trim()) continue
    aiConversationAttributions.set(conversationAttributionKey(attribution.mapId, attribution.cardId), attribution)
  }
  await persistAiConversationAttributions()
}

async function loadAiConversationOrigins() {
  const storedOrigins = await readStoredArray(aiConversationOriginsFile)
  for (const storedOrigin of storedOrigins) rememberAiConversationOrigin(storedOrigin)
  await persistAiConversationOrigins()
}

async function recoverAiConversationOrigins() {
  const candidates = []
  for (const summary of await listMaps()) {
    const map = await readMap(summary.id)
    if (!map || map.trashedAt) continue
    for (const node of map.nodes) {
      for (const link of aiConversationLinksFromData(node.data)) {
        candidates.push({
          conversationId: link.conversationId,
          mapId: map.id,
          cardId: node.id,
          startedBy: link.startedBy?.id ?? null,
          linkedAt: link.startedAt ?? link.linkedAt,
          workspace: link.workspace,
          homeMachineId: link.homeMachineId ?? machineRegistry.mainMachineId,
        })
      }
    }
  }
  candidates.sort((first, second) => String(first.linkedAt ?? '').localeCompare(String(second.linkedAt ?? ''))
    || String(first.mapId).localeCompare(String(second.mapId))
    || String(first.cardId).localeCompare(String(second.cardId)))
  for (const candidate of candidates) rememberAiConversationOrigin(candidate)
  await persistAiConversationOrigins()
}

async function loadAiDelegations() {
  const storedDelegations = await readStoredArray(aiDelegationsFile)
  let rejectedCount = 0
  let repairedCount = 0
  for (const delegation of storedDelegations) {
    if (!isValidAiDelegationId(delegation?.id)) {
      rejectedCount += 1
      continue
    }
    if (!isValidMapId(delegation?.mapId)
      || typeof delegation?.parentCardId !== 'string'
      || typeof delegation?.targetCardId !== 'string'
      || typeof delegation?.parentConversationId !== 'string'
      || typeof delegation?.targetConversationId !== 'string') {
      rejectedCount += 1
      continue
    }
    const normalized = {
      ...delegation,
      parentHomeMachineId: normalizeMachineId(delegation.parentHomeMachineId)
        || conversationHomeMachineId(delegation.parentConversationId),
      targetHomeMachineId: normalizeMachineId(delegation.targetHomeMachineId)
        || conversationHomeMachineId(delegation.targetConversationId),
      ...(delegation.state === 'completed' && delegation.parentDispatchState !== 'completed'
        ? { parentDispatchState: 'completed' }
        : {}),
    }
    if (['failed', 'parent-wake-failed'].includes(normalized.state) && aiDelegationLimitState(normalized)) {
      normalized.attemptHistory = aiDelegationAttemptHistory(delegation, '재시도 가능한 외부 제한 대기 상태로 복원')
      normalized.state = aiDelegationLimitState(normalized)
    }
    if (JSON.stringify(normalized) !== JSON.stringify(delegation)) repairedCount += 1
    aiDelegations.set(normalized.id, normalized)
  }
  if (rejectedCount > 0) {
    console.warn(`[AI delegation storage] ${rejectedCount}개 항목을 무시했으며 원본 파일은 덮어쓰지 않았습니다.`)
  }
  if (repairedCount > 0) {
    await persistAiDelegations()
    console.log(`[AI delegation storage] ${repairedCount}개 위임의 저장 상태를 보정했습니다.`)
  }
}

async function loadAiWorkspaceHistories() {
  const storedHistories = await readStoredArray(aiWorkspaceHistoriesFile)
  // 구버전 서버 이력은 메인에서만 사용했다. 서브 머신이나 계정 기본 머신으로 복제하지 않는다.
  // 명시적 머신 기록(빈 목록 포함)이 구버전 기록보다 우선한다.
  for (const history of [...storedHistories].sort((a, b) => Number(Boolean(a?.machineId)) - Number(Boolean(b?.machineId)))) {
    if (typeof history?.userId !== 'string' || !Array.isArray(history.workspaces)
      || !users.some((user) => user.id === history.userId)) continue
    const machineId = Object.hasOwn(history, 'machineId') ? normalizeMachineId(history.machineId) : machineRegistry.mainMachineId
    if (!machineId) continue
    const workspaces = normalizeAiWorkspaceHistory(history.workspaces)
    aiWorkspaceHistories.set(JSON.stringify([history.userId, machineId]), workspaces)
  }
  await persistAiWorkspaceHistories()
}

async function loadSessions() {
  const now = Date.now()
  const storedSessions = await readStoredArray(sessionsFile)
  for (const session of storedSessions) {
    if (!/^[a-f0-9]{64}$/.test(String(session?.tokenHash ?? ''))) continue
    if (!Number.isFinite(session?.expiresAt) || session.expiresAt <= now) continue
    if (!users.some((user) => user.id === session.userId && user.active !== false)) continue
    sessions.set(session.tokenHash, {
      userId: session.userId,
      expiresAt: session.expiresAt,
      persistent: true,
    })
  }
  await persistSessions()
}

async function loadIntegrationToken() {
  await mkdir(dataDirectory, { recursive: true })
  try {
    const stored = (await readFile(integrationTokenFile, 'utf8')).trim()
    if (stored.length >= 32) return stored
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error
  }

  const token = randomBytes(32).toString('base64url')
  await writeFile(integrationTokenFile, `${token}\n`, { encoding: 'utf8', mode: 0o600 })
  return token
}

async function discoverAionUiBaseUrl() {
  try {
    const record = JSON.parse(await readFile(aionUiDiscoveryFile, 'utf8'))
    const port = Number(record?.port)
    if (record?.schemaVersion !== 1 || record?.host !== '127.0.0.1' || !Number.isInteger(port) || port < 1 || port > 65_535) {
      return null
    }
    return `http://127.0.0.1:${port}`
  } catch (error) {
    if (error?.code !== 'ENOENT' && error instanceof SyntaxError === false) {
      console.warn('[AionUi discovery]', error)
    }
    return null
  }
}

async function aionUiCandidateBaseUrls() {
  const discoveredBaseUrl = await discoverAionUiBaseUrl()
  return [...new Set([
    ...configuredAionUiBaseUrls,
    discoveredBaseUrl,
    activeAionUiBaseUrl,
    ...fallbackAionUiBaseUrls,
  ].filter(Boolean))]
}

async function fetchAionUi(pathname, { timeoutMs = 8_000, method = 'GET', body } = {}) {
  let lastError = null
  let lastResponseError = null
  const candidates = await aionUiCandidateBaseUrls()
  for (const baseUrl of candidates) {
    try {
      const response = await fetch(`${baseUrl}${pathname}`, {
        method,
        headers: {
          Accept: 'application/json',
          ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
        },
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(timeoutMs),
      })
      const responseBody = await response.json().catch(() => ({}))
      if (!response.ok || responseBody?.success === false) {
        const requestError = new Error(`AIONUI_REQUEST_FAILED:${response.status}`)
        requestError.status = response.status
        requestError.code = responseBody?.error?.code ?? responseBody?.code ?? null
        throw requestError
      }
      activeAionUiBaseUrl = baseUrl
      return responseBody?.data ?? responseBody
    } catch (error) {
      lastError = error
      if (Number.isInteger(error?.status)) lastResponseError = error
    }
  }
  throw lastResponseError ?? lastError ?? new Error('AIONUI_REQUEST_FAILED')
}

// 메인 머신과 서브 머신의 유일한 분기점이다.
// 메인은 기존과 같이 루프백으로 직접 호출하고, 서브는 Runner가 가져갈 오퍼레이션 큐에 넣는다.
// 서브 머신의 AionUi는 inbound 주소를 열지 않으므로 메인에서 직접 호출할 수 없다.
function fetchAionUiOn(machineId, pathname, options = {}) {
  const targetMachineId = normalizeMachineId(machineId)
  if (!targetMachineId || targetMachineId === machineRegistry.mainMachineId) {
    return fetchAionUi(pathname, options)
  }

  const machine = findMachine(machineRegistry, targetMachineId)
  if (!machine) {
    return Promise.reject(new MachineOperationError(
      `${targetMachineId} 머신이 등록되어 있지 않습니다.`,
      { reasonCode: 'MACHINE_UNREGISTERED' },
    ))
  }
  if (!machine.enabled) {
    return Promise.reject(new MachineOperationError(
      `${machine.label} 머신이 비활성화되어 있습니다.`,
      { reasonCode: 'MACHINE_DISABLED' },
    ))
  }
  if (!machine.tokenHash) {
    return Promise.reject(new MachineOperationError(
      `${machine.label} 머신에 Runner 토큰이 발급되지 않았습니다.`,
      { reasonCode: 'RUNNER_NOT_CONFIGURED' },
    ))
  }

  try {
    return machineOperationQueue.enqueue(targetMachineId, {
      method: options.method ?? 'GET',
      pathname,
      body: options.body,
      timeoutMs: options.timeoutMs,
    }).completion
  } catch (error) {
    return Promise.reject(error)
  }
}

function fetchAionCoreDispatchCapabilities(machineId = machineRegistry.mainMachineId) {
  const targetMachineId = normalizeMachineId(machineId) || machineRegistry.mainMachineId
  const pendingRequest = aionCoreDispatchCapabilitiesRequests.get(targetMachineId)
  if (pendingRequest) return pendingRequest
  const cached = aionCoreDispatchCapabilitiesCaches.get(targetMachineId)
  if (cached && Date.now() - cached.cachedAt < aionCoreDispatchCapabilitiesCacheMs) {
    return Promise.resolve(cached.value)
  }
  const request = fetchAionUiOn(targetMachineId, '/api/internal/external-conversation-dispatches/capabilities', {
    timeoutMs: 3_000,
  })
    .then((capabilities) => {
      aionCoreDispatchCapabilitiesCaches.set(targetMachineId, { value: capabilities, cachedAt: Date.now() })
      return capabilities
    })
    .catch((error) => {
      aionCoreDispatchCapabilitiesCaches.delete(targetMachineId)
      throw error
    })
    .finally(() => {
      aionCoreDispatchCapabilitiesRequests.delete(targetMachineId)
    })
  aionCoreDispatchCapabilitiesRequests.set(targetMachineId, request)
  return request
}

async function aionCoreSupportsWorkspaceLease(machineId = machineRegistry.mainMachineId) {
  try {
    const capabilities = await fetchAionCoreDispatchCapabilities(machineId)
    return capabilities?.workspaceLeaseVersion >= 2
      && capabilities?.atomicWorkspaceRebind === true
      && capabilities?.releasesRuntimeOnTerminal === true
  } catch {
    return false
  }
}

async function aionCoreSupportsExplicitCompletionAfterInterruption(machineId = machineRegistry.mainMachineId) {
  try {
    const capabilities = await fetchAionCoreDispatchCapabilities(machineId)
    return capabilities?.schemaVersion >= 3
      && capabilities?.explicitCompletionAfterInterruption === true
  } catch {
    return false
  }
}

async function protectAionUiConversationTitle(conversationId, title, machineId = conversationHomeMachineId(conversationId)) {
  const protectedConversation = await fetchAionUiOn(machineId, `/api/conversations/${encodeURIComponent(conversationId)}`, {
    method: 'PATCH',
    body: { name: title, name_source: 'user' },
  })
  if (String(protectedConversation?.id ?? '') !== conversationId
    || String(protectedConversation?.name ?? '') !== title
    || protectedConversation?.name_source !== 'user') {
    throw new Error('AIONUI_CONVERSATION_TITLE_NOT_PROTECTED')
  }
}

function delegationSourceForRequest(scope, mapId) {
  if (!scope.conversationId) {
    return scope.mapId === mapId && scope.cardId
      ? { mapId, cardId: scope.cardId, conversationId: null, startedBy: null, source: 'legacy-mcp-process' }
      : null
  }
  const origin = aiConversationOrigins.get(scope.conversationId)
  if (!origin || origin.mapId !== mapId) return null
  return { ...origin, source: 'conversation-origin' }
}

async function resolveOrRememberDelegationSource(scope, mapId, map) {
  const existing = delegationSourceForRequest(scope, mapId)
  if (existing || !scope.conversationId || scope.mapId !== mapId || !scope.cardId
    || !map.nodes.some((node) => node.id === scope.cardId)) return existing
  const origin = rememberAiConversationOrigin({
    conversationId: scope.conversationId,
    mapId,
    cardId: scope.cardId,
    startedBy: scope.editorId,
    linkedAt: new Date().toISOString(),
  })
  if (!origin) return null
  await persistAiConversationOrigins()
  return { ...origin, source: 'conversation-origin' }
}

function delegationParentAttribution(request, source, parentCard, fallbackUser) {
  const scope = integrationRequestScope(request)
  const token = String(request.headers['x-mnp-ai-attribution'] ?? '').trim()
  const tokenAttribution = token ? aiAttributions.get(sessionTokenKey(token)) : null
  const currentAttribution = aiConversationAttributions.get(conversationAttributionKey(source.mapId, source.cardId))
  const transientAttribution = [...aiAttributions.values()].find((candidate) =>
    candidate.conversationId === source.conversationId
    && candidate.mapId === source.mapId
    && candidate.cardId === source.cardId)
  const matchingAttribution = [tokenAttribution, transientAttribution, currentAttribution]
    .find((candidate) => candidate
      && candidate.mapId === source.mapId
      && candidate.cardId === source.cardId
      && (!source.conversationId || candidate.conversationId === source.conversationId)
      && (!scope.editorId || candidate.startedBy === scope.editorId))
  const conversationLink = source.conversationId
    ? aiConversationLinksFromData(parentCard.data).find((link) => link.conversationId === source.conversationId)
    : null
  const conversationId = source.conversationId ?? matchingAttribution?.conversationId
  if (!conversationId) return null
  return {
    ...(matchingAttribution ?? {}),
    mapId: source.mapId,
    cardId: source.cardId,
    conversationId,
    homeMachineId: conversationHomeMachineId(conversationId, conversationLink ?? source),
    startedBy: matchingAttribution?.startedBy
      ?? source.startedBy
      ?? conversationLink?.startedBy?.id
      ?? fallbackUser.id,
    selection: matchingAttribution?.selection ?? conversationLink ?? null,
    workspace: matchingAttribution?.selection?.workspace
      ?? matchingAttribution?.workspace
      ?? conversationLink?.workspace
      ?? source.workspace
      ?? null,
  }
}

function isHierarchyDescendant(map, parentCardId, targetCardId) {
  const childrenByParent = new Map()
  for (const edge of map.edges.filter((edge) => edge.data?.relation !== 'knowledge')) {
    const children = childrenByParent.get(edge.source) ?? []
    children.push(edge.target)
    childrenByParent.set(edge.source, children)
  }
  const pending = [...(childrenByParent.get(parentCardId) ?? [])]
  const visited = new Set()
  while (pending.length > 0) {
    const cardId = pending.shift()
    if (!cardId || visited.has(cardId)) continue
    if (cardId === targetCardId) return true
    visited.add(cardId)
    pending.push(...(childrenByParent.get(cardId) ?? []))
  }
  return false
}

async function delegationCreateSelection(targetCard, requestedSelection, parentAttribution, machineId) {
  const linkedConversations = aiConversationLinksFromData(targetCard.data)
  const latestLink = [...linkedConversations].reverse()
    .find((link) => conversationHomeMachineId(link.conversationId, link) === machineId)
  const inheritParentWorkspace = conversationHomeMachineId(
    parentAttribution?.conversationId,
    parentAttribution,
  ) === machineId
  const parentSelection = inheritParentWorkspace || !parentAttribution?.selection
    ? parentAttribution?.selection
    : { ...parentAttribution.selection, workspace: null }
  const parentFallback = inheritParentWorkspace || !parentAttribution
    ? parentAttribution
    : { ...parentAttribution, selection: parentSelection, workspace: null }
  const selection = mergeAiDelegationSelections(
    requestedSelection,
    latestLink,
    parentSelection,
    parentFallback,
  )
  if (!selection) throw new AionUiExternalLaunchPayloadError('새 AI 대화에 사용할 AI 종류와 모델을 확인할 수 없습니다.')
  // AI 종류·모델의 재사용과 작업 디렉토리의 상속은 별개다. 과거 하위 카드의
  // 폴더가 사용자가 새 상위 대화에서 선택한 프로젝트를 덮어쓰지 않게 한다.
  selection.workspace = aiDelegationNewWorkspace(requestedSelection, parentFallback, latestLink)

  const [agents, providers, rawMcpServers] = await Promise.all([
    fetchAionUiOn(machineId, '/api/agents/management'),
    fetchAionUiOn(machineId, '/api/providers'),
    fetchAionUiOn(machineId, '/api/mcp/servers'),
  ])
  const normalizedAgents = (Array.isArray(agents) ? agents : [])
    .filter((agent) => agent?.enabled !== false && agent?.installed === true)
    .map((agent) => normalizeAionUiAgent(agent, Array.isArray(providers) ? providers.filter((item) => item?.enabled !== false) : []))
  const resolvedAgent = normalizedAgents.find((agent) => agent.id === selection.agent.id)
  const resolvedModel = resolvedAgent?.models.find((model) => model.id === selection.model.id)
  if (!resolvedAgent || !resolvedModel) {
    throw new AionUiExternalLaunchPayloadError('새 AI 대화에 사용할 AI 종류 또는 모델을 AionUi에서 확인할 수 없습니다.')
  }
  selection.agent = { id: resolvedAgent.id, label: resolvedAgent.name }
  selection.model = { id: resolvedModel.id, label: resolvedModel.label }
  selection.providerId = resolvedModel.providerId ?? selection.providerId

  const mcpServers = normalizeAionUiMcpServers(rawMcpServers)
  const requiredMcpIds = mcpServers.filter((server) => server.required).map((server) => server.id)
  selection.mcpIds = [...new Set([...selection.mcpIds, ...requiredMcpIds])]
  return selection
}

function issueDelegatedAttribution({ mapId, cardId, conversationId, selection, startedBy, homeMachineId }) {
  const token = randomBytes(32).toString('base64url')
  const now = Date.now()
  const attribution = {
    authorName: `${selection.agent.label}(${selection.model.label})`,
    agentId: selection.agent.id,
    agentName: selection.agent.label,
    modelId: selection.model.id,
    modelName: selection.model.label,
    providerId: selection.providerId,
    mapId,
    cardId,
    homeMachineId,
    startedBy,
    selection: {
      agent: selection.agent,
      model: selection.model,
      providerId: selection.providerId,
      ...(selection.mode ? { mode: selection.mode } : {}),
      ...(selection.thoughtLevel ? { thoughtLevel: selection.thoughtLevel } : {}),
      skills: selection.enabledSkillIds.map((id) => ({ id, label: id })),
      mcpServers: selection.mcpIds.map((id) => ({ id, label: id })),
      workspace: selection.workspace,
    },
    createdAt: now,
    expiresAt: now + aiAttributionDurationMs,
    ...(conversationId ? { conversationId } : {}),
  }
  aiAttributions.set(sessionTokenKey(token), attribution)
  return { token, attribution }
}

function buildDelegatedInstruction({ mapId, cardId, editorId, attributionToken, instruction, workspaceLease }) {
  const workspaceInstruction = buildWorkspaceInstruction(workspaceLease)
  return `# MindNProgress 하위 카드 위임 작업 요청

${MNP_CONTEXT_BOOTSTRAP_INSTRUCTION}

이 요청은 상위 카드의 AI가 현재 하위 카드에 실행을 위임한 것이므로, 일반적인 다음 작업 제안에 그치지 말고 아래 "상위 AI 지시"를 실제로 수행하세요. \`editorId\`와 \`attributionToken\`은 이후 MindNProgress MCP 작업이 끝날 때까지 유지하세요.

- mapId: \`${mapId}\`
- cardId: \`${cardId}\`
- editorId: \`${editorId}\`
- attributionToken: \`${attributionToken}\`

MCP 조회 결과의 \`guide\`, \`selection.taskLinks.startupInspection\`, \`selection.aiWorkCoordination\`과 \`nextStep\`을 확인하고 따르세요. 관련 카드를 수정하기 전에는 AI 작업 상태를 확인하고, 실행 결과를 카드 댓글과 공유 지식에 알맞게 기록하세요. 상위 AI가 맡긴 범위에서 수행하고, 분석·제안만 요청받았다면 구현으로 확대하지 마세요.

이 위임 실행이 사용자의 중지로 끊긴 뒤 같은 대화에서 직접 이어진 경우, 단순 질의 응답이나 중간 보고는 위임 완료가 아닙니다. 실제 위임 작업과 카드 기록, 필요한 작업공간 체크포인트까지 모두 끝낸 마지막 턴에서만 최종 답변 직전에 \`mindnprogress_complete_ai_delegation\`을 호출하세요. 중단 없이 진행된 최초 실행에는 이 완료 신호가 필요하지 않습니다.

MCP 도구를 사용할 수 없거나 문서 또는 카드를 찾지 못하면 임의로 추측하지 말고 확인 가능한 범위만 수행한 뒤 제약을 명확히 남기세요.

${workspaceInstruction ? `${workspaceInstruction}\n` : ''}

# 상위 AI 지시

${instruction.trim()}`
}

function sendGroupDocumentInstructionResponse(response, statusCode, reasonCode, message, payload = {}) {
  return sendJson(response, statusCode, groupDocumentInstructionResponseBody(statusCode, reasonCode, message, payload))
}

function groupDocumentInstructionReason(instruction) {
  if (instruction.state === 'queued') return {
    reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_QUEUED',
    message: instruction.message ?? '대상 문서 루트 AI가 현재 응답 중이어서 지시 전문을 대기열에 보관했습니다. 유휴 상태가 되면 같은 지시를 자동 전달합니다.',
  }
  if (instruction.state === 'delivered') return {
    reasonCode: instruction.reasonCode ?? 'GROUP_DOCUMENT_INSTRUCTION_DELIVERED',
    message: instruction.message ?? '그룹 문서 지시 전문을 대상 문서 루트 AI 대화에 전달했습니다. 전달 성공은 문서 업무 완료를 의미하지 않습니다.',
  }
  if (instruction.state === 'replied') return {
    reasonCode: instruction.reasonCode ?? 'GROUP_DOCUMENT_INSTRUCTION_REPLIED',
    message: instruction.message ?? '대상 문서 루트 AI가 지시 전문에 응답했습니다. 응답과 실제 카드·하위 위임 결과를 함께 검수하세요.',
  }
  return {
    reasonCode: instruction.reasonCode ?? 'GROUP_DOCUMENT_INSTRUCTION_FAILED',
    message: instruction.message ?? '그룹 문서 지시 전문을 전달하지 못했습니다.',
  }
}

async function updateGroupDocumentInstruction(id, updates) {
  const current = groupDocumentInstructions.get(id)
  if (!current) return null
  const changed = Object.entries(updates).some(([key, value]) => JSON.stringify(current[key]) !== JSON.stringify(value))
  if (!changed) return current
  const next = { ...current, ...updates, updatedAt: new Date().toISOString() }
  groupDocumentInstructions.set(id, next)
  await persistGroupDocumentInstructions()
  broadcastEvent({ type: 'group-document-instruction-changed', instruction: groupDocumentInstructionPublicView(next) })
  return next
}

async function groupDocumentInstructionMaps(instruction) {
  const [parentMap, targetMap] = await Promise.all([
    readMap(instruction.parentMapId),
    readMap(instruction.targetMapId),
  ])
  const parentCard = parentMap?.nodes.find((node) => node.id === instruction.parentCardId)
  const targetCard = targetMap?.nodes.find((node) => node.id === instruction.targetCardId)
  return { parentMap, targetMap, parentCard, targetCard }
}

async function validateQueuedGroupDocumentInstruction(instruction) {
  const { parentMap, targetMap, parentCard, targetCard } = await groupDocumentInstructionMaps(instruction)
  if (!parentMap || parentMap.trashedAt || !targetMap || targetMap.trashedAt || !parentCard || !targetCard) {
    return { valid: false, reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_CARD_NOT_FOUND', message: '총괄 문서 또는 대상 문서의 루트 카드를 찾을 수 없습니다.' }
  }
  const groupId = await groupProjects.authorizeDocumentInstruction(parentMap, parentCard.id, targetMap, targetCard.id)
  if (groupId !== instruction.groupId) {
    return { valid: false, reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_SCOPE_CHANGED', message: '그룹 소속, 총괄 문서 또는 대상 문서 루트가 변경되어 대기 중인 지시를 전달하지 않았습니다.' }
  }
  const groupContext = await groupProjects.context(groupId)
  if (groupContext.project.version !== instruction.groupProjectVersion
    || parentMap.version !== instruction.sourceRevision
    || targetMap.version !== instruction.targetRevision) {
    return { valid: false, reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_REVISION_CONFLICT', message: '대기 중 그룹 기준 또는 문서 버전이 변경되어 지시를 전달하지 않았습니다. 최신 기준으로 지시 전문을 다시 검토하세요.' }
  }
  return { valid: true, parentMap, targetMap, parentCard, targetCard }
}

async function targetReadyForGroupDocumentInstruction(instruction, targetCard) {
  if (instruction.strategy === 'resume') {
    if (!isAiConversationLinked(targetCard.data, instruction.requestedConversationId)) return false
    try {
      const conversation = await fetchAiConversationRuntime(instruction.requestedConversationId)
      return normalizeAiConversationRuntime(instruction.requestedConversationId, conversation).state === 'idle'
    } catch {
      return false
    }
  }
  const workStates = await aiConversationWorkStates(instruction.targetMapId, [targetCard.id])
  return workStates?.cards?.every((card) => ['idle', 'unlinked'].includes(card.state)) === true
}

async function linkGroupDocumentInstructionConversation({ instruction, targetMap, targetCard, targetConversationId, selection, attribution, user }) {
  rememberAiConversationOrigin({
    conversationId: targetConversationId,
    mapId: targetMap.id,
    cardId: targetCard.id,
    startedBy: attribution.startedBy,
    linkedAt: new Date().toISOString(),
    homeMachineId: instruction.targetHomeMachineId,
  })
  aiConversationAttributions.set(conversationAttributionKey(targetMap.id, targetCard.id), {
    mapId: targetMap.id,
    cardId: targetCard.id,
    conversationId: targetConversationId,
    authorName: attribution.authorName,
    agentId: attribution.agentId,
    agentName: attribution.agentName,
    modelId: attribution.modelId,
    modelName: attribution.modelName,
    providerId: attribution.providerId,
    homeMachineId: instruction.targetHomeMachineId,
    startedBy: attribution.startedBy,
    linkedAt: new Date().toISOString(),
    refreshedAt: new Date().toISOString(),
  })
  await Promise.all([persistAiAttributions(), persistAiConversationAttributions(), persistAiConversationOrigins()])
  if (instruction.strategy !== 'new') return { mapVersion: targetMap.version, linkError: null }

  const latestMap = await readMap(targetMap.id)
  const latestTargetCard = latestMap?.nodes.find((node) => node.id === targetCard.id)
  if (!latestMap || latestMap.trashedAt || !latestTargetCard) {
    return { mapVersion: targetMap.version, linkError: '새 대화는 생성됐지만 대상 문서 루트가 변경되어 연결하지 못했습니다.' }
  }
  const conversationLink = normalizeAiConversationLink({
    conversationId: targetConversationId,
    homeMachineId: instruction.targetHomeMachineId,
    agent: selection.agent,
    model: selection.model,
    providerId: selection.providerId,
    mode: selection.mode,
    thoughtLevel: selection.thoughtLevel,
    skills: selection.enabledSkillIds.map((skillId) => ({ id: skillId, label: skillId })),
    mcpServers: selection.mcpIds.map((mcpId) => ({ id: mcpId, label: mcpId })),
    workspace: selection.workspace,
    requestPreview: instruction.instructionPreview,
    startedBy: { id: attribution.startedBy, label: users.find((candidate) => candidate.id === attribution.startedBy)?.name ?? attribution.startedBy },
    startedAt: new Date().toISOString(),
    linkedAt: new Date().toISOString(),
  })
  try {
    const updatedMap = await saveMap(targetMap.id, {
      nodes: latestMap.nodes.map((node) => node.id === targetCard.id ? {
        ...node,
        data: {
          ...node.data,
          aiConversationId: targetConversationId,
          aiConversations: appendAiConversationLink(node.data, conversationLink),
        },
      } : node),
      edges: latestMap.edges,
    }, user, latestMap.title, latestMap.color, 'content')
    broadcastEvent({
      type: 'ai-conversation-linked', mapId: targetMap.id, nodeId: targetCard.id,
      conversationId: targetConversationId, conversation: conversationLink,
      sourceClientId: null, updatedAt: updatedMap.updatedAt, updatedBy: publicUser(user),
    })
    return { mapVersion: updatedMap.version, linkError: null }
  } catch (error) {
    console.warn('[Group document instruction conversation link]', error)
    return { mapVersion: latestMap.version, linkError: '지시 대화는 생성됐지만 대상 문서 루트의 대화 목록에 연결하지 못했습니다.' }
  }
}

async function dispatchGroupDocumentInstruction(instruction, user) {
  if (groupDocumentInstructionActions.has(instruction.id)) return groupDocumentInstructions.get(instruction.id)
  groupDocumentInstructionActions.add(instruction.id)
  try {
    const validation = await validateQueuedGroupDocumentInstruction(instruction)
    if (!validation.valid) return updateGroupDocumentInstruction(instruction.id, {
      state: 'expired', reasonCode: validation.reasonCode, message: validation.message,
    })
    const { parentMap, targetMap, targetCard } = validation
    if (!await targetReadyForGroupDocumentInstruction(instruction, targetCard)) {
      return updateGroupDocumentInstruction(instruction.id, {
        state: 'queued', reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_TARGET_BUSY',
        message: '대상 문서 루트 AI가 현재 응답 중이거나 상태를 확인할 수 없어 지시 전문을 대기열에 보관했습니다. 유휴 상태가 되면 자동 전달합니다.',
      })
    }
    if (instruction.strategy === 'resume') {
      try {
        const conversation = await fetchAiConversationRuntime(instruction.requestedConversationId)
        const contextHealth = await inspectAiConversationContextHealth(
          instruction.requestedConversationId,
          conversation,
          instruction.targetHomeMachineId,
          { excludeInstructionId: instruction.id },
        )
        if (contextHealth.assessmentId !== instruction.conversationAssessmentId) {
          return updateGroupDocumentInstruction(instruction.id, {
            state: 'expired',
            reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_ASSESSMENT_STALE',
            message: '대기 중 대상 문서 AI 대화가 변경되어 지시를 전달하지 않았습니다. 최신 대화 후보와 문맥 상태를 다시 확인하세요.',
            conversationContextHealth: contextHealth,
          })
        }
        if (!contextHealth.resumeAllowed) {
          return updateGroupDocumentInstruction(instruction.id, {
            state: 'expired',
            reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_CONTEXT_UNAVAILABLE',
            message: contextHealth.message,
            conversationContextHealth: contextHealth,
          })
        }
      } catch {
        return updateGroupDocumentInstruction(instruction.id, {
          state: 'queued',
          reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_ASSESSMENT_UNAVAILABLE',
          message: '대상 문서 AI 대화의 최신 문맥 상태를 확인하지 못해 지시 전달을 대기합니다.',
        })
      }
    }

    const selection = aiDelegationSelectionFromSource(instruction.pendingSelection)
    if (!selection) return updateGroupDocumentInstruction(instruction.id, {
      state: 'failed', reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_SELECTION_INVALID',
      message: '대상 문서 루트 AI의 실행 환경을 복원할 수 없어 지시 전문을 전달하지 못했습니다.',
    })
    const { token: attributionToken, attribution } = issueDelegatedAttribution({
      mapId: targetMap.id,
      cardId: targetCard.id,
      conversationId: instruction.strategy === 'resume' ? instruction.requestedConversationId : null,
      selection,
      startedBy: instruction.startedBy ?? user.id,
      homeMachineId: instruction.targetHomeMachineId,
    })
    await persistAiAttributions()
    const deliveredInstruction = buildGroupDocumentInstruction({
      groupId: instruction.groupId,
      parentMapId: parentMap.id,
      targetMapId: targetMap.id,
      targetCardId: targetCard.id,
      targetRevision: instruction.targetRevision,
      groupProjectVersion: instruction.groupProjectVersion,
      instructionId: instruction.id,
      instructionType: instruction.instructionType,
      approvalScope: instruction.approvalScope,
      approvalEvidence: instruction.pendingApprovalEvidence,
      instruction: instruction.pendingInstruction,
      editorId: attribution.startedBy,
      attributionToken,
      parentConversationId: instruction.parentConversationId,
      replyTarget: instruction.replyTarget,
      documentCoordinatorInstruction: DOCUMENT_COORDINATOR_INSTRUCTION,
    })
    const operationId = groupDocumentInstructionOperationId(instruction.id)
    let dispatch
    try {
      dispatch = await fetchAionUiOn(instruction.targetHomeMachineId, '/api/internal/external-conversation-dispatches', {
        method: 'POST',
        timeoutMs: 30_000,
        body: {
          operationId,
          actorConversationId: instruction.parentConversationId,
          strategy: instruction.strategy,
          ...(instruction.strategy === 'resume'
            ? { targetConversationId: instruction.requestedConversationId }
            : { create: {
                agentId: selection.agent.id,
                title: formatAiConversationTitle(targetMap.title, targetCard.data?.label ?? targetCard.id),
                modelId: selection.model.id,
                mode: selection.mode?.id ?? null,
                thoughtLevel: selection.thoughtLevel?.id ?? null,
                enabledSkillIds: selection.enabledSkillIds,
                disabledBuiltinSkillIds: selection.disabledBuiltinSkillIds,
                mcpIds: selection.mcpIds,
                workspace: selection.workspace,
              } }),
          instruction: deliveredInstruction,
        },
      })
    } catch (error) {
      try {
        dispatch = await fetchAionUiOn(instruction.targetHomeMachineId, `/api/internal/external-conversation-dispatches/${encodeURIComponent(operationId)}`)
      } catch {
        // 요청이 도착하지 않았거나 대상 대화가 아직 바쁘면 아래에서 대기 또는 실패로 기록합니다.
      }
      if (!dispatch) {
        aiAttributions.delete(sessionTokenKey(attributionToken))
        await persistAiAttributions()
        if (error?.status === 409 || error?.status === 429) return updateGroupDocumentInstruction(instruction.id, {
          state: 'queued', reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_TARGET_BUSY',
          message: '대상 문서 루트 AI가 현재 응답 중이어서 지시 전문을 대기열에 보관했습니다. 유휴 상태가 되면 자동 전달합니다.',
        })
        return updateGroupDocumentInstruction(instruction.id, {
          state: 'failed', reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_DISPATCH_FAILED',
          message: 'AionUi에 그룹 문서 지시 전문을 전달하지 못했습니다.',
        })
      }
    }

    const targetConversationId = String(dispatch.conversationId ?? '').trim()
    if (!validAiConversationId(targetConversationId)) {
      aiAttributions.delete(sessionTokenKey(attributionToken))
      await persistAiAttributions()
      return updateGroupDocumentInstruction(instruction.id, {
        state: 'failed', reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_INVALID',
        message: 'AionUi가 지시를 전달할 유효한 대상 대화 ID를 반환하지 않았습니다.',
      })
    }
    attribution.conversationId = targetConversationId
    if (instruction.strategy === 'new') {
      try {
        await protectAionUiConversationTitle(targetConversationId, formatAiConversationTitle(targetMap.title, targetCard.data?.label ?? targetCard.id), instruction.targetHomeMachineId)
      } catch (error) {
        console.warn('[Group document instruction conversation title protection]', error)
      }
    }
    const linked = await linkGroupDocumentInstructionConversation({
      instruction, targetMap, targetCard, targetConversationId, selection, attribution, user,
    })
    return updateGroupDocumentInstruction(instruction.id, {
      state: 'delivered',
      reasonCode: linked.linkError ? 'GROUP_DOCUMENT_INSTRUCTION_DELIVERED_WITH_LINK_WARNING' : 'GROUP_DOCUMENT_INSTRUCTION_DELIVERED',
      message: linked.linkError
        ? `${linked.linkError} 지시 전문은 전달됐으며 연결 상태를 확인해 주세요.`
        : '그룹 문서 지시 전문을 대상 문서 루트 AI 대화에 전달했습니다. 전달 성공은 문서 업무 완료를 의미하지 않습니다.',
      targetConversationId,
      dispatchOperationId: operationId,
      dispatchState: dispatch.state ?? 'starting',
      turnId: dispatch.turnId ?? null,
      deliveredAt: new Date().toISOString(),
      mapVersion: linked.mapVersion,
      linkError: linked.linkError,
      instruction: instruction.pendingInstruction,
      approvalEvidence: instruction.pendingApprovalEvidence,
      pendingInstruction: null,
      pendingApprovalEvidence: null,
      pendingSelection: null,
    })
  } finally {
    groupDocumentInstructionActions.delete(instruction.id)
  }
}

async function pollGroupDocumentInstructions() {
  if (groupDocumentInstructionPollRunning) return
  groupDocumentInstructionPollRunning = true
  try {
    for (const instruction of [...groupDocumentInstructions.values()]) {
      if (groupDocumentInstructionActions.has(instruction.id)) continue
      if (instruction.state === 'queued') {
        const user = users.find((candidate) => candidate.id === instruction.startedBy) ?? users[0]
        if (user) await dispatchGroupDocumentInstruction(instruction, user)
        continue
      }
      if (instruction.state !== 'delivered' || !instruction.dispatchOperationId) continue
      try {
        const status = await fetchAionUiOn(instruction.targetHomeMachineId, `/api/internal/external-conversation-dispatches/${encodeURIComponent(instruction.dispatchOperationId)}`)
        if (['starting', 'waiting_resource', 'running', 'waiting_resume'].includes(status.state)) {
          await updateGroupDocumentInstruction(instruction.id, {
            dispatchState: status.state,
            turnId: status.turnId ?? instruction.turnId ?? null,
          })
          continue
        }
        if (status.state === 'completed') {
          const response = await latestAssistantResult(instruction.targetConversationId)
          await updateGroupDocumentInstruction(instruction.id, {
            state: 'replied',
            reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_REPLIED',
            message: response
              ? '대상 문서 루트 AI가 지시 전문에 응답했습니다. 응답과 실제 카드·하위 위임 결과를 함께 검수하세요.'
              : '대상 문서 루트 AI의 지시 응답이 끝났지만 응답 원문을 캡처하지 못했습니다. 대상 대화와 실제 카드를 확인하세요.',
            dispatchState: 'completed',
            turnId: status.turnId ?? instruction.turnId ?? null,
            response,
            responseHash: response ? createHash('sha256').update(response).digest('hex') : null,
            repliedAt: new Date().toISOString(),
          })
          continue
        }
        await updateGroupDocumentInstruction(instruction.id, {
          state: 'failed',
          reasonCode: status.state === 'recovery_required'
            ? 'GROUP_DOCUMENT_INSTRUCTION_INTERRUPTED'
            : 'GROUP_DOCUMENT_INSTRUCTION_EXECUTION_FAILED',
          message: status.state === 'recovery_required'
            ? 'AionCore 재시작으로 문서 AI의 지시 응답이 중단됐습니다. 대상 대화를 확인한 뒤 새 지시가 필요한지 판단하세요.'
            : status.errorMessage ?? '대상 문서 루트 AI가 지시 전문에 응답하지 못했습니다.',
          dispatchState: status.state ?? 'failed',
          turnId: status.turnId ?? instruction.turnId ?? null,
        })
      } catch (error) {
        if (error?.status !== 404) continue
        await updateGroupDocumentInstruction(instruction.id, {
          state: 'failed',
          reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_STATUS_LOST',
          message: 'AionUi가 전달된 지시의 응답 상태를 더 이상 보유하지 않습니다. 같은 지시를 자동 재실행하지 않았습니다.',
        })
      }
    }
  } finally {
    groupDocumentInstructionPollRunning = false
  }
}

function delegationRecoveryInstruction(delegation, instruction, recovery = null, conversationDisplayLabel = delegation.targetConversationId) {
  const inspection = delegation.coordinationOnly
    ? `${DOCUMENT_COORDINATOR_INSTRUCTION}\n\n먼저 그룹 기준, 현재 문서의 실행 계약, 하위 위임 상태와 최근 대화·카드 결과를 대조하세요. 이 조정 업무에는 worker가 배정되지 않으므로 작업공간을 임의로 점유하거나 새 lease를 만들지 마세요.`
    : '먼저 `.ai-session.json`, 현재 브랜치, Git 변경과 최근 대화·카드 결과를 서로 대조하세요. 다른 작업공간으로 이동하거나 새 lease를 만들지 마세요.'
  const externalLimitRecovery = ['usage-limit', 'rate-limit', 'model-capacity'].includes(recovery?.failureCategory)
  const userStopRecovery = recovery?.failureCategory === 'user-stop'
  const title = recovery?.failureCategory === 'model-capacity'
    ? '모델 실행 용량 확보 후 위임 복구'
    : externalLimitRecovery ? '외부 사용량 제한 해제 후 위임 복구'
      : userStopRecovery ? '사용자 중지 후 위임 재개' : '재시작 후 위임 복구'
  const reason = externalLimitRecovery
    ? `이전 실행은 ${recovery.failureCategory === 'rate-limit' ? '요청 한도' : recovery.failureCategory === 'model-capacity' ? '선택 모델의 실행 용량 부족' : '사용량 한도'}로 중단됐고, 사용자가 원인 해소를 확인한 뒤 같은 대화와 작업공간의 재개를 요청했습니다.`
    : userStopRecovery ? '사용자가 중지했던 기존 위임을 같은 대화에서 다시 이어가도록 요청했습니다.'
      : 'AionCore 또는 MindNProgress 재시작으로 이전 실행의 메모리 상태가 끊겼습니다.'
  const workspaceLease = delegation.workspaceLease
  const workspaceSummary = delegation.coordinationOnly
    ? '- 현재 작업공간 배정: 문서 조정 전용 · worker 배정 없음'
    : workspaceLease
      ? `- 현재 workspaceId: \`${workspaceLease.workspaceId ?? '미확인'}\`
- 현재 jobId: \`${workspaceLease.jobId ?? '미확인'}\`
- 현재 leaseId: \`${workspaceLease.leaseId ?? '미확인'}\`
- 현재 projectRoot: \`${workspaceLease.projectRoot ?? '미확인'}\`
- 현재 branch: \`${workspaceLease.branch ?? '미확인'}\`
- 현재 baseCommit: \`${workspaceLease.baseCommit ?? '미확인'}\``
      : '- 현재 작업공간 배정: 기존 대화 작업공간 · 등록된 worker lease 없음'
  const workspaceRecoveryRule = delegation.coordinationOnly
    ? ''
    : '\n복구 작업에서도 이번 전문의 `# 할당된 작업공간`에 기재된 현재 배정만 사용하세요. 대화 기록에 남은 이전 경로·브랜치·lease를 복구 후보로 사용하지 마세요.'
  return `# ${title}

${reason} 원래 지시를 처음부터 반복하지 말고, 아래 복구 확인 절차에 따라 미완료 부분만 이어서 수행하세요.

- 위임 ID: ${delegation.id}
- 대상 카드: ${delegation.targetCardLabel} (${delegation.targetCardId})
- 대상 대화: ${conversationDisplayLabel}
${workspaceSummary}

${inspection}${workspaceRecoveryRule}
현재 상태와 아래 복구 지시를 대조하고 원래 맡긴 범위의 미완료 작업만 이어가세요. 범위를 벗어난 변경이 필요하면 상위 AI에 보고하세요. 분석·제안 위임의 복구는 계속 분석·제안만 허용됩니다.
이미 완료된 변경이나 외부 처리는 중복 실행하지 말고 검증과 결과 보고만 하세요.

# 복구 후 수행 지시

${instruction.trim()}`
}

function delegationPublicView(delegation, includeResult = false) {
  const publicDelegation = { ...delegation }
  delete publicDelegation.instructionHash
  delete publicDelegation.recoveryInstructionHash
  delete publicDelegation.requestSignature
  delete publicDelegation.pendingInstruction
  delete publicDelegation.pendingSelection
  delete publicDelegation.pendingWorkspaceHint
  delete publicDelegation.childResultSnapshot
  if (publicDelegation.reportArchive) {
    const { content: _content, ...metadata } = publicDelegation.reportArchive
    publicDelegation.reportArchive = metadata
  }
  publicDelegation.reportArchived = aiDelegationReportArchived(delegation)
  publicDelegation.reportArchivePending = aiDelegationReportArchivePending(delegation)
  const recovery = aiDelegationRecoveryAvailability(delegation)
  if (recovery) publicDelegation.recovery = recovery
  const closure = aiDelegationClosureAvailability(delegation)
  if (closure) publicDelegation.closure = closure
  publicDelegation.displayState = aiDelegationDisplayState(delegation)
  Object.assign(publicDelegation, aiDelegationStateReason(delegation))
  publicDelegation.workCompleted = aiDelegationSucceeded(delegation)
  publicDelegation.reportStatus = aiDelegationReportStatus(delegation)
  publicDelegation.reportPending = !aiDelegationIsTerminal(delegation)
    && aiDelegationSucceeded(delegation) && publicDelegation.reportStatus !== 'received'
  const result = aiDelegationReportResult(delegation)
  publicDelegation.resultAvailability = result.availability
  if (includeResult === true) {
    publicDelegation.result = result.text
    publicDelegation.resultHash = result.hash
    publicDelegation.resultTurnId = result.turnId
  }
  return publicDelegation
}

async function loadGroupDocumentInstructions() {
  const storedInstructions = await readStoredArray(groupDocumentInstructionsFile)
  let rejectedCount = 0
  for (const instruction of storedInstructions) {
    if (!isValidGroupDocumentInstructionId(instruction?.id)
      || !isValidMapId(instruction?.parentMapId)
      || !isValidMapId(instruction?.targetMapId)
      || typeof instruction?.parentCardId !== 'string'
      || typeof instruction?.targetCardId !== 'string'
      || typeof instruction?.parentConversationId !== 'string'
      || !['queued', 'delivered', 'replied', 'failed', 'cancelled', 'expired'].includes(instruction?.state)) {
      rejectedCount += 1
      continue
    }
    groupDocumentInstructions.set(instruction.id, instruction)
  }
  if (rejectedCount > 0) {
    console.warn(`[Group document instruction storage] ${rejectedCount}개 항목을 무시했으며 원본 파일은 덮어쓰지 않았습니다.`)
  }
}

function sendAiDelegationResponse(response, statusCode, reasonCode, message, payload = {}) {
  return sendJson(
    response,
    statusCode,
    aiDelegationResponseBody(statusCode, reasonCode, message, payload),
  )
}

function delegationTargetMachineId(delegation) {
  return normalizeMachineId(delegation?.targetHomeMachineId)
