async function resolveAiDelegationWorkspacePool({ selection, targetCard, parentAttribution, requested }) {
  const selectedWorkspace = String(selection?.workspace ?? '').trim()
  if (selectedWorkspace) return { known: true, workspaceHint: selectedWorkspace,
    expectsWorkspacePool: Boolean(workspacePoolManager.poolForWorkspace(selectedWorkspace)) }
  const candidates = [
    selection?.workspace,
    requested?.workspace,
    ...aiConversationLinksFromData(targetCard?.data).map((link) => link.workspace),
    parentAttribution?.selection?.workspace,
    parentAttribution?.workspace,
  ].map((candidate) => String(candidate ?? '').trim()).filter(Boolean)
  const directHint = candidates.find((candidate) => workspacePoolManager.poolForWorkspace(candidate)) ?? null
  if (directHint) return { known: true, workspaceHint: directHint, expectsWorkspacePool: true }

  const parentConversationId = String(parentAttribution?.conversationId ?? '').trim()
  if (validAiConversationId(parentConversationId)) {
    try {
      const conversation = await fetchAiConversationRuntime(parentConversationId)
      const liveWorkspace = aiConversationLinkFromAionUiConversation(conversation)?.workspace ?? null
      if (liveWorkspace) {
        const pool = workspacePoolManager.poolForWorkspace(liveWorkspace)
        rememberAiConversationOrigin({
          ...(aiConversationOrigins.get(parentConversationId) ?? {}),
          conversationId: parentConversationId,
          mapId: parentAttribution.mapId,
          cardId: parentAttribution.cardId,
          startedBy: parentAttribution.startedBy,
          linkedAt: aiConversationOrigins.get(parentConversationId)?.linkedAt ?? new Date().toISOString(),
          workspace: liveWorkspace,
          workspacePoolId: pool?.poolId ?? null,
        })
        await persistAiConversationOrigins()
        if (pool) return { known: true, workspaceHint: liveWorkspace, expectsWorkspacePool: true }
        return { known: true, workspaceHint: null, expectsWorkspacePool: false }
      }
    } catch {
      // 명시적으로 저장된 workspace 후보가 있으면 해당 경로를 기준으로 비-pool 여부를 판단합니다.
    }
  }

  if (candidates.length > 0 || workspacePoolManager.publicSnapshot().available !== true) {
    return { known: true, workspaceHint: null, expectsWorkspacePool: false }
  }
  return { known: false, workspaceHint: null, expectsWorkspacePool: false }
}

function aiDelegationDispatchError(message, status = 503, code = 'AI_DELEGATION_DISPATCH_FAILED') {
  const error = new Error(message)
  error.status = status
  error.code = code
  return error
}

function aiDelegationWorkspaceLeaseError(message, expected, actual) {
  const error = aiDelegationDispatchError(message, 409, 'AI_WORKSPACE_LEASE_MISMATCH')
  error.details = {
    expectedLeaseId: expected?.leaseId ?? null,
    expectedWorkspaceId: expected?.workspaceId ?? null,
    actualLeaseId: actual?.leaseId ?? null,
    actualWorkspaceId: actual?.workspaceId ?? null,
    mismatchedFields: ['workspaceId', 'jobId', 'leaseId', 'projectRoot', 'branch'].filter((key) => {
      if (key === 'branch') return Boolean(expected?.branch && Object.hasOwn(actual ?? {}, key) && expected[key] !== actual[key])
      if (typeof expected?.[key] !== 'string' || !expected[key].trim() || typeof actual?.[key] !== 'string' || !actual[key].trim()) return true
      if (key === 'projectRoot') return !sameExecutionWorkspace(expected[key], actual[key])
      return expected[key] !== actual[key]
    }),
  }
  return error
}

async function updateAiDelegation(id, updates) {
  const current = aiDelegations.get(id)
  if (!current) return null
  const changed = Object.entries(updates).some(([key, value]) => JSON.stringify(current[key]) !== JSON.stringify(value))
  if (!changed) return current
  const next = { ...current, ...updates, updatedAt: new Date().toISOString() }
  aiDelegations.set(id, next)
  await persistAiDelegations()
  broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(next) })
  return next
}

async function restoreAiDelegationResumeReservation(delegation, error) {
  if (!delegation || aiDelegations.get(delegation.id)?.state !== 'resuming') return
  await updateAiDelegation(delegation.id, {
    state: 'waiting-child-resume',
    resumingByDelegationId: null,
    resumeError: error?.message ?? String(error ?? 'AI 위임 재개를 완료하지 못했습니다.'),
  })
}

async function dispatchPreparedAiDelegation({
  queuedDelegation = null,
  id,
  requestSignature,
  map,
  parentCard,
  targetCard,
  parentAttribution,
  targetConversationId: requestedConversationId,
  strategy,
  decisionReason,
  sourceRevision,
  instruction,
  selection,
  workspaceLease,
  resumedDelegation,
  user,
  expectsWorkspacePool = false,
  parentHomeMachineId = conversationHomeMachineId(parentAttribution?.conversationId),
  targetHomeMachineId = machineRegistry.mainMachineId,
}) {
  if (!await aionCoreSupportsExplicitCompletionAfterInterruption(targetHomeMachineId)) {
    throw aiDelegationDispatchError(
      '현재 AionCore가 중단 후 명시적 완료 신호를 지원하지 않습니다. AionCore를 최신 빌드로 재기동해 주세요.',
      503,
      'AIONCORE_EXPLICIT_COMPLETION_UNAVAILABLE',
    )
  }
  if (expectsWorkspacePool && !workspaceLease) {
    throw aiDelegationDispatchError(
      '등록된 AI 작업공간 풀의 lease 없이 작업을 시작할 수 없습니다.',
      503,
      'AI_WORKSPACE_LEASE_REQUIRED',
    )
  }

  let targetConversationId = requestedConversationId
  let reservedDelegation = resumedDelegation
  if (reservedDelegation && aiDelegations.get(reservedDelegation.id)?.state !== 'resuming') {
    reservedDelegation = await updateAiDelegation(reservedDelegation.id, {
      state: 'resuming',
      resumingByDelegationId: id,
      resumeRequestedAt: new Date().toISOString(),
    })
  }

  const { token: attributionToken, attribution } = issueDelegatedAttribution({
    mapId: map.id,
    cardId: targetCard.id,
    conversationId: strategy === 'resume' ? targetConversationId : null,
    selection,
    startedBy: parentAttribution.startedBy ?? user.id,
    homeMachineId: targetHomeMachineId,
  })
  await persistAiAttributions()
  const delegatedInstruction = buildDelegatedInstruction({
    mapId: map.id,
    cardId: targetCard.id,
    editorId: parentAttribution.startedBy ?? user.id,
    attributionToken,
    instruction,
    workspaceLease,
  })
  const delegatedConversationTitle = strategy === 'new'
    ? formatAiConversationTitle(map.title, targetCard.data?.label ?? targetCard.id)
    : null

  let dispatch
  try {
    dispatch = await fetchAionUiOn(targetHomeMachineId, '/api/internal/external-conversation-dispatches', {
      method: 'POST',
      timeoutMs: 30_000,
      body: {
        operationId: id,
        actorConversationId: parentAttribution.conversationId,
        strategy,
        explicitCompletionAfterInterruption: true,
        ...(workspaceLease ? { workspaceLease } : {}),
        ...(strategy === 'resume' ? { targetConversationId } : {
          create: {
            agentId: selection.agent.id,
            title: delegatedConversationTitle,
            modelId: selection.model.id,
            mode: selection.mode?.id ?? null,
            thoughtLevel: selection.thoughtLevel?.id ?? null,
            enabledSkillIds: selection.enabledSkillIds,
            disabledBuiltinSkillIds: selection.disabledBuiltinSkillIds,
            mcpIds: selection.mcpIds,
            workspace: selection.workspace,
          },
        }),
        instruction: delegatedInstruction,
      },
    })
  } catch (error) {
    for (let attempt = 0; attempt < 10 && !dispatch; attempt += 1) {
      if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, 500))
      try {
        dispatch = await fetchAionUiOn(targetHomeMachineId, `/api/internal/external-conversation-dispatches/${encodeURIComponent(id)}`)
      } catch {
        // The POST may have reached AionCore even if its response was lost.
      }
    }
    if (!dispatch) {
      aiAttributions.delete(sessionTokenKey(attributionToken))
      const definitelyRejected = Number.isInteger(error?.status)
        && error.status >= 400 && error.status < 500 && error.status !== 409 && error.status !== 429
      await restoreAiDelegationResumeReservation(reservedDelegation, error)
      await Promise.all([
        persistAiAttributions(),
        workspaceLease && !reservedDelegation
          ? (definitelyRejected
              ? workspacePoolManager.cancel(workspaceLease.leaseId, 'AionCore가 위임 요청을 실행 전에 거부했습니다.')
              : workspacePoolManager.quarantine(workspaceLease.leaseId, 'AionUi 위임 요청의 실행 여부를 확인하지 못했습니다.'))
          : Promise.resolve(),
      ])
      throw aiDelegationDispatchError(
        error?.status === 409
          ? '대상 AI 대화가 이미 작업 중이거나 같은 위임 요청이 준비 중입니다.'
          : 'AionUi에 AI 작업을 위임하지 못했습니다.',
        error?.status === 409 ? 409 : 503,
      )
    }
  }

  if (!aiDelegationWorkspaceLeaseMatches(workspaceLease, dispatch?.workspaceLease ?? null)) {
    aiAttributions.delete(sessionTokenKey(attributionToken))
    await restoreAiDelegationResumeReservation(reservedDelegation, 'AionCore의 작업공간 lease가 요청과 일치하지 않습니다.')
    await Promise.all([
      persistAiAttributions(),
      workspaceLease && !reservedDelegation
        ? workspacePoolManager.quarantine(
            workspaceLease.leaseId,
            'AionCore가 보고한 작업공간 lease와 MindNProgress 요청이 일치하지 않습니다.',
          )
        : Promise.resolve(),
    ])
    throw aiDelegationWorkspaceLeaseError(
      workspaceLease
        ? 'AionCore가 보고한 작업공간 lease가 MindNProgress 요청과 일치하지 않습니다.'
        : '동일한 위임 ID가 작업공간 lease를 사용하는 다른 실행에 연결되어 있습니다.',
      workspaceLease,
      dispatch?.workspaceLease ?? null,
    )
  }

  targetConversationId = String(dispatch.conversationId ?? '').trim()
  if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(targetConversationId)) {
    await restoreAiDelegationResumeReservation(reservedDelegation, 'AionUi가 유효한 위임 대화 ID를 반환하지 않았습니다.')
    if (workspaceLease && !reservedDelegation) {
      await workspacePoolManager.quarantine(workspaceLease.leaseId, 'AionUi가 유효한 위임 대화 ID를 반환하지 않았습니다.')
    }
    throw aiDelegationDispatchError('AionUi가 위임 대화 ID를 반환하지 않았습니다.')
  }
  if (workspaceLease) {
    try {
      workspaceLease = await workspacePoolManager.bindConversation(workspaceLease.leaseId, targetConversationId)
        ?? workspaceLease
    } catch (error) {
      await workspacePoolManager.quarantine(
        workspaceLease.leaseId,
        `AI 작업공간과 대화 연결을 확정하지 못했습니다: ${error?.message ?? String(error)}`,
      )
      const bindingError = aiDelegationDispatchError(
        'AI 작업공간과 대상 대화의 연결을 확정하지 못했습니다.',
        409,
        'AI_WORKSPACE_CONVERSATION_CONFLICT',
      )
      bindingError.details = { leaseId: workspaceLease.leaseId, conversationId: targetConversationId }
      throw bindingError
    }
  }
  if (delegatedConversationTitle) {
    try {
      await protectAionUiConversationTitle(targetConversationId, delegatedConversationTitle, targetHomeMachineId)
    } catch (error) {
      console.warn('[AI delegation conversation title protection]', JSON.stringify({
        mapId: map.id,
        cardId: targetCard.id,
        conversationId: targetConversationId,
        error: error?.message ?? String(error),
      }))
    }
  }

  attribution.conversationId = targetConversationId
  rememberAiConversationOrigin({
    conversationId: targetConversationId,
    mapId: map.id,
    cardId: targetCard.id,
    startedBy: attribution.startedBy,
    linkedAt: new Date().toISOString(),
    workspace: selection.workspace,
    workspacePoolId: workspaceLease?.poolId ?? null,
    homeMachineId: targetHomeMachineId,
  })
  aiConversationAttributions.set(conversationAttributionKey(map.id, targetCard.id), {
    mapId: map.id,
    cardId: targetCard.id,
    conversationId: targetConversationId,
    authorName: attribution.authorName,
    agentId: attribution.agentId,
    agentName: attribution.agentName,
    modelId: attribution.modelId,
    modelName: attribution.modelName,
    providerId: attribution.providerId,
    homeMachineId: targetHomeMachineId,
    startedBy: attribution.startedBy,
    linkedAt: new Date().toISOString(),
    refreshedAt: new Date().toISOString(),
  })
  await Promise.all([persistAiAttributions(), persistAiConversationAttributions(), persistAiConversationOrigins()])

  let updatedMap = map
  let linkError = null
  if (strategy === 'new') {
    const latestMap = await readMap(map.id)
    const latestTargetCard = latestMap?.nodes.find((node) => node.id === targetCard.id)
    if (!latestMap || latestMap.trashedAt || !latestTargetCard) {
      linkError = '새 대화는 생성됐지만 대상 카드가 변경되어 연결하지 못했습니다.'
    } else {
      const conversationLink = normalizeAiConversationLink({
        conversationId: targetConversationId,
        homeMachineId: targetHomeMachineId,
        agent: selection.agent,
        model: selection.model,
        providerId: selection.providerId,
        mode: selection.mode,
        thoughtLevel: selection.thoughtLevel,
        skills: selection.enabledSkillIds.map((skillId) => ({ id: skillId, label: skillId })),
        mcpServers: selection.mcpIds.map((mcpId) => ({ id: mcpId, label: mcpId })),
        workspace: selection.workspace,
        requestPreview: instruction,
        startedBy: { id: attribution.startedBy, label: users.find((candidate) => candidate.id === attribution.startedBy)?.name ?? attribution.startedBy },
        startedAt: new Date().toISOString(),
        linkedAt: new Date().toISOString(),
      })
      try {
        updatedMap = await saveMap(map.id, {
          nodes: latestMap.nodes.map((node) => node.id === targetCard.id ? {
            ...node,
            data: {
              ...node.data,
              aiConversationId: targetConversationId,
              aiConversations: appendAiConversationLink(node.data, conversationLink),
            },
          } : node),
          edges: latestMap.edges,
        }, user, latestMap.title, latestMap.color, 'content')
        broadcastEvent({
          type: 'ai-conversation-linked', mapId: map.id, nodeId: targetCard.id,
          conversationId: targetConversationId, conversation: conversationLink,
          sourceClientId: null, updatedAt: updatedMap.updatedAt, updatedBy: publicUser(user),
        })
      } catch (error) {
        linkError = '새 대화는 생성됐지만 대상 카드의 대화 목록에 연결하지 못했습니다.'
        console.warn('[AI delegation conversation link]', error)
      }
    }
  }

  const now = new Date().toISOString()
  const delegation = {
    ...(queuedDelegation ?? {}),
    id,
    requestSignature,
    mapId: map.id,
    parentCardId: parentCard.id,
    parentCardLabel: parentCard.data?.label ?? parentCard.id,
    targetCardId: targetCard.id,
    targetCardLabel: targetCard.data?.label ?? targetCard.id,
    parentConversationId: parentAttribution.conversationId,
    parentHomeMachineId,
    targetConversationId,
    targetHomeMachineId,
    childOperationId: id,
    strategy,
    conversationAssessmentId: strategy === 'resume' ? queuedDelegation?.conversationAssessmentId ?? null : null,
    decisionReason,
    sourceRevision,
    instructionPreview: instruction.replace(/\s+/g, ' ').slice(0, 240),
    instructionHash: createHash('sha256').update(instruction).digest('hex'),
    ...initialAiDelegationRuntime(dispatch, now),
    linkError,
    startedBy: attribution.startedBy,
    workspaceLease,
    ...(reservedDelegation ? { resumesDelegationId: reservedDelegation.id } : {}),
    createdAt: queuedDelegation?.createdAt ?? now,
    updatedAt: now,
    ...(queuedDelegation ? { workspaceWaitCompletedAt: now } : {}),
  }
  delete delegation.pendingInstruction
  delete delegation.pendingSelection
  delete delegation.pendingWorkspaceHint
  delete delegation.workspaceWaitError
  if (reservedDelegation) {
    const superseded = {
      ...reservedDelegation,
      state: 'superseded',
      supersededByDelegationId: id,
      supersededAt: now,
      resumingByDelegationId: null,
      updatedAt: now,
    }
    aiDelegations.set(superseded.id, superseded)
    broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(superseded) })
  }
  aiDelegations.set(id, delegation)
  await persistAiDelegations()
  broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(delegation) })
  return { delegation, updatedMap }
}

async function reconcileAiDelegationWorkspaceLeases() {
  const legacyIntegrationDirtyFailures = [...aiDelegations.values()].filter((delegation) =>
    delegation.state === 'failed'
    && delegation.childStatus === 'rejected'
    && !delegation.workspaceLease?.leaseId
    && delegation.childError === integrationWorktreeDirtyMessage
    && delegation.workspaceWaitError === integrationWorktreeDirtyMessage
    && typeof delegation.pendingInstruction === 'string'
    && delegation.pendingInstruction.trim()
    && delegation.pendingSelection
    && typeof delegation.pendingSelection === 'object')
  if (legacyIntegrationDirtyFailures.length > 0) {
    try {
      const integrationChanges = await workspacePoolManager.integrationTrackedChanges()
      const snapshot = workspacePoolManager.publicSnapshot()
      for (const delegation of legacyIntegrationDirtyFailures) {
        const now = new Date().toISOString()
        await updateAiDelegation(delegation.id, {
          state: integrationChanges.dirty ? 'waiting-integration-clean' : 'waiting-workspace',
          childStatus: null,
          childError: null,
          workspaceWaitError: integrationChanges.dirty ? integrationWorktreeDirtyMessage : null,
          integrationCleanTrackedChanges: integrationChanges.paths,
          integrationCleanWaitStartedAt: delegation.integrationCleanWaitStartedAt ?? now,
          legacyIntegrationCleanRecoveredAt: now,
          resource: {
            kind: integrationChanges.dirty ? 'integration_workspace' : 'workspace_pool',
            key: integrationChanges.dirty ? snapshot.integrationWorkspaceId : snapshot.poolId,
            projectRoot: delegation.pendingWorkspaceHint,
          },
          completedAt: null,
        })
      }
    } catch (error) {
      console.warn('[AI delegation integration clean startup recovery]', error)
    }
  }

  for (const delegation of aiDelegations.values()) {
    if (delegation.state !== 'resuming') continue
    await updateAiDelegation(delegation.id, {
      state: 'waiting-child-resume',
      resumingByDelegationId: null,
      resumeError: 'MindNProgress 재시작으로 완료되지 않은 재개 예약을 해제했습니다.',
    })
  }

  for (const delegation of aiDelegations.values()) {
    if (delegation.state !== 'failed'
      || delegation.childStatus !== 'completed'
      || delegation.workspaceResult?.status !== 'quarantined'
      || delegation.pendingRecovery
      || !delegation.workspaceLease?.leaseId) continue
    if (activeAiDelegationsForConversation(aiDelegations.values(), {
      mapId: delegation.mapId, targetCardId: delegation.targetCardId,
      targetConversationId: delegation.targetConversationId, excludeId: delegation.id,
    }).length) continue
    try {
      const workspaceResult = await workspacePoolManager.recoverUntrackedIntegrationFailure(
        delegation.workspaceLease.leaseId,
      ) ?? await workspacePoolManager.recoverCheckpointedFinalizationFailure(
        delegation.workspaceLease.leaseId,
      ) ?? await workspacePoolManager.recoverLegacyDirtyIntegration(delegation.workspaceLease.leaseId)
      if (workspaceResult?.status !== 'waiting-integration') continue
      await updateAiDelegation(delegation.id, {
        state: 'waiting-integration',
        childError: workspaceResult.childError ?? null,
        workspaceResult,
        workspaceError: null,
        parentDispatchState: null,
        parentTurnId: null,
        parentError: null,
        parentResource: null,
        wakeOperationId: null,
        reportReceipt: null, reportWaitReason: null, reportArchive: null,
        reportPayloadHash: null, reportResultAvailability: null, reportResultHash: null,
        reportResultTurnId: null, reportPreparedAt: null,
        attemptHistory: aiDelegationAttemptHistory(delegation, '보존된 체크포인트와 통합 브랜치 검증 후 자동 통합 대기로 복구'),
        completedAt: null,
        legacyIntegrationRecoveredAt: new Date().toISOString(),
      })
      console.log(`[AI workspace pool] 체크포인트가 보존된 격리 작업을 통합 대기로 복구했습니다: ${delegation.id}`)
    } catch (error) {
      console.warn('[AI workspace pool checkpointed integration recovery]', JSON.stringify({
        delegationId: delegation.id,
        leaseId: delegation.workspaceLease.leaseId,
        error: error?.message ?? String(error),
      }))
    }
  }

  const delegations = [...aiDelegations.values()]
  if (await aionCoreSupportsWorkspaceLease()) {
    for (const delegation of delegations) {
      const suspiciousTerminalWorkspace = delegation.state === 'completed'
        && delegation.childStatus === 'completed'
        && ['failed-clean', 'cancelled', 'quarantined'].includes(delegation.workspaceResult?.status)
      if ((!shouldReconcileAiDelegationChildWorkspace(delegation) && !suspiciousTerminalWorkspace)
        || !delegation.childOperationId
        || !delegation.targetConversationId) continue
      try {
        const status = await fetchAionUiOn(
          delegationTargetMachineId(delegation),
          `/api/internal/external-conversation-dispatches/${encodeURIComponent(delegation.childOperationId)}`,
          { timeoutMs: 3_000 },
        )
        await reconcileAiDelegationWorkspaceLeaseStatus(delegation, status, 'startup')
      } catch (error) {
        console.warn('[AI delegation workspace conversation recovery]', JSON.stringify({
          delegationId: delegation.id,
          leaseId: delegation.workspaceLease?.leaseId ?? null,
          error: error?.message ?? String(error),
        }))
      }
    }
  }

  const visited = new Set()
  for (const delegation of delegations) {
    const key = `${delegation.mapId}\u0000${delegation.targetCardId}\u0000${delegation.targetConversationId}`
    if (visited.has(key)) continue
    visited.add(key)
    const active = activeAiDelegationsForConversation(aiDelegations.values(), {
      mapId: delegation.mapId,
      targetCardId: delegation.targetCardId,
      targetConversationId: delegation.targetConversationId,
    })
    if (active.length < 2) continue
    const canonical = active[0]
    if (canonical.state === 'waiting-child-resume') continue
    for (const supersededCandidate of active.slice(1)) {
      if (supersededCandidate.state !== 'waiting-child-resume') continue
      const oldLeaseId = supersededCandidate.workspaceLease?.leaseId
      const canonicalLeaseId = canonical.workspaceLease?.leaseId
      let workspaceResult = supersededCandidate.workspaceResult ?? null
      if (oldLeaseId && oldLeaseId !== canonicalLeaseId) {
        workspaceResult = await workspacePoolManager.cancel(
          oldLeaseId,
          `새 위임 ${canonical.id}이 같은 카드와 대화의 작업을 이어받았습니다.`,
        )
      }
      await updateAiDelegation(supersededCandidate.id, {
        state: 'superseded',
        supersededByDelegationId: canonical.id,
        supersededAt: new Date().toISOString(),
        workspaceResult,
      })
    }
  }
}

async function reconcileAiDelegationWorkspaceLeaseStatus(delegation, status, source) {
  const actualLease = status?.workspaceLease ?? null
  const expectedLease = delegation.workspaceLease ?? null
  if (!actualLease?.leaseId) {
    if (!expectedLease?.leaseId) return true
    await updateAiDelegation(delegation.id, {
      state: 'recovery-required',
      childStatus: 'interrupted-by-workspace-conflict',
      childError: 'AionCore가 위임 실행에 실제 사용한 작업공간 lease를 반환하지 않아 안전하게 완료 여부를 판단할 수 없습니다.',
      recoveryRequiredAt: delegation.recoveryRequiredAt ?? new Date().toISOString(),
      workspaceLeaseReconciledAt: new Date().toISOString(),
      workspaceLeaseReconciliationSource: source,
      resource: null,
    })
    return false
  }

  if (aiDelegationWorkspaceLeaseMatches(expectedLease, actualLease)) {
    try {
      const reboundLease = await workspacePoolManager.bindConversation(
        actualLease.leaseId,
        delegation.targetConversationId,
      )
      if (!aiDelegationWorkspaceLeaseMatches(actualLease, reboundLease)) {
        throw new Error('작업공간 lease가 더 이상 활성 상태가 아니거나 실제 실행 정보와 일치하지 않습니다.')
      }
      return true
    } catch (error) {
      await updateAiDelegation(delegation.id, {
        state: 'recovery-required',
        childStatus: 'interrupted-by-workspace-conflict',
        childError: `AI 대화와 작업공간 lease 연결을 복구하지 못했습니다: ${error?.message ?? String(error)}`,
        recoveryRequiredAt: delegation.recoveryRequiredAt ?? new Date().toISOString(),
        workspaceLeaseReconciledAt: new Date().toISOString(),
        workspaceLeaseReconciliationSource: source,
        resource: null,
      })
      return false
    }
  }

  let recoveredLease = actualLease
  let recoveryError = null
  try {
    recoveredLease = await workspacePoolManager.reuseLease(actualLease.leaseId, {
      mapId: delegation.mapId,
      cardId: delegation.targetCardId,
      conversationId: delegation.targetConversationId,
    })
    if (!aiDelegationWorkspaceLeaseMatches(actualLease, recoveredLease)) {
      throw new Error('AionCore 응답과 로컬 작업공간 lease 정보가 일치하지 않습니다.')
    }
  } catch (error) {
    recoveryError = error?.message ?? String(error)
    await workspacePoolManager.quarantine(
      actualLease.leaseId,
      `AionCore의 실제 작업공간 lease를 안전하게 복구하지 못했습니다: ${recoveryError}`,
    )
  }

  const oldLeaseId = expectedLease?.leaseId
  let previousWorkspaceResult = null
  if (!recoveryError && oldLeaseId && oldLeaseId !== actualLease.leaseId) {
    previousWorkspaceResult = await workspacePoolManager.cancel(
      oldLeaseId,
      `AionCore가 보고한 실제 lease ${actualLease.leaseId}로 위임 정합성을 복구했습니다.`,
    )
  }

  await updateAiDelegation(delegation.id, {
    state: 'recovery-required',
    childStatus: 'interrupted-by-workspace-mismatch',
    childError: recoveryError
      ? `AionCore의 실제 작업공간 lease를 확인했지만 안전하게 복구하지 못했습니다: ${recoveryError}`
      : 'MindNProgress에 저장된 작업공간과 AionCore가 실제 사용한 작업공간이 달라 실제 lease로 복구했습니다. 작업 상태를 확인한 뒤 명시적으로 재개하세요.',
    workspaceLease: recoveredLease,
    workspaceResult: previousWorkspaceResult,
    workspaceError: recoveryError,
    recoveryRequiredAt: delegation.recoveryRequiredAt ?? new Date().toISOString(),
    workspaceLeaseReconciledAt: new Date().toISOString(),
    workspaceLeaseReconciliationSource: source,
    resource: null,
  })
  return false
}

async function latestAssistantResult(conversationId) {
  try {
    const messagePage = await fetchAionUiOn(conversationHomeMachineId(conversationId), `/api/conversations/${encodeURIComponent(conversationId)}/messages?limit=100&content_mode=full`, { timeoutMs: 30_000 })
    const messages = Array.isArray(messagePage?.items) ? messagePage.items : Array.isArray(messagePage) ? messagePage : []
    const message = [...messages].reverse().find((candidate) => candidate?.position === 'left'
      && (candidate.type === 'text' || candidate.type === 'tips')
      && readAionUiMessageContent(candidate).trim())
    return readAionUiMessageContent(message).trim().slice(0, 12_000)
  } catch {
    return ''
  }
}

async function captureAiDelegationChildResult(delegation) {
  if (delegation?.childResultSnapshot) return delegation
  const lastAttempt = Date.parse(String(delegation?.childResultCaptureAttemptedAt ?? ''))
  if (Number.isFinite(lastAttempt) && Date.now() - lastAttempt < 10_000) return delegation
  const result = await latestAssistantResult(delegation?.targetConversationId)
  const attemptedAt = new Date().toISOString()
  return updateAiDelegation(delegation.id, result
    ? {
        childResultSnapshot: result,
        childResultHash: createHash('sha256').update(result).digest('hex'),
        childResultTurnId: delegation?.childTurnId ?? null,
        childResultCapturedAt: attemptedAt,
        childResultCaptureAttemptedAt: attemptedAt,
      }
    : { childResultCaptureAttemptedAt: attemptedAt })
}

async function aiWorkspaceCandidates({ map, group, machineId }) {
  const collect = (document) => (document?.nodes ?? []).filter((node) => !node.data.reference)
    .flatMap((node) => aiConversationLinksFromData(node.data).map((link) => ({ ...link, reason: `${document.title} · ${node.data.label}` })))
    .filter((link) => conversationHomeMachineId(link.conversationId, link) === machineId)
  let links = collect(map)
  if (!links.length && group) {
    const documents = await Promise.all(group.mapIds.filter((id) => id !== map?.id).map(readMap))
    links = documents.filter((item) => item && !item.trashedAt && !item.archivedAt).flatMap(collect)
  }
  const unique = [...new Map(links.map((link) => [link.conversationId, link])).values()]
  let lookups = 0
  return (await Promise.all(unique.map(async (link) => {
    let workspace = link.workspace || aiConversationOrigins.get(link.conversationId)?.workspace
    if (!workspace && lookups++ < 5) {
      try { workspace = aiConversationLinkFromAionUiConversation(await fetchAionUiOn(machineId, `/api/conversations/${encodeURIComponent(link.conversationId)}`))?.workspace } catch { /* 추천 조회 실패는 기본값으로 대체하지 않는다. */ }
    }
    return workspace ? { workspace, reason: link.reason } : null
  }))).filter(Boolean)
}

function aiDelegationResultSection(reportResult) {
  if (reportResult.availability === 'captured') {
    return `## 하위 AI의 마지막 응답\n\n${reportResult.text}\n\n`
  }
  if (reportResult.availability === 'integrity-failed') {
    return `## 하위 AI 원문 무결성 오류\n\n저장된 결과의 해시 또는 실행 턴이 위임 기록과 일치하지 않아 원문을 전달하지 않았습니다. 대화의 최신 응답으로 대체하지 말고 위임 기록과 원본 대화를 별도로 검토하세요.\n\n`
  }
  return `## 하위 AI 원문 미캡처\n\n이 위임의 하위 AI 원문은 MindNProgress 위임 기록에 캡처되지 않아 재전달할 수 없습니다. 다른 작업이 이어졌을 수 있는 대화의 최신 응답으로 대체하지 않았으며, 아래 작업공간·체크포인트·통합 정보만 확인된 결과입니다.\n\n`
}

async function parentWakeInstruction(delegation, reportResult = aiDelegationReportResult(delegation)) {
  const parentMapId = delegation.parentMapId ?? delegation.mapId
  const parentProject = delegation.groupId ? null : await groupProjects.forDocument(parentMapId)
  const groupCoordinator = Boolean(delegation.groupId) || (parentProject?.role === 'coordinator'
    && documentRoot(await readMap(parentMapId))?.id === delegation.parentCardId)
  const approvalInstruction = groupCoordinator ? `${AI_EXECUTION_APPROVAL_INSTRUCTION}\n\n${GROUP_APPROVAL_INSTRUCTION}\n\n` : ''
  const followupInstruction = groupCoordinator ? GROUP_AI_DELEGATION_FOLLOWUP_INSTRUCTION : AI_DELEGATION_FOLLOWUP_INSTRUCTION
  const integrationFailure = delegation.integrationStatus && delegation.integrationStatus !== 'completed'
    ? delegation.integrationError ?? delegation.workspaceError ?? delegation.integrationStatus
    : null
  const outcome = integrationFailure
    ? `작업 완료 후 필수 체크포인트 또는 통합 실패 (${integrationFailure})`
    : delegation.workspaceError
      ? `작업 완료 후 통합 실패 (${delegation.workspaceError})`
      : aiDelegationSucceeded(delegation)
        ? '완료'
        : `실패 또는 중단 (${delegation.childError ?? '상세 원인 없음'})`
  const workspaceResult = delegation.workspaceResult
    ? `- 작업공간: ${delegation.workspaceResult.workspaceId ?? delegation.workspaceLease?.workspaceId ?? '미확인'}\n- 체크포인트: ${delegation.workspaceResult.headCommit ?? '변경 없음'}\n- 통합 커밋: ${delegation.workspaceResult.integratedCommit ?? '통합되지 않음'}\n- 작업공간 결과: ${delegation.workspaceResult.status ?? '미확인'}\n`
    : ''
  const conversationDisplay = await resolveAiConversationDisplay(
    delegation.targetConversationId,
    delegationTargetMachineId(delegation),
  )
  return `# MindNProgress 하위 AI 작업 결과

상위 카드에서 위임한 하위 카드 작업이 ${outcome} 상태가 되었습니다.
대상 문서: ${delegation.mapId}. 상위 문서: ${delegation.parentMapId ?? delegation.mapId}.

- 위임 ID: ${delegation.id}
- 하위 카드: ${delegation.targetCardLabel} (${delegation.targetCardId})
- 실행 대화: ${conversationDisplay.displayLabel}
- 하위 실행 턴: ${delegation.childTurnId ?? '미확인'}
- 결과 원문: ${reportResult.availability === 'captured' ? '캡처됨' : reportResult.availability === 'integrity-failed' ? '무결성 오류로 제외됨' : '캡처되지 않음'}
- 선택 방식: ${delegation.strategy === 'resume' ? '기존 대화 이어가기' : '새 대화 시작'}
- 선택 이유: ${delegation.decisionReason}
${workspaceResult}

${approvalInstruction}${aiDelegationResultSection(reportResult)}${AI_DELEGATION_REPORT_INSTRUCTION}

${followupInstruction}`
}

function aiDelegationRecoveryKey(delegation) {
  return [
    Number(delegation?.recoveryAttempt ?? 0),
    String(delegation?.recoveryRequiredAt ?? ''),
    String(delegation?.state ?? ''),
  ].join(':')
}

function parentRecoveryInstruction(delegation, conversationDisplayLabel = delegation.targetConversationId) {
  const error = delegation.integrationError ?? delegation.childError ?? delegation.workspaceError ?? '상세 원인 없음'
  const checkpoint = delegation.workspaceResult?.status === 'checkpoint-required'
    ? `- 체크포인트 회차: ${delegation.workspaceResult.checkpointRound ?? '미확인'}\n`
    : ''
  const result = delegation.childResultSnapshot
  return `# MindNProgress 하위 AI 작업 복구 필요

상위 카드에서 위임한 하위 카드 작업이 완료 보고 전 복구 필요 상태가 되었습니다. 이 알림은 완료 보고가 아니며 기존 위임은 아직 활성 상태입니다.

- 위임 ID: ${delegation.id}
- 하위 카드: ${delegation.targetCardLabel} (${delegation.targetCardId})
- 실행 대화: ${conversationDisplayLabel}
- 상태: ${delegation.state}
${checkpoint}- 원인: ${error}

${result ? `## 보존된 하위 AI의 마지막 응답\n\n${result}\n\n` : ''}같은 작업을 새로 위임하지 마세요. MindNProgress에서 기존 위임과 하위 카드·작업공간 상태를 확인한 뒤, 안전하게 이어갈 수 있을 때만 mindnprogress_recover_ai_delegation으로 기존 위임을 복구하세요. 자동 판단이 어렵다면 사용자에게 현재 상태와 필요한 확인을 알리세요.`
}

async function ensureAiDelegationNotification(delegation, { kind, message, dedupeKey, type = 'ai-delegation' }) {
  const notificationKey = `${kind}NotificationKey`
  if (delegation?.[notificationKey] === dedupeKey) return delegation
  const recipient = users.find((candidate) => candidate.id === delegation?.startedBy
    && candidate.role === 'editor' && candidate.active !== false)
  const map = await readMap(delegation?.mapId)
  const node = map?.nodes.find((candidate) => candidate.id === delegation?.targetCardId)
  if (!recipient || !map || map.trashedAt || !node) return delegation
  const notification = await createNotification(recipient, {
    type,
    mapId: map.id,
    mapTitle: map.title,
    nodeId: node.id,
    nodeLabel: node.data?.label ?? delegation.targetCardLabel ?? node.id,
    message,
    actor: systemUser,
    dedupeKey,
  })
  return updateAiDelegation(delegation.id, {
    [notificationKey]: dedupeKey,
    [`${kind}NotificationId`]: notification.id,
    [`${kind}NotifiedAt`]: notification.createdAt,
  })
}

// 하위 작업 완료 알림은 차단 알림과 다른 타입으로 만들어 화면에서 구분한다.
// 이미 알린 위임은 dedupeKey로 건너뛰므로 보고 재전달·결과 재확인이 반복돼도 중복 생성되지 않는다.
async function ensureAiDelegationCompletionNotification(delegation) {
  const notice = aiDelegationCompletionNotice(delegation)
  if (!notice) return delegation
  return ensureAiDelegationNotification(delegation, {
    kind: 'completed',
    type: AI_DELEGATION_COMPLETION_NOTIFICATION_TYPE,
    dedupeKey: notice.dedupeKey,
    message: notice.message,
  })
}

async function ensureCheckpointRequiredNotification(delegation, workspaceResult) {
  const round = Number(workspaceResult?.checkpointRound ?? 0)
  return ensureAiDelegationNotification(delegation, {
    kind: 'checkpoint',
    dedupeKey: `ai-delegation-checkpoint:${delegation.id}:${round}`,
    message: `하위 AI 작업은 종료됐지만 명시적 체크포인트가 없어 자동 보완을 요청했습니다. (회차 ${round || '미확인'})`,
  })
}

async function validateAiDelegationAction(request, delegation, body, approvalRequired = false, { requireConversationLinks = true } = {}) {
  const fail = (message, status = 409) => { throw Object.assign(new Error(message), { status, groupProjectError: true }) }
  const parentMapId = delegation.parentMapId ?? delegation.mapId
  const human = !hasValidIntegrationBearer(request) && Boolean(getSignedInUser(request))
  if (!human) {
    const source = delegationSourceForRequest(integrationRequestScope(request), parentMapId)
    if (!source || source.cardId !== delegation.parentCardId) fail('이 위임을 관리하는 상위 카드에서만 처리할 수 있습니다.', 403)
    const ownerMap = await readMap(parentMapId)
    const owner = ownerMap?.nodes.find((node) => node.id === delegation.parentCardId)
    if (source.conversationId && !isAiConversationLinked(owner?.data, source.conversationId)) fail('현재 AI 대화가 상위 카드에 연결되어 있지 않습니다.', 403)
  }
  if (body.expectedUpdatedAt && body.expectedUpdatedAt !== delegation.updatedAt) fail('위임 상태가 변경됐습니다. 상태를 다시 확인하세요.')
  const map = await readMap(delegation.mapId)
  const parent = parentMapId === delegation.mapId ? map : await readMap(parentMapId)
  const target = map?.nodes.find((node) => node.id === delegation.targetCardId)
  const parentCard = parent?.nodes.find((node) => node.id === delegation.parentCardId)
  if (!target || !parentCard || map.trashedAt || parent.trashedAt) fail('위임 문서 또는 카드를 찾을 수 없습니다.', 404)
  if (requireConversationLinks
    && (!isAiConversationLinked(target.data, delegation.targetConversationId) || !isAiConversationLinked(parentCard.data, delegation.parentConversationId))) fail('기존 상위·대상 대화의 카드 연결이 변경됐습니다.')
  if (delegation.groupId) {
    if (await groupProjects.authorizeDelegation(parent, parentCard.id, map, target.id) !== delegation.groupId) fail('그룹 소속 또는 총괄 문서가 변경됐습니다.')
    const context = await groupProjects.context(delegation.groupId)
    if (approvalRequired && delegation.groupProjectVersion !== undefined && delegation.groupProjectVersion !== context.project.version) fail('위임 이후 기획 기준이 변경됐습니다. 변경된 계획을 제안하고 사용자 승인을 다시 확인하세요.')
    if (human && body.groupVersion !== context.project.version) fail('최신 그룹 기준을 확인한 뒤 다시 요청하세요.')
  }
  if (human && (body.expectedUpdatedAt !== delegation.updatedAt || body.sourceRevision !== parent.version || body.targetRevision !== map.version)) fail('문서 또는 위임 상태가 변경됐습니다. 최신 내용을 불러오세요.')
  if (approvalRequired && human && body.confirmApprovedScope !== true) fail('기존 승인 계획과 현재 범위가 같음을 사용자가 확인해야 재개할 수 있습니다.', 400)
  return { human, map, parent, target }
}

async function recoverExpiredAiDelegationDispatch(delegation, machineId) {
  const origins = [...aiConversationOrigins.values()].filter((origin) => origin.mapId === delegation.mapId
    && origin.cardId === delegation.targetCardId && origin.startedBy === delegation.startedBy
    && conversationHomeMachineId(origin.conversationId, origin) === machineId)
  if (!origins.length || origins.length > 10) throw aiDelegationDispatchError('원본 실행 기록이 만료됐고 시작 카드 기준으로 복구 대화를 한정하지 못했습니다.', 409)
  const matches = []
  for (const origin of origins) {
    const conversation = await fetchAionUiOn(machineId, `/api/conversations/${encodeURIComponent(origin.conversationId)}`).catch((error) => {
      if (error.status === 404) return null
      throw error
    })
    if (!conversation || !sameExecutionWorkspace(conversation.extra?.workspace, delegation.workspaceLease.projectRoot)) continue
    let before = ''
    for (let page = 0; page < 20; page++) {
      const query = new URLSearchParams({ limit: '100', content_mode: 'full', ...(before ? { before } : {}) })
      const messages = await fetchAionUiOn(machineId, `/api/conversations/${encodeURIComponent(origin.conversationId)}/messages?${query}`)
      if (!Array.isArray(messages?.items) || typeof messages.has_more_before !== 'boolean') throw aiDelegationDispatchError('최초 위임 전문의 조회 범위를 확증하지 못했습니다.', 409)
      if (!messages.has_more_before) {
        const first = [...messages.items].sort((a, b) => Number(a.created_at) - Number(b.created_at)).find((message) => message.type === 'text')
        try { matches.push(verifyAiDelegationOriginalMessage(delegation, origin, conversation, first)) }
        catch (error) { if (error.code !== 'AI_DELEGATION_ORIGINAL_MESSAGE_UNCONFIRMED') throw error }
        break
      }
      if (!messages.oldest_cursor || messages.oldest_cursor === before || page === 19) throw aiDelegationDispatchError('최초 위임 전문까지 확인하지 못했습니다. 내용을 생략하여 복구하지 않습니다.', 409)
      before = messages.oldest_cursor
    }
  }
  if (matches.length !== 1) throw aiDelegationDispatchError('최초 위임 전문·해시·시작 카드·lease가 일치하는 대화를 하나로 확증하지 못했습니다.', 409)
  return { ...matches[0], operationId: delegation.childOperationId, turnId: null }
}

async function restoreConfirmedAiDelegationDispatch(delegation, map, parentMap, user) {
  const machineId = delegationTargetMachineId(delegation)
  let dispatch
  try { dispatch = await readAiDelegationDispatchStatus(fetchAionUiOn, { machineId, operationId: delegation.childOperationId }) }
  catch (error) {
    if (error.code !== 'AI_DELEGATION_STATUS_NOT_FOUND') throw error
    dispatch = await recoverExpiredAiDelegationDispatch(delegation, machineId)
  }
  const conversationId = String(dispatch.conversationId ?? '')
  if (!dispatch.recoveryProof && !['completed', 'failed', 'recovery_required', 'waiting_resume'].includes(dispatch.state)) {
    throw aiDelegationDispatchError('기존 실행이 아직 진행·대기 중이거나 상태가 불명확하여 복구하지 않았습니다.', 409)
  }
  if (dispatch.operationId !== delegation.childOperationId || !validAiConversationId(conversationId)
    || !aiDelegationWorkspaceLeaseMatches(delegation.workspaceLease, dispatch.workspaceLease)) {
    throw aiDelegationWorkspaceLeaseError('기존 실행의 대화·작업공간을 확증하지 못해 복구하지 않았습니다.', delegation.workspaceLease, dispatch.workspaceLease)
  }
  const parent = parentMap.nodes.find((node) => node.id === delegation.parentCardId)
  if (!isAiConversationLinked(parent?.data, delegation.parentConversationId)
    || (!delegation.groupId && !isHierarchyDescendant(map, delegation.parentCardId, delegation.targetCardId))) {
    throw aiDelegationDispatchError('기존 상위 대화 연결 또는 하위 카드 관계가 변경되었습니다.', 409)
  }
  const origin = aiConversationOrigins.get(conversationId)
  if (origin && (origin.mapId !== map.id || origin.cardId !== delegation.targetCardId)) {
    throw aiDelegationDispatchError('생성된 대화는 다른 시작 카드에 귀속되어 있습니다.', 409)
  }
  const conversation = await fetchAionUiOn(machineId, `/api/conversations/${encodeURIComponent(conversationId)}`)
  if (conversation?.id !== conversationId || normalizeAiConversationRuntime(conversationId, conversation).state !== 'idle') {
    throw aiDelegationDispatchError('기존 대화가 실행 중이거나 상태를 확인할 수 없어 복구하지 않았습니다.', 409)
  }
  if (!sameExecutionWorkspace(aiConversationLinkFromAionUiConversation(conversation)?.workspace, delegation.workspaceLease.projectRoot)) {
    throw aiDelegationDispatchError('기존 대화의 실제 작업 디렉토리가 배정된 작업공간과 달라 복구하지 않았습니다.', 409)
  }
  const selection = aiDelegationSelectionFromSource(delegation.pendingSelection)
  if (!selection) throw aiDelegationDispatchError('기존 실행의 AI 설정을 확인할 수 없습니다.', 409)
  const workspaceLease = await workspacePoolManager.reactivateQuarantinedLease(delegation.workspaceLease.leaseId, {
    mapId: map.id, cardId: delegation.targetCardId, conversationId,
    failureCategory: 'confirmed-dispatch', confirmedDispatchLease: dispatch.workspaceLease,
  })
  const link = normalizeAiConversationLink({
    conversationId, homeMachineId: machineId, agent: selection.agent, model: selection.model,
    providerId: selection.providerId, mode: selection.mode, thoughtLevel: selection.thoughtLevel,
    skills: selection.enabledSkillIds.map((id) => ({ id, label: id })),
    mcpServers: selection.mcpIds.map((id) => ({ id, label: id })), workspace: workspaceLease.projectRoot,
    startedBy: { id: delegation.startedBy, label: user.name },
    startedAt: normalizedIsoDate(conversation.created_at) ?? delegation.createdAt, linkedAt: new Date().toISOString(),
  })
  const updatedMap = await saveMap(map.id, { nodes: map.nodes.map((node) => node.id === delegation.targetCardId
    ? { ...node, data: { ...node.data, aiConversationId: conversationId, aiConversations: appendAiConversationLink(node.data, link) } } : node), edges: map.edges }, user, map.title, map.color, 'content')
  rememberAiConversationOrigin({ conversationId, mapId: map.id, cardId: delegation.targetCardId,
    startedBy: delegation.startedBy, homeMachineId: machineId, linkedAt: link.linkedAt,
    workspace: workspaceLease.projectRoot, workspacePoolId: workspaceLease.poolId })
  await persistAiConversationOrigins()
  const updated = await updateAiDelegation(delegation.id, { targetConversationId: conversationId, workspaceLease,
    dispatchRecoveryProof: dispatch.recoveryProof ?? { kind: 'original-operation', operationId: delegation.childOperationId },
    childTurnId: dispatch.turnId ?? null, dispatchLinkRecoveredAt: new Date().toISOString(),
    attemptHistory: aiDelegationAttemptHistory(delegation, '기존 실행 조회와 Git·세션 검증 후 누락된 대화 연결 복구') })
  broadcastEvent({ type: 'ai-conversation-linked', mapId: map.id, nodeId: delegation.targetCardId,
    conversationId, conversation: link, sourceClientId: null, updatedAt: updatedMap.updatedAt, updatedBy: publicUser(user) })
  return { delegation: updated, map: updatedMap }
}

async function ensureAiDelegationTerminalResolutionIdle(delegation) {
  const operationId = delegation.state === 'parent-wake-failed'
    ? delegation.wakeOperationId
    : delegation.childOperationId
  if (!operationId) return
  const machineId = delegation.state === 'parent-wake-failed'
    ? delegationParentMachineId(delegation)
    : delegationTargetMachineId(delegation)
  let dispatch
  try {
    dispatch = await fetchAionUiOn(machineId, `/api/internal/external-conversation-dispatches/${encodeURIComponent(operationId)}`)
  } catch (error) {
    if (error?.status === 404) return
    throw Object.assign(new Error('실행 상태를 확인할 수 없어 위임을 종료하지 않았습니다. 연결을 확인한 뒤 다시 시도하세요.'), { status: 409, groupProjectError: true })
  }
  if (['starting', 'running', 'waiting_resource', 'waiting_resume'].includes(dispatch?.state)) {
    throw Object.assign(new Error('AionUi에 아직 실행 또는 재개 대기 중인 작업이 있어 위임을 종료할 수 없습니다. 해당 대화를 먼저 중지하거나 마무리하세요.'), { status: 409, groupProjectError: true })
  }
  if (dispatch?.state === 'completed') {
    throw Object.assign(new Error('저장된 기록보다 실행 상태가 앞서 있습니다. 상태 다시 확인 후 처리하세요.'), { status: 409, groupProjectError: true })
  }
}

async function settlePendingAiRecovery(delegation) {
  const pending = delegation.pendingRecovery
  if (!pending) return null
  const dispatch = await readAiDelegationDispatchStatus(fetchAionUiOn, { machineId: delegationTargetMachineId(delegation), operationId: pending.operationId, phase: 'recovery' })
  if (dispatch.conversationId !== delegation.targetConversationId || !aiDelegationWorkspaceLeaseMatches(pending.workspaceLease ?? null, dispatch.workspaceLease ?? null)) throw aiDelegationDispatchError('복구 실행의 대화·작업공간이 저장된 요청과 일치하지 않습니다.', 409)
  if (!['starting', 'running', 'waiting_resource', 'waiting_resume', 'recovery_required', 'completed', 'failed'].includes(dispatch.state)) throw aiDelegationDispatchError('복구 실행 상태를 아직 확인할 수 없습니다.', 409)
  const now = new Date().toISOString()
  const runtime = pending.integrationRecovery ? { state: integrationDelegationState(dispatch.state), integrationOperationId: pending.operationId, integrationTurnId: dispatch.turnId ?? null } : {
    ...initialAiDelegationRuntime(dispatch, now), childOperationId: pending.operationId,
    // 응답 유실 동안 끝났어도 일반 완료 경로에서 하위 업무와 체크포인트를 검증한다.
    ...(['completed', 'failed'].includes(dispatch.state) ? { state: 'starting' } : {}),
    childStatus: dispatch.state === 'waiting_resume' ? 'interrupted' : null,
    childError: dispatch.errorMessage ?? null,
    childResultSnapshot: null, childResultHash: null, childResultTurnId: null,
    childResultCapturedAt: null, childResultCaptureAttemptedAt: null,
    reportReceipt: null, reportWaitReason: null,
    reportPayloadHash: null, reportResultAvailability: null, reportResultHash: null,
    reportResultTurnId: null, reportPreparedAt: null,
    workspaceResult: null, workspaceError: null,
  }
  return updateAiDelegation(delegation.id, {
    ...runtime, pendingRecovery: null, recoveryWorkspaceLease: null, recoveryAttempt: pending.attempt, recoveryOperationId: pending.operationId,
    recoverySourceState: pending.sourceState, workspaceLease: pending.workspaceLease,
    recoveryDispatchError: null, parentError: null, parentDispatchState: null, completedAt: null,
  })
}

async function refreshSuspendedAiDelegation(delegation) {
  if (delegation.pendingRecovery) return settlePendingAiRecovery(delegation)
  if (['completed', 'superseded', 'closed'].includes(delegation.state)) return delegation
  const delivered = aiDelegationStoredReportDeliveryPatch(delegation)
  if (delivered) return updateAiDelegation(delegation.id, delivered)
  // 하위 실행이 이미 끝난 보고 대기를 과거 child operation 조회 실패로 막지 않는다.
  if (delegation.state === 'waiting-parent') return delegation
  // 실행 요청을 보내지 않는다. 같은 operation의 확인된 상태만 반영한다.
  const reportOnly = aiDelegationSucceeded(delegation) && ['waking-parent', 'parent-wake-failed'].includes(delegation.state)
  const operationId = reportOnly ? delegation.wakeOperationId : delegation.childOperationId
  if (!operationId) return delegation
  const status = await readAiDelegationDispatchStatus(fetchAionUiOn, {
    machineId: reportOnly ? delegationParentMachineId(delegation) : delegationTargetMachineId(delegation),
    operationId, phase: reportOnly ? 'report' : 'child',
  })
  const expectedConversation = reportOnly ? delegation.parentConversationId : delegation.targetConversationId
  if (status.conversationId && status.conversationId !== expectedConversation) throw aiDelegationDispatchError('실행 대화가 위임 기록과 일치하지 않습니다.', 409)
  if (reportOnly) {
    const received = aiDelegationDeliveredReportPatch(delegation, { ...status, conversationId: status.conversationId ?? expectedConversation })
    if (received) return updateAiDelegation(delegation.id, received)
    if (status.state !== 'completed') return delegation
    return updateAiDelegation(delegation.id, {
      state: 'completed', parentDispatchState: 'completed', parentError: null,
      completedAt: new Date().toISOString(), attemptHistory: aiDelegationAttemptHistory(delegation, '기존 결과 전달 완료 확인'),
    })
  }
  if (!['waiting-usage-limit', 'waiting-rate-limit', 'waiting-model-capacity', 'parent-wake-failed', 'failed'].includes(delegation.state)) return delegation
  const limitState = aiDelegationLimitState({ ...delegation, childStatus: status.state, childError: status.errorMessage ?? null })
  if (limitState) {
    // 새 사용량 중단의 worker만 한 번 안전하게 보존한다. 이후에는 상태 조회만 한다.
    const workspace = delegation.workspaceLease?.leaseId && !delegation.workspaceResult
      ? await finalizeDelegationWorkspace(delegation, 'failed', status.errorMessage)
      : { result: delegation.workspaceResult, error: delegation.workspaceError }
    return updateAiDelegation(delegation.id, { state: limitState, childStatus: 'failed', childError: status.errorMessage ?? delegation.childError, workspaceResult: workspace.result, workspaceError: workspace.error })
  }
  // 격리 worker를 조회만으로 재활성화하거나 성공 처리하지 않는다.
  if (delegation.workspaceResult?.status === 'quarantined') return delegation
  if (['starting', 'running', 'waiting_resource', 'waiting_resume', 'recovery_required'].includes(status.state)) {
    return updateAiDelegation(delegation.id, {
      ...initialAiDelegationRuntime(status), childError: status.errorMessage ?? null,
      childStatus: status.state === 'waiting_resume' ? 'interrupted' : null,
      parentError: null, parentDispatchState: null, completedAt: null,
      childResultSnapshot: null, childResultHash: null, childResultTurnId: null,
      childResultCapturedAt: null, childResultCaptureAttemptedAt: null,
      reportReceipt: null, reportWaitReason: null,
      reportPayloadHash: null, reportResultAvailability: null, reportResultHash: null,
      reportResultTurnId: null, reportPreparedAt: null,
      attemptHistory: aiDelegationAttemptHistory(delegation, '같은 실행의 재개 확인'),
    })
  }
  if (status.state === 'completed' && !delegation.workspaceLease?.leaseId) {
    const workPending = await documentCoordinationPending(delegation)
    const updated = await updateAiDelegation(delegation.id, {
      state: workPending ? 'waiting-document-work' : 'parent-wake-failed', childStatus: 'completed', childError: null,
      childCompletedAt: delegation.childCompletedAt ?? new Date().toISOString(),
      reportApprovalRequired: true,
      parentDispatchState: 'not-sent', parentError: null, childTurnId: status.turnId ?? delegation.childTurnId,
      childResultSnapshot: null, childResultHash: null, childResultTurnId: null,
      childResultCapturedAt: null, childResultCaptureAttemptedAt: null,
      reportReceipt: null, reportWaitReason: null,
      reportPayloadHash: null, reportResultAvailability: null, reportResultHash: null,
      reportResultTurnId: null, reportPreparedAt: null,
      attemptHistory: aiDelegationAttemptHistory(delegation, '같은 실행 완료 확인 · 결과 전달은 사용자 요청 대기'),
    })
    return workPending ? updated : captureAiDelegationChildResult(updated)
  }
  return delegation
}

function pendingDocumentCoordinationDelegations(delegation) {
  if (!delegation?.coordinationOnly) return []
  return [...aiDelegations.values()].filter((item) =>
    item.parentConversationId === delegation.targetConversationId
    && aiDelegationWorkPending(item))
}

function canFinalizeDocumentCoordination(delegation) {
  if (!delegation?.coordinationOnly || delegation.workspaceLease?.leaseId) return false
  if (delegation.state === 'waiting-document-work') return true
  // 구버전 waiting-document-work가 재시작 뒤 과거 operation 404로 recovery-required에
  // 후퇴했더라도 당시 캡처한 결과가 있으면 사용자 확인으로 조정 실행만 종료할 수 있다.
  return delegation.state === 'recovery-required' && Boolean(delegation.childResultHash)
}

async function documentCoordinationPending(delegation) {
  if (!delegation.coordinationOnly) return false
  // 사용자가 미완료 카드와 하위 위임을 보존한 채 조정 실행만 명시적으로 끝낸 경우에는
  // 이후 폴링에서도 다시 waiting-document-work로 되돌리지 않는다.
  if (delegation.coordinationFinalizedAt) return false
  if (pendingDocumentCoordinationDelegations(delegation).length > 0) return true
  const conversation = await fetchAiConversationRuntime(delegation.targetConversationId)
  return normalizeAiConversationRuntime(delegation.targetConversationId, conversation).state !== 'idle'
}

function integrationCleanWaitKey(delegation) {
  return createHash('sha256').update(JSON.stringify({
    id: delegation?.id,
    startedAt: delegation?.integrationCleanWaitStartedAt,
  })).digest('hex').slice(0, 16)
}

function integrationCleanWaitMessage(delegation) {
  const paths = Array.isArray(delegation?.integrationCleanTrackedChanges)
    ? delegation.integrationCleanTrackedChanges
    : []
  const pathSummary = paths.length > 0
    ? ` 차단 파일: ${paths.slice(0, 3).join(', ')}${paths.length > 3 ? ` 외 ${paths.length - 3}건` : ''}`
    : ''
  return `통합 작업공간의 커밋되지 않은 추적 변경 때문에 하위 AI 전문을 아직 전달하지 않았습니다. 변경이 정리되면 같은 위임을 자동 시작합니다.${pathSummary}`
}

function parentIntegrationCleanWaitInstruction(delegation, conversationDisplayLabel = delegation.targetConversationId) {
  const paths = Array.isArray(delegation?.integrationCleanTrackedChanges)
    ? delegation.integrationCleanTrackedChanges
    : []
  const pathList = paths.length > 0
    ? paths.map((item) => `- ${item}`).join('\n')
