  } catch (error) {
    if (!(error instanceof SyntaxError)) throw error
    console.warn(`[Notifications] 손상된 알림 파일을 빈 목록으로 처리합니다: ${userId}`)
    notifications = []
  }
  return notifications
    .filter((notification) => notification?.userId === userId)
