const acquireDocumentMutation = createDocumentMutationGate()

const server = createServer(runtimeLifecycle.request(async (request, response) => {
  const loopbackLocation = localLoopbackRedirectLocation(request)
  if (loopbackLocation) {
    response.writeHead(307, {
      Location: loopbackLocation,
      'Cache-Control': 'no-store',
    })
    response.end()
    return
  }
  const url = new URL(request.url ?? '/', `http://${request.headers.host ?? 'localhost'}`)
  const runnerMcpAccess = authorizeRunnerMcpRequest({
    request,
    pathname: url.pathname,
    machineRegistry,
    conversationOrigins: aiConversationOrigins,
    transientAttributions: aiAttributions.values(),
    users,
  })
  if (runnerMcpAccess.kind === 'rejected') {
    return sendJson(response, runnerMcpAccess.status, {
      error: runnerMcpAccess.error,
      code: runnerMcpAccess.code,
    })
  }
  if (runnerMcpAccess.kind === 'authorized') {
    // 머신 토큰은 검증된 대화에서만 기존 연동 권한으로 승격한다.
    // 이후 라우트는 기존 로컬 MCP와 같은 사용자 귀속·권한 검사를 그대로 사용한다.
    request.headers.authorization = `Bearer ${integrationToken}`
    request.headers['x-mnp-ai-editor-id'] = runnerMcpAccess.owner.id
  }
  let delegationActionId = null
  let releaseDocumentMutation = null

  try {
    if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method) && /^\/api\/(maps|groups|document-reconstructions|card-layouts)(\/|$)/.test(url.pathname)) {
      const isTransition = /^\/api\/maps\/[^/]+\/archive$/.test(url.pathname)
        || /^\/api\/maps\/[^/]+\/cards\/[^/]+\/move$/.test(url.pathname)
        || /^\/api\/document-reconstructions\/(apply|[^/]+\/rollback)$/.test(url.pathname)
        || /^\/api\/card-layouts\/[^/]+\/apply$/.test(url.pathname)
      releaseDocumentMutation = await acquireDocumentMutation(isTransition)
    }
    const writableMapRoute = url.pathname.match(/^\/api\/maps\/([^/]+)(\/.*)?$/)
    if (writableMapRoute && !['GET', 'HEAD', 'OPTIONS'].includes(request.method) && writableMapRoute[2] !== '/archive') {
      const mapId = decodeURIComponent(writableMapRoute[1])
      if (isValidMapId(mapId) && documentReconstruction.isUnavailable(mapId)) {
        if (!requireUser(request, response)) return
        documentReconstruction.assertWritable(mapId)
      }
    }
    const archiveRoute = url.pathname.match(/^\/api\/maps\/(map-[a-zA-Z0-9_-]+)\/archive$/)
    if (url.pathname === '/api/maps/archive' && request.method === 'GET') {
      if (!requireUser(request, response)) return
      return sendJson(response, 200, { maps: await listMaps({ archivedOnly: true }) })
    }
    if (archiveRoute && request.method === 'PATCH') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 문서를 보관하거나 복원할 수 있습니다.' })
      const map = await documentReconstruction.archive(archiveRoute[1], await readJsonBody(request), publicUser(user))
      broadcastMapChange(request, map.id, map.archivedAt ? 'archived' : 'archive-restored', user)
      const maps = await listMaps()
      return sendJson(response, 200, { map, maps, documentLayout: await readDocumentLayout(maps.map((m) => m.id)) })
    }
    if (url.pathname === '/api/card-layouts' || url.pathname.startsWith('/api/card-layouts/')) {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 배치 제안을 사용할 수 있습니다.' })
      const actor = publicUser(user)
      const parts = url.pathname.slice('/api/card-layouts'.length).split('/').filter(Boolean).map(decodeURIComponent)
      if (request.method === 'GET' && !parts.length) return sendJson(response, 200, { requests: cardLayoutRequests.list(url.searchParams.get('mapId'), actor) })
      if (request.method === 'GET' && parts.length === 1) return sendJson(response, 200, await cardLayoutRequests.get(parts[0], actor))
      if (request.method === 'POST') {
        const body = await readJsonBody(request)
        if (!parts.length) return sendJson(response, 201, await cardLayoutRequests.create(body, actor))
        const [id, action] = parts
        if (parts.length !== 2) return sendJson(response, 404, { error: '배치 요청 경로를 확인하세요.' })
        if (action === 'capture') return sendJson(response, 200, await cardLayoutRequests.capture(id, body, actor))
        if (action === 'proposal') return sendJson(response, 200, await cardLayoutRequests.submit(id, body, actor))
        if (action === 'preview') return sendJson(response, 200, await cardLayoutRequests.preview(id, actor, body))
        if (['measure', 'verify'].includes(action)) return sendJson(response, 200, await cardLayoutRequests.inspect(id, body, action === 'verify', actor))
        if (action === 'cancel') return sendJson(response, 200, await cardLayoutRequests.cancel(id, actor))
        if (action === 'apply') {
          const result = await cardLayoutRequests.apply(id, body, actor)
          broadcastMapChange(request, result.mapId, 'card-layout', user)
          return sendJson(response, 200, result)
        }
      }
      return sendJson(response, 404, { error: '지원하지 않는 배치 요청입니다.' })
    }
    if (url.pathname === '/api/document-reconstructions' || url.pathname.startsWith('/api/document-reconstructions/')) {
      const user = requireUser(request, response)
      if (!user) return
      const suffix = url.pathname.slice('/api/document-reconstructions'.length)
      if (request.method === 'GET') {
        if (suffix === '/choices') return sendJson(response, 200, await documentReconstruction.choices({ groupId: url.searchParams.get('groupId'), mapId: url.searchParams.get('mapId') }))
        if (suffix === '/requests') return sendJson(response, 200, { requests: reconstructionRequests.list() })
        if (/^\/requests\/[^/]+$/.test(suffix)) {
          const record = reconstructionRequests.get(decodeURIComponent(suffix.split('/')[2]))
          if (!record.conversation?.id) return sendJson(response, 200, record)
          const display = await resolveAiConversationDisplay(record.conversation.id, conversationHomeMachineId(record.conversation.id, record.conversation))
          return sendJson(response, 200, {
            ...record,
            conversation: {
              ...record.conversation,
              name: display.name,
              displayLabel: display.displayLabel,
              displaySource: display.source,
            },
          })
        }
        if (suffix === '/context') return sendJson(response, 200, await documentReconstruction.context(url.searchParams.getAll('mapId')))
        if (!suffix) return sendJson(response, 200, { operations: documentReconstruction.list() })
        const record = documentReconstruction.get(decodeURIComponent(suffix.slice(1)))
        return sendJson(response, record ? 200 : 404, record ?? { error: '전환 이력을 찾을 수 없습니다.' })
      }
      if (request.method === 'POST' && suffix === '/preview') {
        const body = await readJsonBody(request)
        return sendJson(response, 200, await documentReconstruction.preview(body.plan))
      }
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 문서 재구성을 적용하거나 되돌릴 수 있습니다.' })
      if (request.method === 'POST' && ['/measure-layout', '/verify-layout'].includes(suffix)) {
        const body = await readJsonBody(request)
        return sendJson(response, 200, await documentReconstruction.inspectRenderedLayout(body.plan, body.previewHash, body.measurements, suffix === '/verify-layout', publicUser(user)))
      }
      if (request.method === 'POST' && suffix === '/requests') return sendJson(response, 201, await reconstructionRequests.create(await readJsonBody(request), publicUser(user)))
      if (request.method === 'POST' && /^\/requests\/[^/]+\/proposal$/.test(suffix)) return sendJson(response, 200, await reconstructionRequests.submit(decodeURIComponent(suffix.split('/')[2]), await readJsonBody(request), publicUser(user)))
      if (request.method === 'POST' && (suffix === '/apply' || /^\/[^/]+\/rollback$/.test(suffix))) {
        const body = await readJsonBody(request)
        const operation = suffix === '/apply'
          ? await documentReconstruction.apply(body.plan, publicUser(user), body.previewHash)
          : await documentReconstruction.rollback(decodeURIComponent(suffix.split('/')[1]), publicUser(user))
        for (const mapId of [...operation.sources.map((source) => source.mapId), ...operation.targetMapIds]) broadcastMapChange(request, mapId, 'reconstructed', user)
        const maps = await listMaps()
        return sendJson(response, 200, { operation, maps, documentLayout: await readDocumentLayout(maps.map((map) => map.id)) })
      }
      return sendJson(response, 404, { error: '지원하지 않는 재구성 작업입니다.' })
    }
    const actionRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/ai-delegations\/([^/]+)\/(recover|refresh|retry-report|finalize-coordination|supersede|close)$/)
    if (actionRoute && request.method === 'POST') {
      const id = decodeURIComponent(actionRoute[2])
      for (let attempt = 0; aiDelegationPollRunning && attempt < 100; attempt++) await new Promise((resolve) => setTimeout(resolve, 25))
      if (aiDelegationPollRunning || aiDelegationActions.has(id)) return sendJson(response, 409, { error: '위임 상태를 처리 중입니다. 잠시 후 다시 확인하세요.', code: 'AI_DELEGATION_ACTION_BUSY' })
      aiDelegationActions.add(id)
      delegationActionId = id
      if (actionRoute[3] !== 'recover') {
        const user = requireUser(request, response)
        if (!user) return
        if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 위임 상태를 처리할 수 있습니다.' })
        const delegation = aiDelegations.get(id)
        if (!delegation || (delegation.parentMapId ?? delegation.mapId) !== decodeURIComponent(actionRoute[1])) return sendJson(response, 404, { error: '위임을 찾을 수 없습니다.' })
        const body = await readJsonBody(request)
        const retryReport = actionRoute[3] === 'retry-report'
        const finalizeCoordination = actionRoute[3] === 'finalize-coordination'
        const supersede = actionRoute[3] === 'supersede'
        const close = actionRoute[3] === 'close'
        const validated = await validateAiDelegationAction(request, delegation, body, retryReport || finalizeCoordination, { requireConversationLinks: !supersede && !close })
        if (!retryReport && !finalizeCoordination && !supersede && !close) {
          if (body.acknowledgeResultHash !== undefined) {
            const source = delegationSourceForRequest(integrationRequestScope(request), delegation.parentMapId ?? delegation.mapId)
            if (validated.human || !source || source.cardId !== delegation.parentCardId) return sendJson(response, 403, { error: '담당 상위 AI 대화에서만 결과 수신을 확인할 수 있습니다.' })
            if (body.expectedUpdatedAt !== delegation.updatedAt) return sendJson(response, 409, { error: '최신 위임 상태를 조회한 뒤 수신 확인하세요.' })
            if (await documentCoordinationPending(delegation)) return sendJson(response, 409, { error: '미완료 하위 업무가 남아 문서 조정 결과를 수신 완료로 처리할 수 없습니다.' })
            const patch = acknowledgeAiDelegationReport(delegation, { conversationId: source.conversationId, resultHash: body.acknowledgeResultHash })
            const acknowledged = await updateAiDelegation(id, patch)
            const archived = await archiveAiDelegationReport(acknowledged)
            return sendJson(response, 200, { delegation: delegationPublicView(archived), executionRequested: false, resultAcknowledged: true, cardChanged: false })
          }
          return sendJson(response, 200, { delegation: delegationPublicView(await refreshSuspendedAiDelegation(delegation)), executionRequested: false })
        }
        if (close) {
          if (body.confirmClosedWithoutCompletion !== true || body.confirmResultReportDiscarded !== true) {
            return sendJson(response, 400, { error: '완료 처리와 결과 보고 없이 위임 기록을 종료할지 모두 확인해야 합니다.' })
          }
          const reason = String(body.reason ?? '').trim()
          const note = String(body.note ?? '').trim()
          if (!['result-invalidated', 'conversation-removed', 'no-longer-needed'].includes(reason)) return sendJson(response, 400, { error: '사용자 종료 사유를 선택하세요.' })
          if (note.length < 3 || note.length > 1000) return sendJson(response, 400, { error: '사용자 종료 감사 메모를 3자 이상 1000자 이하로 입력하세요.' })
          const closure = aiDelegationClosureAvailability(delegation)
          if (!closure?.closeAvailable) {
            return sendJson(response, 409, { error: closure?.reason === 'workspace-changes-preserved'
              ? '작업공간에 보존할 변경이 있어 위임을 종료할 수 없습니다. 기존 작업을 복구하거나 작업공간을 먼저 안전하게 정리하세요.'
              : '실행 또는 복구 가능성이 남은 위임은 사용자 종료할 수 없습니다. 상태를 다시 확인하세요.' })
          }
          await ensureAiDelegationTerminalResolutionIdle(delegation)
          const closedAt = new Date().toISOString()
          const updated = await updateAiDelegation(id, {
            state: 'closed', closedAt, closedByUserId: user.id,
            closureSourceState: delegation.state, closureReason: reason, closureNote: note,
            reportApprovalRequired: false, reportCancelledAt: closedAt,
          })
          return sendJson(response, 200, {
            delegation: delegationPublicView(updated), childExecutionRequested: false,
            resultReported: false, cardChanged: false, workspaceChanged: false,
          })
        }
        if (supersede) {
          if (body.confirmSupersededByCompletedDelegation !== true) return sendJson(response, 400, { error: '완료된 후속 위임으로 기존 미종료 위임을 종료할지 확인해야 합니다.' })
          const replacementId = String(body.replacementDelegationId ?? '').trim()
          const replacement = aiDelegations.get(replacementId)
          if (!aiDelegationCanBeSupersededBy(delegation, replacement)) {
            return sendJson(response, 409, { error: '같은 상위 카드와 대상 카드에서 나중에 성공한 위임이며, 기존 실행이 결과 보고 실패 또는 변경 없는 한도 중단인 경우에만 후속 위임으로 종료할 수 있습니다.' })
          }
          await ensureAiDelegationTerminalResolutionIdle(delegation)
          const supersededAt = new Date().toISOString()
          const updated = await updateAiDelegation(id, {
            state: 'superseded', supersededByDelegationId: replacement.id,
            supersededAt, supersededByUserId: user.id,
            supersessionReason: '같은 카드의 후속 위임이 작업과 결과 전달을 완료했습니다.',
          })
          return sendJson(response, 200, {
            delegation: delegationPublicView(updated), replacement: delegationPublicView(replacement),
            childExecutionRequested: false, cardChanged: false,
          })
        }
        if (finalizeCoordination) {
          if (body.confirmPendingWorkPreserved !== true) return sendJson(response, 400, { error: '미완료 하위 업무와 카드의 상태·진행률·외부 대기를 그대로 보존할지 확인해야 합니다.' })
          if (!canFinalizeDocumentCoordination(delegation)) {
            return sendJson(response, 409, { error: '완료 관측 또는 보존 결과가 있는 문서 조정 전용 위임만 조정 실행을 종료할 수 있습니다.' })
          }
          // waiting-document-work는 해당 child operation의 completed 응답을 관측한 뒤에만 저장된다.
          // AionCore가 재시작되어 operation을 잃어도 이 내구 상태와 사용자 확인으로 복구할 수 있다.
          const supersededDelegations = []
          for (const pending of pendingDocumentCoordinationDelegations(delegation)) {
            const replacement = completedAiDelegationReplacement(pending, aiDelegations.values())
            if (!replacement) continue
            const supersededAt = new Date().toISOString()
            await updateAiDelegation(pending.id, {
              state: 'superseded', supersededByDelegationId: replacement.id,
              supersededAt, supersededByUserId: user.id,
              supersessionReason: '문서 조정 종료 시 같은 카드의 완료된 후속 위임을 확인했습니다.',
            })
            supersededDelegations.push({ delegationId: pending.id, replacementDelegationId: replacement.id })
          }
          const pendingDelegationIds = pendingDocumentCoordinationDelegations(delegation).map((item) => item.id)
          const captured = await captureAiDelegationChildResult(delegation)
          const finalizedAt = new Date().toISOString()
          const updated = await updateAiDelegation(id, {
            state: 'waiting-parent', childStatus: 'completed', childError: null,
            childCompletedAt: captured.childCompletedAt ?? finalizedAt,
            parentDispatchState: null, parentError: null, completedAt: null,
            reportApprovalRequired: false,
            coordinationFinalizedAt: finalizedAt,
            coordinationFinalizedBy: user.id,
            coordinationFinalizationSourceState: delegation.state,
            coordinationPendingDelegationIds: pendingDelegationIds,
            coordinationSupersededDelegations: supersededDelegations,
          })
          return sendJson(response, 202, {
            delegation: delegationPublicView(updated), childExecutionRequested: false,
            pendingWorkPreserved: true, supersededDelegations,
            preserved: {
              mapVersion: validated.map.version,
              targetCardStatus: validated.target.data?.status ?? null,
              targetCardProgress: validated.target.data?.progress ?? null,
              waitingItemCount: Array.isArray(validated.target.data?.waitingItems) ? validated.target.data.waitingItems.length : 0,
              pendingDelegationIds,
            },
          })
        }
        if (delegation.state !== 'parent-wake-failed' || !aiDelegationSucceeded(delegation)) return sendJson(response, 409, { error: '실제 작업 완료가 확인된 보고 대기 위임만 결과를 재전달할 수 있습니다.' })
        if (delegation.wakeOperationId) {
          let previous
          try { previous = await fetchAionUiOn(delegationParentMachineId(delegation), `/api/internal/external-conversation-dispatches/${encodeURIComponent(delegation.wakeOperationId)}`) }
          catch (error) { if (error?.status !== 404) throw error }
          if (previous?.conversationId && previous.conversationId !== delegation.parentConversationId) return sendJson(response, 409, { error: '기존 결과 전달 대화가 일치하지 않습니다.' })
          if (previous?.state === 'completed') return sendJson(response, 200, { delegation: delegationPublicView(await refreshSuspendedAiDelegation(delegation)), repeated: true })
          if (['starting', 'running', 'waiting_resource', 'waiting_resume'].includes(previous?.state)) {
            const updated = await updateAiDelegation(id, { state: 'waking-parent', parentDispatchState: previous.state, parentTurnId: previous.turnId ?? delegation.parentTurnId, parentError: null })
            return sendJson(response, 202, { delegation: delegationPublicView(updated), repeated: true, childExecutionRequested: false })
          }
          if (previous && !['failed', 'recovery_required'].includes(previous.state)) return sendJson(response, 409, { error: '기존 결과 전달의 종료 상태를 확인하지 못했습니다. 새 전달은 만들지 않았습니다.' })
        }
        const updated = await updateAiDelegation(id, {
          state: 'waiting-parent', parentDispatchState: null, parentError: null, completedAt: null,
          reportApprovalRequired: false,
          attemptHistory: aiDelegationAttemptHistory(delegation, '사용자 요청에 따른 결과 재전달'),
          reportRetryRequestedAt: new Date().toISOString(), reportRetryRequestedBy: user.id,
          reportReceipt: null, reportWaitReason: null,
          reportPayloadHash: null, reportResultAvailability: null, reportResultHash: null,
          reportResultTurnId: null, reportPreparedAt: null,
        })
        return sendJson(response, 202, { delegation: delegationPublicView(updated), childExecutionRequested: false })
      }
    }
    const groupRoute = url.pathname.match(/^\/api\/groups\/([^/]+)(\/documents)?$/)
    if (groupRoute) {
      const user = requireUser(request, response)
      if (!user) return
      const groupId = decodeURIComponent(groupRoute[1])
      if (request.method === 'GET' && !groupRoute[2]) return sendJson(response, 200, await groupProjects.context(groupId))
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 그룹 개발 정보를 변경할 수 있습니다.' })
      if ((request.method === 'PATCH' && !groupRoute[2]) || (request.method === 'POST' && groupRoute[2])) {
        const body = await readJsonBody(request)
        const result = groupRoute[2]
          ? { map: await groupProjects.createDocument(groupId, body, user) }
          : await groupProjects.update(groupId, body, user)
        broadcastEvent({ type: 'map-changed', mapId: null, action: 'layout', sourceClientId: requestClientId(request), updatedAt: new Date().toISOString(), updatedBy: publicUser(user) })
        return sendJson(response, groupRoute[2] ? 201 : 200, result)
      }
      return sendJson(response, 405, { error: '지원하지 않는 그룹 요청입니다.' })
    }
    if (request.method === 'GET' && url.pathname === '/api/health') {
      return sendJson(response, 200, {
        status: 'ok',
        publicBaseUrl,
        aionUiWebBaseUrl,
        aionUiWebConfigured: Boolean(configuredAionUiWebBaseUrl),
      })
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/aionui/conversation-display/resolve') {
      if (!hasValidIntegrationBearer(request)) {
        return sendJson(response, 401, { error: '올바른 MindNProgress 연동 토큰이 필요합니다.' })
      }
      const scope = integrationRequestScope(request)
      if (!validAiConversationId(scope.conversationId)) {
        return sendJson(response, 400, {
          error: '현재 AionUi 대화 ID를 확인할 수 없습니다.',
          code: 'AI_CONVERSATION_DISPLAY_ID_REQUIRED',
        })
      }
      return sendJson(response, 200, await resolveAiConversationDisplay(scope.conversationId))
    }

    const aionUiMindNProgressConversationRoute = url.pathname.match(/^\/api\/integrations\/aionui\/conversations\/([^/]+)\/mindnprogress(\/select)?$/)
    if (aionUiMindNProgressConversationRoute && (request.method === 'GET' || request.method === 'POST')) {
      if (!hasValidIntegrationBearer(request)) {
        return sendJson(response, 401, { error: '올바른 MindNProgress 연동 토큰이 필요합니다.' })
      }
      const conversationId = decodeURIComponent(aionUiMindNProgressConversationRoute[1])
      if (!validAiConversationId(conversationId)) {
        return sendJson(response, 400, {
          error: '확인할 AionUi 대화 ID가 올바르지 않습니다.',
          code: 'MNP_AI_CONVERSATION_ID_INVALID',
        })
      }
      const selectionRequested = Boolean(aionUiMindNProgressConversationRoute[2])
      if ((request.method === 'POST') !== selectionRequested) {
        return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
      }
      const navigation = await resolveAiConversationNavigation(conversationId)
      const target = navigation?.target ?? null
      const selectionIdentity = aiConversationSelectionIdentity(request, navigation?.recordedStartedBy)
      if (selectionIdentity.accountMismatch) {
        return sendJson(response, 403, {
          error: '요청에 포함된 MindNProgress 계정이 대화 연결 기록의 계정과 일치하지 않습니다.',
          code: 'MNP_SELECTION_ACCOUNT_MISMATCH',
        })
      }
      if (selectionIdentity.invalidForwardedAddress) {
        return sendJson(response, 400, {
          error: 'AionUi 사용 디바이스의 접속 주소가 올바르지 않습니다.',
          code: 'MNP_SELECTION_DEVICE_ADDRESS_INVALID',
        })
      }
      if (!selectionIdentity.deviceKey) {
        return sendJson(response, 400, {
          error: 'AionUi와 MindNProgress가 같은 디바이스인지 확인할 수 없습니다.',
          code: 'MNP_SELECTION_DEVICE_REQUIRED',
        })
      }
      if (!selectionRequested) {
        const localViewCount = localEventClientCount()
        const matchingViewCount = matchingAiConversationSelectionClientCount(selectionIdentity)
        return sendJson(response, 200, {
          conversationId,
          exists: Boolean(target),
          target,
          selectionAvailable: Boolean(target) && matchingViewCount > 0,
          matchingViewCount,
          localSelectionAvailable: Boolean(target) && localViewCount > 0,
          localViewCount,
          message: target
            ? 'MindNProgress에 연결된 대화입니다.'
            : 'MindNProgress 카드에 연결된 대화를 찾을 수 없습니다.',
        })
      }
      if (!target) {
        return sendJson(response, 404, {
          error: 'MindNProgress 카드에 연결된 대화를 찾을 수 없습니다.',
          code: 'MNP_AI_CONVERSATION_NOT_FOUND',
        })
      }
      if (!selectionIdentity.editorId) {
        return sendJson(response, 400, {
          error: '대화 연결 기록에서 MindNProgress 계정을 확인할 수 없습니다.',
          code: 'MNP_SELECTION_ACCOUNT_REQUIRED',
        })
      }
      if (!selectionIdentity.account) {
        return sendJson(response, 403, {
          error: '선택을 요청한 MindNProgress 계정을 사용할 수 없거나 편집 권한이 없습니다.',
          code: 'MNP_SELECTION_ACCOUNT_UNAVAILABLE',
        })
      }
      const requestedAt = new Date().toISOString()
      const deliveredClientCount = broadcastEvent({
        type: 'ai-conversation-selection-requested',
        conversationId,
        mapId: target.mapId,
        cardId: target.cardId,
        requestedAt,
      }, (client) => (
        client.user.id === selectionIdentity.account.id
        && client.selectionDeviceKey === selectionIdentity.deviceKey
      ))
      if (deliveredClientCount === 0) {
        return sendJson(response, 409, {
          error: '같은 계정과 디바이스로 열린 MindNProgress 화면이 연결되어 있지 않습니다.',
          code: 'MNP_MATCHING_VIEW_NOT_CONNECTED',
          conversationId,
          target,
        })
      }
      return sendJson(response, 200, {
        selected: true,
        conversationId,
        target,
        deliveredClientCount,
        requestedAt,
        message: '같은 계정과 디바이스의 MindNProgress 화면에서 문서와 카드를 선택했습니다.',
      })
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/aionui/conversation-attribution/resolve') {
      if (!hasValidIntegrationBearer(request)) {
        return sendJson(response, 401, { error: '올바른 MindNProgress 연동 토큰이 필요합니다.' })
      }
      const scope = integrationRequestScope(request)
      if (!validAiConversationId(scope.conversationId)) {
        return sendJson(response, 400, {
          error: '현재 AionUi 대화 ID를 확인할 수 없습니다.',
          code: 'AI_ATTRIBUTION_CONVERSATION_REQUIRED',
        })
      }
      if (Boolean(scope.mapId) !== Boolean(scope.cardId)) {
        return sendJson(response, 400, {
          error: 'AI 작성자 귀속 범위를 지정하려면 문서와 카드 ID를 함께 보내야 합니다.',
          code: 'AI_ATTRIBUTION_SCOPE_REQUIRED',
        })
      }
      if (scope.mapId) {
        if (!isValidMapId(scope.mapId)) {
          return sendJson(response, 400, {
            error: 'AI 작성자 귀속을 확인할 문서 ID가 올바르지 않습니다.',
            code: 'AI_ATTRIBUTION_SCOPE_REQUIRED',
          })
        }
        const map = await readMap(scope.mapId)
        if (!map || map.trashedAt || !map.nodes.some((node) => node.id === scope.cardId)) {
          return sendJson(response, 404, {
            error: 'AI 작성자 귀속을 확인할 문서 또는 카드를 찾을 수 없습니다.',
            code: 'AI_ATTRIBUTION_SCOPE_NOT_FOUND',
          })
        }
      }
      const editor = scope.editorId
        ? users.find((candidate) => candidate.id === scope.editorId && candidate.active !== false && canEdit(candidate))
        : null
      if (scope.editorId && !editor) {
        return sendJson(response, 403, {
          error: 'AI 작성자 귀속에 지정된 편집자 계정을 사용할 수 없습니다.',
          code: 'AI_ATTRIBUTION_EDITOR_NOT_FOUND',
        })
      }

      try {
        const existing = resolveScopedAttribution(
          scope,
          [...aiAttributions.values()],
          aiConversationAttributions,
        ).attribution
        const attribution = existing ?? await resolveConversationAttribution(
          scope.mapId,
          scope.cardId,
          scope.conversationId,
          editor?.id ?? null,
          null,
          { inferStartedBy: false },
        )
        const attributionToken = randomBytes(32).toString('base64url')
        const now = Date.now()
        const expiresAt = now + aiAttributionDurationMs
        aiAttributions.set(sessionTokenKey(attributionToken), {
          ...attribution,
          createdAt: now,
          expiresAt,
        })
        await persistAiAttributions()
        console.log('[AI attribution]', JSON.stringify({
          source: existing ? 'conversation-preflight-existing' : 'conversation-preflight',
          mapId: scope.mapId,
          cardId: scope.cardId,
          editorId: editor?.id ?? null,
          conversationId: scope.conversationId,
          actorId: editor?.id ?? integrationUser.id,
          authorName: attribution.authorName,
          tokenHashPrefix: sessionTokenKey(attributionToken).slice(0, 12),
        }))
        return sendJson(response, 201, {
          attributionToken,
          authorName: attribution.authorName,
          editorId: editor?.id ?? null,
          conversationId: scope.conversationId,
          expiresAt,
        })
      } catch (error) {
        console.warn('[AionUi conversation attribution preflight]', JSON.stringify({
          mapId: scope.mapId,
          cardId: scope.cardId,
          editorId: scope.editorId || null,
          conversationId: scope.conversationId,
          error: error?.message ?? String(error),
        }))
        return sendJson(response, 503, {
          error: 'AionUi에서 현재 대화의 AI 종류와 모델을 확인하지 못했습니다.',
          code: 'AI_ATTRIBUTION_UNRESOLVED',
        })
      }
    }

    if (request.method === 'POST' && url.pathname === '/api/auth/login') {
      const body = await readJsonBody(request)
      const user = users.find((candidate) => candidate.email.toLowerCase() === String(body.email ?? '').toLowerCase())
      const suppliedHash = user ? hashPassword(String(body.password ?? ''), user.salt) : hashPassword(String(body.password ?? ''), 'invalid-user')
      if (!user || user.active === false || isPublicViewer(user) || !timingSafeEqual(user.passwordHash, suppliedHash)) {
        return sendJson(response, 401, { error: '이메일 또는 비밀번호가 올바르지 않습니다.' })
      }

      const token = randomBytes(32).toString('base64url')
      const rememberMe = body.rememberMe === true
      const durationMs = rememberMe ? rememberedSessionDurationMs : sessionDurationMs
      const expiresAt = Date.now() + durationMs
      sessions.set(sessionTokenKey(token), { userId: user.id, expiresAt, persistent: rememberMe })
      if (rememberMe) await persistSessions()
      user.lastLoginAt = new Date().toISOString()
      user.updatedAt = user.updatedAt ?? user.lastLoginAt
      await persistUsers()
      return sendJson(response, 200, { user: publicUser(user), rememberMe, expiresAt }, {
        'Set-Cookie': [
          `mnp_session=${token}`,
          'Path=/',
          'HttpOnly',
          'SameSite=Strict',
          ...(rememberMe ? [`Max-Age=${rememberedSessionDurationMs / 1000}`] : []),
        ].join('; '),
      })
    }

    if (request.method === 'POST' && url.pathname === '/api/auth/viewer-access') {
      const viewer = users.find((candidate) => candidate.id === 'user-public-viewer' && isPublicViewer(candidate) && candidate.active !== false)
      if (!viewer) return sendJson(response, 503, { error: '공개 뷰어 계정이 준비되지 않았습니다.' })
      const token = randomBytes(32).toString('base64url')
      sessions.set(sessionTokenKey(token), { userId: viewer.id, expiresAt: Date.now() + sessionDurationMs, persistent: false })
      return sendJson(response, 200, { user: publicUser(viewer) }, {
        'Set-Cookie': `mnp_session=${token}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${sessionDurationMs / 1000}`,
      })
    }

    if (request.method === 'GET' && url.pathname === '/api/auth/me') {
      const user = getCurrentUser(request)
      return sendJson(response, 200, { user: user ? publicUser(user) : null })
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/dooray/task-preview') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 Dooray 업무를 추가할 수 있습니다.' })
      const body = await readJsonBody(request)
      try {
        const parsed = parseDoorayTaskUrl(body.url)
        const task = await fetchDoorayTaskPreview(parsed, await getDoorayApiConfig())
        return sendJson(response, 200, { task })
      } catch (error) {
        if (error instanceof DoorayTaskError) return sendJson(response, error.status, { error: error.message, code: error.code })
        throw error
      }
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/dooray/wiki-preview') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 Dooray Wiki를 추가할 수 있습니다.' })
      const body = await readJsonBody(request)
      try {
        const parsed = parseDoorayWikiUrl(body.url)
        const wiki = await fetchDoorayWikiPreview(parsed, await getDoorayApiConfig())
        return sendJson(response, 200, { wiki })
      } catch (error) {
        if (error instanceof DoorayTaskError) return sendJson(response, error.status, { error: error.message, code: error.code })
        throw error
      }
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/dooray/task-titles') {
      const user = requireUser(request, response)
      if (!user) return
      const body = await readJsonBody(request)
      if (!Array.isArray(body.urls) || body.urls.length === 0 || body.urls.length > doorayTaskTitleBatchLimit) {
        return sendJson(response, 400, { error: `Dooray 업무 URL은 한 번에 1~${doorayTaskTitleBatchLimit}개까지 조회할 수 있습니다.` })
      }

      let tasks
      try {
        const parsedTaskMap = new Map()
        body.urls.forEach((taskUrl) => {
          const parsed = parseDoorayTaskUrl(taskUrl)
          if (!parsedTaskMap.has(parsed.labelKey)) parsedTaskMap.set(parsed.labelKey, parsed)
        })
        const parsedTasks = [...parsedTaskMap.values()]
        const config = await getDoorayApiConfig()
        const taskRequests = new Map()
        const getTask = (parsed) => {
          if (!taskRequests.has(parsed.key)) taskRequests.set(parsed.key, resolveDoorayTaskPreview(parsed, config))
          return taskRequests.get(parsed.key)
        }
        tasks = (await Promise.all(parsedTasks.map(async (parsed) => {
          try {
            const task = await getTask(parsed)
            const comment = await resolveDoorayComment(parsed, task, config).catch(() => null)
            return {
              key: parsed.labelKey,
              url: parsed.url,
              title: task.subject,
              ...(parsed.commentId ? { comment: comment ?? { id: parsed.commentId, authorName: '' } } : {}),
            }
          } catch (error) {
            if (error instanceof DoorayTaskError) return null
            throw error
          }
        }))).filter(Boolean)
      } catch (error) {
        if (error instanceof DoorayTaskError) return sendJson(response, error.status, { error: error.message, code: error.code })
        throw error
      }
      return sendJson(response, 200, { tasks })
    }

    if (request.method === 'GET' && url.pathname === '/api/integrations/dooray/mentions') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: 'Dooray 참조는 계정 사용자만 확인할 수 있습니다.' })
      const state = await readDoorayMentionState(user.id)
      return sendJson(response, 200, doorayMentionResponse(state, user.id))
    }

    const doorayApprovalContextRoute = url.pathname.match(/^\/api\/integrations\/dooray\/response-approvals\/([a-zA-Z0-9_-]+)$/)
    if (doorayApprovalContextRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 승인 기록을 확인할 수 있습니다.' })
      try {
        const result = await doorayResponses.approvalContext(user.id, doorayApprovalContextRoute[1], url.searchParams.get('revision'), {
          execution: url.searchParams.get('execution') === '1', conversationId: url.searchParams.get('conversationId'),
          handoffId: url.searchParams.get('handoffId'),
        })
        return sendJson(response, 200, result)
      } catch (error) { return sendJson(response, error.status ?? 500, { error: error.message }) }
    }

    const doorayResponseRoute = url.pathname.match(/^\/api\/integrations\/dooray\/mentions\/responses(?:\/([a-zA-Z0-9_-]+)\/(retry|refine|complete|handoff|execution-handoff|approve))?$/)
    if (doorayResponseRoute) {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user) || isPublicViewer(user)) return sendJson(response, 403, { error: '편집자만 AI 대응을 요청할 수 있습니다.' })
      try {
        if (doorayResponseRoute[2] === 'execution-handoff') {
          if (request.method === 'GET') return sendJson(response, 200, await doorayResponses.executionHandoffOptions(user.id, doorayResponseRoute[1], url.searchParams.get('mapId')))
          if (request.method === 'POST') return sendJson(response, 200, await doorayResponses.prepareExecutionHandoff(user.id, doorayResponseRoute[1], await readJsonBody(request)))
          return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
        }
        if (doorayResponseRoute[2] === 'handoff') {
          if (request.method === 'GET') return sendJson(response, 200, await doorayResponses.handoffOptions(user.id, doorayResponseRoute[1]))
          if (request.method === 'POST') {
            const body = await readJsonBody(request)
            return sendJson(response, 202, await doorayResponses.handoff(user.id, doorayResponseRoute[1], body.conversationId))
          }
          return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
        }
        if (request.method === 'GET' && !doorayResponseRoute[1]) {
          return sendJson(response, 200, { jobs: await doorayResponses.list(user.id) })
        }
        if (request.method === 'POST' && doorayResponseRoute[1]) {
          if (doorayResponseRoute[2] === 'approve') {
            const body = await readJsonBody(request)
            return sendJson(response, 200, { job: await doorayResponses.approve(user.id, doorayResponseRoute[1], body.proposalRevision) })
          }
          if (doorayResponseRoute[2] === 'complete') return sendJson(response, 200, { job: await doorayResponses.complete(user.id, doorayResponseRoute[1]) })
          if (doorayResponseRoute[2] === 'refine') {
            const body = await readJsonBody(request)
            return sendJson(response, 202, { job: await doorayResponses.refine(user.id, doorayResponseRoute[1], body.hint) })
          }
          await doorayResponses.retry(user.id, doorayResponseRoute[1])
          return sendJson(response, 202, { jobs: await doorayResponses.list(user.id) })
        }
        if (request.method === 'POST' && !doorayResponseRoute[1]) {
          const body = await readJsonBody(request)
          const state = await readDoorayMentionState(user.id)
          const item = state.items.find((entry) => entry.key === body.itemKey)
          if (!item) return sendJson(response, 404, { error: '수집 결과에 없는 참조입니다. 다시 수집해 주세요.' })
          return sendJson(response, 202, await doorayResponses.start(user, item, body.settings ?? {}))
        }
        return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
      } catch (error) {
        return sendJson(response, error.status ?? 502, { error: error.message ?? 'AI 대응 요청에 실패했습니다.' })
      }
    }

    if (url.pathname === '/api/integrations/dooray/mentions/projects') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: 'Dooray 참조는 계정 사용자만 확인할 수 있습니다.' })

      if (request.method === 'GET') {
        try {
          const result = await listDoorayMentionProjects(await getDoorayApiConfig())
          const availableIds = new Set(result.projects.map((project) => project.id))
          let state = await readDoorayMentionState(user.id)
          const selectedProjectIds = state.selectedProjectIds.filter((id) => availableIds.has(id))
          // 프로젝트에서 제외되면 계정에 저장된 선택에서도 제거한다. 새로 초대된 프로젝트는
          // 목록에만 나타나고 사용자가 직접 고르기 전까지 선택하지 않는다.
          if (selectedProjectIds.length !== state.selectedProjectIds.length) {
            state = await updateDoorayMentionState(user.id, (latestState) => ({
              ...latestState,
              selectedProjectIds: latestState.selectedProjectIds.filter((id) => availableIds.has(id)),
            }))
          }
          return sendJson(response, 200, {
            projects: result.projects,
            selectedProjectIds: state.selectedProjectIds,
            maxSelectedProjects: doorayMentionProjectLimit,
          })
        } catch (error) {
          if (error instanceof DoorayTaskError) return sendJson(response, error.status, { error: error.message, code: error.code })
          throw error
        }
      }

      if (request.method === 'PUT') {
        const body = await readJsonBody(request)
        if (!Array.isArray(body.projectIds)) {
          return sendJson(response, 400, { error: '저장할 프로젝트 목록을 지정해 주세요.' })
        }
        const selectedProjectIds = [...new Set(
          body.projectIds.map((value) => String(value ?? '').trim().slice(0, 120)).filter(Boolean),
        )].slice(0, doorayMentionProjectLimit)
        await updateDoorayMentionState(user.id, (state) => ({ ...state, selectedProjectIds }))
        return sendJson(response, 200, { selectedProjectIds })
      }

      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    if (request.method === 'PUT' && url.pathname === '/api/integrations/dooray/mentions/preferences') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: 'Dooray 참조는 계정 사용자만 확인할 수 있습니다.' })
      const preferences = normalizeDoorayMentionPreferences(await readJsonBody(request))
      if (!preferences) return sendJson(response, 400, { error: '저장할 조회 조건이 올바르지 않습니다.' })
      await updateDoorayMentionState(user.id, (state) => ({ ...state, preferences }))
      return sendJson(response, 200, { preferences })
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/dooray/mentions/scan') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: 'Dooray 참조는 계정 사용자만 확인할 수 있습니다.' })
      if (doorayMentionScanState(user.id).status === 'running') {
        return sendJson(response, 409, { error: '이미 수집이 진행 중입니다.', code: 'SCAN_RUNNING' })
      }
      const body = await readJsonBody(request)
      const storedState = await readDoorayMentionState(user.id)
      const requestedProjectIds = Array.isArray(body.projectIds)
        ? body.projectIds
        : Array.isArray(body.projectCodes) ? body.projectCodes : storedState.selectedProjectIds
      const projectIds = [...new Set(
        requestedProjectIds.map((value) => String(value ?? '').trim()).filter(Boolean),
      )].slice(0, doorayMentionProjectLimit)
      if (projectIds.length === 0) {
        return sendJson(response, 400, {
          error: '탐색할 프로젝트를 하나 이상 선택해 주세요.',
          code: 'PROJECT_SELECTION_REQUIRED',
        })
      }
      let range
      try {
        range = normalizeDoorayMentionRange({ since: body.since, until: body.until })
        const config = await getDoorayApiConfig()
        if (!config.apiKey) {
          throw new DoorayTaskError('CONFIG_UNAVAILABLE', 'Dooray API 키가 설정되어 있지 않습니다.', 503)
        }
      } catch (error) {
        if (error instanceof DoorayTaskError) return sendJson(response, error.status, { error: error.message, code: error.code })
        throw error
      }
      const includeAssigned = body.includeAssigned !== false
      const options = {
        since: range.since,
        until: range.until,
        projectIds,
        includeBody: body.includeBody !== false,
        includeComments: body.includeComments !== false,
        includeAssigned,
        // 이전 클라이언트는 담당과 참조를 includeAssigned 하나로 보냈다.
        includeCc: body.includeCc === undefined ? includeAssigned : body.includeCc !== false,
      }
      const scan = updateDoorayMentionScan(user.id, {
        status: 'running',
        phase: 'me',
        done: 0,
        total: 0,
        startedAt: new Date().toISOString(),
        finishedAt: null,
        error: null,
      })
      // 수집은 수 분이 걸릴 수 있어 응답을 붙잡지 않고 진행 상황은 조회 API로 노출한다.
      void runtimeLifecycle.track(() => runDoorayMentionScan(user.id, options))
      return sendJson(response, 202, { scan, ...options })
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/dooray/mentions/acknowledgements') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: 'Dooray 참조는 계정 사용자만 확인할 수 있습니다.' })
      const body = await readJsonBody(request)
      const keys = Array.isArray(body.keys)
        ? [...new Set(body.keys.map((value) => String(value ?? '').trim()).filter(Boolean))]
        : []
      if (keys.length === 0) return sendJson(response, 400, { error: '확인할 항목을 지정해 주세요.' })
      let nextState
      try {
        nextState = await updateDoorayMentionState(user.id, (state) => {
          const known = new Set(state.items.map((item) => item.key))
          const unknown = keys.filter((key) => !known.has(key))
          if (unknown.length > 0) {
            throw new DoorayTaskError('MENTION_NOT_FOUND', '수집 결과에 없는 항목입니다.', 404)
          }
          const acknowledgements = { ...state.acknowledgements }
          const acknowledgedAt = new Date().toISOString()
          for (const key of keys) {
            if (body.acknowledged === false) delete acknowledgements[key]
            else acknowledgements[key] = { acknowledgedAt }
          }
          return { ...state, acknowledgements }
        })
      } catch (error) {
        if (error instanceof DoorayTaskError) {
          return sendJson(response, error.status, { error: error.message, code: error.code })
        }
        throw error
      }
      return sendJson(response, 200, doorayMentionResponse(nextState, user.id))
    }

    if (request.method === 'GET' && url.pathname === '/api/integrations/aionui/subscription-usage') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 구독 사용량을 확인할 수 있습니다.' })
      const usage = await readAionUiSubscriptionUsage(aionUiSubscriptionUsageFile, {
        readText: (filePath) => readFile(filePath, 'utf8'),
        staleAfterMs: aionUiSubscriptionUsageStaleAfterMs,
      })
      return sendJson(response, 200, { usage })
    }

    if (request.method === 'GET' && url.pathname === '/api/users') {
      const user = requireUser(request, response)
      if (!user) return
      return sendJson(response, 200, { users: users.filter((candidate) => candidate.active !== false && !isPublicViewer(candidate)).map(publicUser) })
    }

    if (request.method === 'GET' && url.pathname === '/api/assignees') {
      const user = requireUser(request, response)
      if (!user) return
      return sendJson(response, 200, { users: users.filter((candidate) => candidate.role === 'editor').map(accountUser) })
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/aionui/attributions') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화를 시작할 수 있습니다.' })
      const body = await readJsonBody(request)
      const agentId = String(body.agentId ?? '').trim().slice(0, 120)
      const modelId = String(body.modelId ?? '').trim().slice(0, 240)
      const providerId = String(body.providerId ?? '').trim().slice(0, 120)
      const mapId = String(body.mapId ?? '').trim().slice(0, 120)
      const cardId = String(body.cardId ?? '').trim().slice(0, 120)
      const purpose = body.purpose === undefined ? 'card' : String(body.purpose).trim()
      let doorayApprovalContext = null
      if (purpose === 'dooray-response') {
        // 문서가 아직 없는 구성 제안도 지원하되 임의의 카드로 귀속하지 않는다.
        try {
          doorayApprovalContext = await doorayResponses.approvalContext(user.id, body.doorayApproval?.responseId, body.doorayApproval?.proposalRevision, { handoffId: body.doorayApproval?.handoffId })
          if (doorayApprovalContext.launch.mapId !== mapId || doorayApprovalContext.launch.cardId !== cardId) return sendJson(response, 409, { error: '승인한 담당 경로와 대화 시작 대상이 다릅니다.' })
          if (doorayApprovalContext.linkedConversation) return sendJson(response, 409, { error: '이미 시작한 승인 대화가 있습니다. 해당 대화에서 이어가 주세요.' })
          assertDoorayExecutionWorkspace(body.workspace)
        } catch (error) { return sendJson(response, error.status ?? 500, { error: error.message }) }
      }
      if (!agentId || !modelId || (!doorayApprovalContext && (!isValidMapId(mapId) || !cardId))) {
        return sendJson(response, 400, { error: 'AI 종류, 모델, 문서와 카드를 모두 지정해 주세요.' })
      }
      if (!isAiConversationPurpose(purpose)) {
        return sendJson(response, 400, { error: 'AI 대화 용도가 올바르지 않습니다.' })
      }
      const map = mapId ? await readMap(mapId) : null
      if ((!doorayApprovalContext || mapId) && (!map || map.trashedAt || (doorayApprovalContext && map.archivedAt) || !map.nodes.some((node) => node.id === cardId))) {
        return sendJson(response, 404, { error: 'AI 대화를 시작할 문서 또는 카드를 찾을 수 없습니다.' })
      }
      if (purpose === 'group-coordination') {
        const project = await groupProjects.forDocument(mapId)
        if (project?.role !== 'coordinator' || documentRoot(map)?.id !== cardId) return sendJson(response, 400, { error: '그룹 총괄 대화는 연결된 통합 관리 문서의 루트에서 시작해야 합니다.' })
      }
      if (purpose === 'shared-knowledge-review') {
        try {
          buildSharedKnowledgeReviewContext(map, cardId)
        } catch (error) {
          if (sendSharedKnowledgeMaintenanceError(response, error)) return
          throw error
        }
      }
      if (purpose === 'document-reconstruction') {
        const draftRequest = reconstructionRequests.get(String(body.reconstructionRequestId ?? ''))
        if (draftRequest.createdBy.id !== user.id || draftRequest.launchTarget.mapId !== mapId || draftRequest.launchTarget.cardId !== cardId) return sendJson(response, 403, { error: '정리 요청의 편집자와 시작 대상을 확인하세요.' })
        documentReconstruction.assertWritable(mapId)
      }

      if (purpose === 'card-layout') {
        const draftRequest = await cardLayoutRequests.get(String(body.cardLayoutRequestId ?? ''), publicUser(user))
        if (draftRequest.stale || draftRequest.state !== 'open' || !draftRequest.measurements || draftRequest.conversation || draftRequest.launchTarget.mapId !== mapId || draftRequest.launchTarget.cardId !== cardId) return sendJson(response, 409, { error: '배치 요청의 측정·대상·최신 상태를 확인하세요.' })
        documentReconstruction.assertWritable(mapId)
      }
      try {
        const { machineId: homeMachineId } = resolveTargetMachineForUser(user, body.machineId)
        try { body.workspace = await aiWorkspaceSettings.validateLaunch({ ...body, mapId, machineId: homeMachineId }) }
        catch (error) { return sendJson(response, error.status ?? 400, { error: error.message, code: 'AI_WORKSPACE_SELECTION_REQUIRED' }) }
        const [agents, providers, skills, mcpServers] = await Promise.all([
          fetchAionUiOn(homeMachineId, '/api/agents/management'),
          fetchAionUiOn(homeMachineId, '/api/providers'),
          fetchAionUiOn(homeMachineId, '/api/skills'),
          fetchAionUiOn(homeMachineId, '/api/mcp/servers'),
        ])
        const normalizedAgents = (Array.isArray(agents) ? agents : [])
          .filter((agent) => agent?.enabled !== false && agent?.installed === true)
          .map((agent) => normalizeAionUiAgent(agent, Array.isArray(providers) ? providers.filter((item) => item?.enabled !== false) : []))
        const normalizedSkills = normalizeAionUiSkills(skills)
        const normalizedMcpServers = normalizeAionUiMcpServers(mcpServers)
        const agent = normalizedAgents.find((candidate) => candidate.id === agentId)
        const model = agent?.models.find((candidate) => candidate.id === modelId
          && (!providerId || !candidate.providerId || candidate.providerId === providerId))
        if (!agent || !model) return sendJson(response, 400, { error: '선택한 AI 종류 또는 모델을 AionUi에서 확인할 수 없습니다.' })

        const agentName = agent.name.replace(/\s+/g, ' ').trim().slice(0, 80) || agent.id
        const modelName = model.label.replace(/\s+/g, ' ').trim().slice(0, 120) || model.id
        const authorName = `${agentName}(${modelName})`
        const attributionToken = randomBytes(32).toString('base64url')
        const completionToken = randomBytes(32).toString('base64url')
        const expiresAt = Date.now() + aiAttributionDurationMs
        for (const [tokenKey, attribution] of aiAttributions) {
          if (attribution.expiresAt <= Date.now()) aiAttributions.delete(tokenKey)
        }
        for (const [tokenKey, launch] of aiConversationLaunches) {
          if (launch.expiresAt <= Date.now()) aiConversationLaunches.delete(tokenKey)
        }
        aiAttributions.set(sessionTokenKey(attributionToken), {
          authorName,
          agentId: agent.id,
          agentName,
          modelId: model.id,
          modelName,
          providerId: model.providerId ?? null,
          mapId,
          cardId,
          homeMachineId,
          startedBy: user.id,
          selection: aiConversationSelectionSnapshot(body, agent, model, normalizedSkills, normalizedMcpServers),
          createdAt: Date.now(),
          expiresAt,
        })
        aiConversationLaunches.set(sessionTokenKey(completionToken), {
          attributionKey: sessionTokenKey(attributionToken),
          mapId,
          cardId,
          homeMachineId,
          purpose,
          reconstructionRequestId: purpose === 'document-reconstruction' ? body.reconstructionRequestId : undefined,
          cardLayoutRequestId: purpose === 'card-layout' ? body.cardLayoutRequestId : undefined,
          doorayApproval: doorayApprovalContext ? body.doorayApproval : undefined,
          startedBy: user.id,
          expiresAt,
        })
        const completionBaseUrl = homeMachineId === machineRegistry.mainMachineId
          ? `http://127.0.0.1:${port}`
          : runnerCallbackBaseUrlForMachine(homeMachineId)
        if (!completionBaseUrl) {
          throw new SubMachinePayloadError('서브 머신의 AionUi Runner를 최신 버전으로 다시 시작한 뒤 시도해 주세요.')
        }
        const completionUrl = `${completionBaseUrl}/api/integrations/aionui/launches/${completionToken}/conversation`
        aiConversationLaunches.get(sessionTokenKey(completionToken)).completionUrl = completionUrl
        await persistAiAttributions()
        console.log('[AI attribution]', JSON.stringify({
          source: 'created', mapId, cardId, actorId: user.id, authorName,
          tokenHashPrefix: sessionTokenKey(attributionToken).slice(0, 12),
        }))
        return sendJson(response, 201, {
          attributionToken,
          completionUrl,
          authorName,
          editorId: user.id,
          homeMachineId,
          homeMachineLabel: machineLabel(homeMachineId),
          workspace: body.workspace,
          ...(doorayApprovalContext ? { approvalRequest: doorayApprovalContext.launch.initialRequest } : {}),
          expiresAt,
        })
      } catch (error) {
        if (error instanceof SubMachinePayloadError) return sendJson(response, 400, { error: error.message })
        console.error('[AionUi attribution]', error)
        return sendJson(response, 503, { error: 'AionUi에서 선택한 AI 정보를 확인할 수 없습니다.' })
      }
    }

    if (request.method === 'POST' && url.pathname === '/api/integrations/aionui/external-conversation-launches') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화를 시작할 수 있습니다.' })

      try {
        const payload = normalizeAionUiExternalLaunchPayload(await readJsonBody(request))
        const completionToken = parseMindNProgressCompletionToken(payload.completionUrl, [
          `http://127.0.0.1:${port}`,
          publicBaseUrl,
          ...runnerCallbackBaseUrls.values(),
        ])
        if (!completionToken) {
          return sendJson(response, 400, { error: 'AI 대화 완료 통보 주소가 올바르지 않습니다.' })
        }

        const launch = aiConversationLaunches.get(sessionTokenKey(completionToken))
        if (!launch || launch.expiresAt <= Date.now()) {
          if (launch) aiConversationLaunches.delete(sessionTokenKey(completionToken))
          return sendJson(response, 404, { error: 'AI 대화 시작 정보를 찾을 수 없습니다. 다시 시도해 주세요.' })
        }
        if (launch.startedBy !== user.id) {
          return sendJson(response, 403, { error: '다른 편집자의 AI 대화 시작 정보는 사용할 수 없습니다.' })
        }
        if (payload.completionUrl !== launch.completionUrl) {
          return sendJson(response, 409, { error: 'AI 대화 완료 통보 주소가 발급 정보와 일치하지 않습니다.' })
        }

        const attribution = aiAttributions.get(launch.attributionKey)
        if (!attribution
          || attribution.agentId !== payload.agentId
          || attribution.modelId !== payload.modelId
          || (payload.providerId && attribution.providerId && attribution.providerId !== payload.providerId)) {
          return sendJson(response, 409, { error: 'AI 종류와 모델 정보가 작성자 귀속 정보와 일치하지 않습니다.' })
        }

        if (launch.doorayApproval) {
          const context = await doorayResponses.approvalContext(user.id, launch.doorayApproval.responseId, launch.doorayApproval.proposalRevision, { handoffId: launch.doorayApproval.handoffId })
          if (context.linkedConversation) return sendJson(response, 409, { error: '이미 연결된 승인 대화에서 이어가 주세요.' })
          assertDoorayExecutionWorkspace(payload.workspace)
          if (!sameExecutionWorkspace(attribution.selection?.workspace, payload.workspace)) return sendJson(response, 409, { error: '확인한 작업공간과 실행할 작업공간이 다릅니다. 다시 시작해 주세요.' })
          if (!payload.prompt.includes(context.launch.initialRequest)) return sendJson(response, 409, { error: '승인 전문이 변경되거나 누락되었습니다. 다시 확인해 주세요.' })
        }
        if (!sameExecutionWorkspace(attribution.selection?.workspace, payload.workspace)) return sendJson(response, 409, { error: '확인한 작업공간과 실행 경로가 다릅니다. 다시 시작해 주세요.' })
        const ticket = await fetchAionUiOn(launch.homeMachineId, '/api/internal/external-conversation-launches', {
          method: 'POST',
          body: payload,
        })
        const launchUrl = createAionUiWebLaunchUrl(aionUiWebBaseUrlForMachine(launch.homeMachineId), ticket?.launchId)
        return sendJson(response, 201, {
          launchId: ticket.launchId,
          expiresAt: ticket.expiresAt ?? null,
          launchUrl,
          homeMachineId: launch.homeMachineId,
          homeMachineLabel: machineLabel(launch.homeMachineId),
        })
      } catch (error) {
        if (error instanceof AionUiExternalLaunchPayloadError) {
          return sendJson(response, 400, { error: error.message })
        }
        if (error instanceof SubMachinePayloadError) {
          return sendJson(response, 503, { error: error.message })
        }
        // 완료·변경된 승인으로 시작하려는 요청은 외부 서버 장애가 아닌 승인 충돌이다.
        if (error.status === 409) return sendJson(response, 409, { error: error.message })
        console.error('[AionUi external conversation launch]', error)
        return sendJson(response, 503, { error: 'AionUi WebUI 대화 시작 정보를 발급하지 못했습니다.' })
      }
    }

    const aionUiLaunchCompletionRoute = url.pathname.match(/^\/api\/integrations\/aionui\/launches\/([^/]+)\/conversation$/)
    if (aionUiLaunchCompletionRoute && request.method === 'POST') {
      const tokenKey = sessionTokenKey(decodeURIComponent(aionUiLaunchCompletionRoute[1]))
      const launch = aiConversationLaunches.get(tokenKey)
      if (!launch || launch.expiresAt <= Date.now()) {
        aiConversationLaunches.delete(tokenKey)
        return sendJson(response, 404, { error: 'AI 대화 시작 정보를 찾을 수 없습니다.' })
      }
      const body = await readJsonBody(request)
      const conversationId = String(body.conversationId ?? '').trim()
      if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(conversationId)) {
        return sendJson(response, 400, { error: '올바르지 않은 AionUi 대화 ID입니다.' })
      }

      try {
        const conversation = await fetchAionUiOn(
          launch.homeMachineId,
          `/api/conversations/${encodeURIComponent(conversationId)}`,
        )
        if (!conversation || conversation.id !== conversationId) {
          return sendJson(response, 409, { error: '생성된 AionUi 대화를 확인할 수 없습니다.' })
        }
        if (launch.purpose === 'dooray-response') {
          const actualWorkspace = aiConversationLinkFromAionUiConversation(conversation)?.workspace
          assertDoorayExecutionWorkspace(actualWorkspace)
          if (!sameExecutionWorkspace(aiAttributions.get(launch.attributionKey)?.selection?.workspace, actualWorkspace)) return sendJson(response, 409, { error: '생성된 대화의 작업공간이 시작 요청과 다릅니다.' })
          const approvalOptions = { handoffId: launch.doorayApproval.handoffId }
          const context = await doorayResponses.approvalContext(launch.startedBy, launch.doorayApproval.responseId, launch.doorayApproval.proposalRevision, approvalOptions)
          if (context.linkedConversation && context.linkedConversation.conversationId !== conversationId) return sendJson(response, 409, { error: '이미 연결된 승인 대화가 있습니다.' })
          // 담당이 없을 때만 구성용 대화로 연결한다. 담당이 있으면 아래 공통 카드
          // 연결·시작 카드 저장을 모두 마친 뒤 승인 실행을 허용한다.
          if (!launch.mapId && !launch.cardId) {
            await doorayResponses.linkApprovalConversation(launch.startedBy, launch.doorayApproval.responseId, launch.doorayApproval.proposalRevision,
              { conversationId, homeMachineId: launch.homeMachineId, homeMachineRole: launch.homeMachineId === machineRegistry.mainMachineId ? 'main' : 'sub', linkedAt: new Date().toISOString() }, approvalOptions)
            const attribution = aiAttributions.get(launch.attributionKey)
            if (attribution) { attribution.conversationId = conversationId; await persistAiAttributions() }
            return sendJson(response, 200, { conversationId, linked: true, purpose: launch.purpose })
          }
        }
        const map = await readMap(launch.mapId)
        const targetNode = map?.nodes.find((node) => node.id === launch.cardId)
        if (!map || map.trashedAt || !targetNode) {
          aiConversationLaunches.delete(tokenKey)
          return sendJson(response, 404, { error: 'AI 대화를 연결할 문서 또는 카드를 찾을 수 없습니다.' })
        }
        const attribution = aiAttributions.get(launch.attributionKey)
        const origin = aiConversationOrigins.get(conversationId)
        if (origin && (origin.mapId !== launch.mapId || origin.cardId !== launch.cardId)) return sendJson(response, 409, { error: '다른 카드에서 시작한 대화의 소속을 변경할 수 없습니다.' })
        if (attribution) {
          attribution.conversationId = conversationId
          await persistAiAttributions()
        }
        if (launch.purpose === 'document-reconstruction') {
          await reconstructionRequests.linkConversation(launch.reconstructionRequestId, { id: conversationId, homeMachineId: launch.homeMachineId, linkedAt: new Date().toISOString() })
        }
        if (launch.purpose === 'card-layout') {
          await cardLayoutRequests.linkConversation(launch.cardLayoutRequestId, { id: conversationId, homeMachineId: launch.homeMachineId, linkedAt: new Date().toISOString() }, { id: launch.startedBy })
        }
        if (launch.purpose === 'shared-knowledge-review' || launch.purpose === 'document-reconstruction' || launch.purpose === 'card-layout') {
          rememberAiConversationOrigin({
            conversationId,
            mapId: launch.mapId,
            cardId: launch.cardId,
            startedBy: launch.startedBy,
            linkedAt: new Date().toISOString(),
            homeMachineId: launch.homeMachineId,
          })
          await persistAiConversationOrigins()
          aiConversationLaunches.delete(tokenKey)
          return sendJson(response, 200, {
            conversationId,
            linked: false,
            purpose: launch.purpose,
          })
        }

        const actor = users.find((candidate) => candidate.id === launch.startedBy) ?? integrationUser
        const selection = attribution?.selection ?? {
          agent: attribution?.agentId ? { id: attribution.agentId, label: attribution.agentName ?? attribution.agentId } : null,
          model: attribution?.modelId ? { id: attribution.modelId, label: attribution.modelName ?? attribution.modelId } : null,
          providerId: attribution?.providerId ?? null,
          skills: [],
          mcpServers: [],
        }
        const conversationLink = normalizeAiConversationLink({
          conversationId,
          homeMachineId: launch.homeMachineId,
          ...selection,
          startedBy: { id: actor.id, label: actor.name },
          startedAt: normalizedIsoDate(conversation.created_at),
          linkedAt: new Date().toISOString(),
        })
        const updatedMap = isAiConversationLinked(targetNode.data, conversationId) ? map : await saveMap(launch.mapId, {
          nodes: map.nodes.map((node) => node.id === launch.cardId
            ? {
                ...node,
                data: {
                  ...node.data,
                  aiConversationId: conversationId,
                  aiConversations: appendAiConversationLink(node.data, conversationLink),
                },
              }
            : node),
          edges: map.edges,
        }, actor, map.title, map.color, 'content')
        rememberAiConversationOrigin({
          conversationId,
          mapId: launch.mapId,
          cardId: launch.cardId,
          startedBy: launch.startedBy,
          linkedAt: conversationLink.startedAt ?? conversationLink.linkedAt,
          workspace: conversationLink.workspace,
          workspacePoolId: workspacePoolManager.poolForWorkspace(conversationLink.workspace)?.poolId ?? null,
          homeMachineId: launch.homeMachineId,
        })
        await persistAiConversationOrigins()
        if (attribution) {
          try {
            await refreshConversationAttribution(launch.mapId, launch.cardId, conversationId, launch.startedBy, attribution)
          } catch (error) {
            const fallbackAttribution = {
              mapId: launch.mapId,
              cardId: launch.cardId,
              conversationId,
              authorName: attribution.authorName,
              agentId: attribution.agentId,
              agentName: attribution.agentName,
              modelId: attribution.modelId,
              modelName: attribution.modelName,
              providerId: attribution.providerId ?? null,
              homeMachineId: launch.homeMachineId,
              startedBy: launch.startedBy,
              linkedAt: normalizedIsoDate(conversation.created_at),
              refreshedAt: new Date().toISOString(),
            }
            aiConversationAttributions.set(conversationAttributionKey(launch.mapId, launch.cardId), fallbackAttribution)
            await persistAiConversationAttributions()
            console.warn('[AI conversation attribution link]', error)
          }
        }
        if (launch.purpose === 'dooray-response') {
          await doorayResponses.linkApprovalConversation(launch.startedBy, launch.doorayApproval.responseId, launch.doorayApproval.proposalRevision,
            { conversationId, mapId: launch.mapId, cardId: launch.cardId, homeMachineId: launch.homeMachineId,
              homeMachineRole: launch.homeMachineId === machineRegistry.mainMachineId ? 'main' : 'sub', linkedAt: conversationLink.linkedAt },
            { handoffId: launch.doorayApproval.handoffId })
        } else aiConversationLaunches.delete(tokenKey)
        broadcastEvent({
          type: 'ai-conversation-linked',
          mapId: launch.mapId,
          nodeId: launch.cardId,
          conversationId,
          conversation: conversationLink,
          sourceClientId: null,
          updatedAt: updatedMap.updatedAt,
          updatedBy: publicUser(actor),
        })
        void runtimeLifecycle.track(() => refreshAiConversationRuntimeForMap(launch.mapId)).catch((error) => {
          console.warn('[AI conversation runtime link refresh]', error)
        })
        return sendJson(response, 200, { conversationId, homeMachineId: launch.homeMachineId })
      } catch (error) {
        console.error('[AionUi conversation completion]', error)
        return sendJson(response, error.status ?? 503, { error: error.status ? error.message : '생성된 AionUi 대화를 확인하지 못했습니다.' })
      }
    }

    const aionUiConversationTranscriptRoute = url.pathname.match(/^\/api\/integrations\/aionui\/conversations\/([^/]+)\/transcript$/)

    const groupDocumentInstructionsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/group-document-instructions$/)
    const aiDelegationsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/ai-delegations$/)
    const aiDelegationCompletionRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/ai-delegations\/complete$/)
    const aiDelegationRecoveryRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/ai-delegations\/([^/]+)\/recover$/)
    const aiWorkspacesRoute = url.pathname === '/api/ai-workspaces'
    const aiWorkspaceCheckpointRoute = url.pathname.match(/^\/api\/ai-workspaces\/([^/]+)\/checkpoint$/)

    if (request.method === 'POST' && url.pathname === '/api/internal/ai-workspaces/synchronize-idle') {
      if (!hasValidIntegrationBearer(request)) {
        return sendJson(response, 401, { error: '올바른 MindNProgress 연동 토큰이 필요합니다.' })
      }
      const body = await readJsonBody(request)
      if (body.workspaceIds !== undefined && (!Array.isArray(body.workspaceIds) || body.workspaceIds.length > 100)) {
        return sendJson(response, 400, {
          error: 'workspaceIds는 최대 100개의 작업공간 ID 배열이어야 합니다.',
          code: 'AI_WORKSPACE_SYNC_INPUT_INVALID',
        })
      }
      try {
        const result = await workspacePoolManager.synchronizeIdleWorkersToIntegration({
          workspaceIds: body.workspaceIds,
        })
        return sendJson(response, 200, result)
      } catch (error) {
        if (error instanceof WorkspacePoolUnavailableError) {
          return sendJson(response, 409, {
            error: error.message,
            code: error.reasonCode ?? error.code,
            details: error.details,
          })
        }
        throw error
      }
    }

    if (aiWorkspacesRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 작업공간 풀을 조회할 수 있습니다.' })
      const scope = integrationRequestScope(request)
      return sendJson(response, 200, workspacePoolManager.publicSnapshot({
        conversationId: scope.conversationId,
      }))
    }

    if (aiWorkspaceCheckpointRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 작업공간 체크포인트를 생성할 수 있습니다.' })
      const leaseId = decodeURIComponent(aiWorkspaceCheckpointRoute[1])
      const scope = integrationRequestScope(request)
      const source = scope.mapId && scope.conversationId
        ? delegationSourceForRequest(scope, scope.mapId)
        : null
      if (scope.conversationId && !source) {
        return sendJson(response, 409, {
          error: '현재 AionUi 대화가 시작된 MindNProgress 카드를 확인할 수 없습니다.',
          code: 'AI_WORKSPACE_CHECKPOINT_ORIGIN_NOT_FOUND',
          conversationId: scope.conversationId,
        })
      }
      if (source && scope.cardId && scope.cardId !== source.cardId) {
        return sendJson(response, 409, {
          error: '현재 MCP 범위와 AionUi 대화의 시작 카드가 일치하지 않습니다.',
          code: 'AI_WORKSPACE_CHECKPOINT_ORIGIN_MISMATCH',
          conversationId: scope.conversationId,
          sourceCardId: source.cardId,
        })
      }
      const checkpointCardId = source?.cardId ?? scope.cardId
      if (!scope.mapId || !checkpointCardId) {
        return sendJson(response, 400, {
          error: '현재 AI 대화의 문서와 카드 범위가 필요합니다.',
          code: 'AI_WORKSPACE_CHECKPOINT_SCOPE_REQUIRED',
        })
      }
      const body = await readJsonBody(request)
      const paths = Array.isArray(body.paths) ? body.paths : []
      const confirmNoChanges = body.confirmNoChanges === true
      if (!body.jobId || paths.length > 2_000) {
        return sendJson(response, 400, {
          error: '현재 jobId와 체크포인트에 포함할 변경 경로가 필요합니다.',
          code: 'AI_WORKSPACE_CHECKPOINT_INPUT_INVALID',
        })
      }
      if (confirmNoChanges && (paths.length > 0 || body.commitMessage !== undefined)) {
        return sendJson(response, 400, {
          error: '무변경 확인에는 paths 또는 commitMessage를 전달할 수 없습니다.',
          code: 'AI_WORKSPACE_CHECKPOINT_INPUT_INVALID',
        })
      }
      if (!confirmNoChanges && paths.length === 0) {
        return sendJson(response, 400, {
          error: '변경 체크포인트에는 한 개 이상의 paths가 필요합니다. 변경이 없다면 무변경 확인 도구를 사용하세요.',
          code: 'AI_WORKSPACE_CHECKPOINT_INPUT_INVALID',
        })
      }
      if (!confirmNoChanges && (!body.commitMessage || typeof body.commitMessage !== 'object')) {
        return sendJson(response, 400, {
          error: '변경 체크포인트에는 실제 변경을 설명하는 commitMessage가 필요합니다.',
          code: 'AI_WORKSPACE_CHECKPOINT_MESSAGE_REQUIRED',
          details: [{ commitMessage: checkpointCommitMessageExample }],
        })
      }
      let map = null
      try {
        map = await readMap(scope.mapId)
      } catch (error) {
        console.warn('[AI workspace checkpoint context]', error)
      }
      const card = map?.nodes.find((node) => node.id === checkpointCardId)
      try {
        const result = await workspacePoolManager.checkpoint(leaseId, {
          jobId: String(body.jobId),
          mapId: scope.mapId,
          cardId: checkpointCardId,
          conversationId: scope.conversationId,
          paths,
          confirmNoChanges,
          commitMessage: body.commitMessage,
          mnpContext: {
            mapId: scope.mapId,
            cardId: checkpointCardId,
            documentTitle: map?.title,
            cardTitle: card?.data?.label,
          },
        })
        return sendJson(response, result.noChanges ? 200 : 201, result)
      } catch (error) {
        if (error instanceof WorkspacePoolUnavailableError) {
          return sendJson(response, 409, {
            error: error.message,
            code: error.reasonCode ?? error.code,
            details: error.details,
          })
        }
        throw error
      }
    }

    if (aiDelegationCompletionRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 위임 완료를 확인할 수 있습니다.' })
      const mapId = decodeURIComponent(aiDelegationCompletionRoute[1])
      const scope = integrationRequestScope(request)
      if (!isValidMapId(mapId)
        || (scope.mapId && scope.mapId !== mapId)
        || !validAiConversationId(scope.conversationId)) {
        return sendJson(response, 400, {
          error: '현재 AI 대화의 문서와 대화 범위가 필요합니다.',
          code: 'AI_DELEGATION_COMPLETION_SCOPE_REQUIRED',
        })
      }
      const source = delegationSourceForRequest(scope, mapId)
      if (!source) {
        return sendJson(response, 409, {
          error: '현재 AionUi 대화가 시작된 MindNProgress 카드를 확인할 수 없습니다.',
          code: 'AI_DELEGATION_COMPLETION_ORIGIN_NOT_FOUND',
          conversationId: scope.conversationId,
        })
      }
      if (scope.cardId && scope.cardId !== source.cardId) {
        return sendJson(response, 409, {
          error: '현재 MCP 범위와 AionUi 대화의 시작 카드가 일치하지 않습니다.',
          code: 'AI_DELEGATION_COMPLETION_ORIGIN_MISMATCH',
          conversationId: scope.conversationId,
          sourceCardId: source.cardId,
        })
      }
      const targetCardId = source.cardId
      const map = await readMap(mapId)
      if (!map || map.trashedAt || !map.nodes.some((node) => node.id === targetCardId)) {
        return sendJson(response, 404, { error: 'AI 위임 완료 대상 문서 또는 카드를 찾지 못했습니다.' })
      }
      const candidates = explicitCompletionAiDelegationsForConversation(aiDelegations.values(), {
        mapId,
        targetCardId,
        targetConversationId: scope.conversationId,
      })
      if (candidates.length === 0) {
        return sendJson(response, 200, {
          accepted: false,
          required: false,
          state: 'not-required',
          instruction: '현재 카드와 AI 대화에는 명시적 완료 신호가 필요한 위임이 없습니다. 중단 없이 진행된 위임은 최종 답변을 마치면 자동으로 상위 AI에 보고됩니다.',
        })
      }
      if (candidates.length > 1) {
        return sendJson(response, 409, {
          error: '명시적 완료를 기다리는 AI 위임이 여러 개라 자동으로 선택할 수 없습니다.',
          code: 'AI_DELEGATION_EXPLICIT_COMPLETION_AMBIGUOUS',
          delegations: candidates.map(delegationPublicView),
        })
      }
      const delegation = candidates[0]
      const dispatchPath = `/api/internal/external-conversation-dispatches/${encodeURIComponent(delegation.childOperationId)}`
      try {
        const dispatch = await fetchAionUiOn(delegationTargetMachineId(delegation), dispatchPath)
        const dispatchState = String(dispatch?.state ?? '').trim()
        if (dispatchState !== 'waiting_resume') {
          if (dispatchState === 'failed' || dispatchState === 'recovery_required') {
            const code = dispatchState === 'failed'
              ? 'AI_DELEGATION_CHILD_ALREADY_FAILED'
              : 'AI_DELEGATION_CHILD_RECOVERY_REQUIRED'
            return sendJson(response, 409, {
              error: dispatchState === 'failed'
                ? `현재 AI 위임은 이미 실패 상태라 완료 신호를 받을 수 없습니다. (${code})`
                : `현재 AI 위임은 복구가 필요한 상태라 완료 신호보다 위임 복구가 먼저 필요합니다. (${code})`,
              code,
              state: dispatchState,
              delegation: delegationPublicView(delegation),
            })
          }
          if (['starting', 'waiting_resource', 'running', 'completed'].includes(dispatchState)) {
            return sendJson(response, 200, {
              accepted: false,
              required: false,
              state: dispatchState,
              delegation: delegationPublicView(delegation),
              instruction: dispatchState === 'completed'
                ? '현재 위임은 이미 완료됐습니다. MindNProgress가 상위 AI 재개 상태를 동기화합니다.'
                : '현재 위임은 사용자 중지 후 재개를 기다리는 상태가 아니므로 별도 완료 신호가 필요하지 않습니다. 실제 작업의 최종 답변을 마치면 AionCore가 자동으로 완료를 확정하고 상위 AI에 보고합니다.',
            })
          }
          return sendJson(response, 409, {
            error: `AionCore가 알 수 없는 AI 위임 상태를 반환했습니다. (AI_DELEGATION_EXPLICIT_COMPLETION_STATE_UNKNOWN: ${dispatchState || 'empty'})`,
            code: 'AI_DELEGATION_EXPLICIT_COMPLETION_STATE_UNKNOWN',
            state: dispatchState || null,
            delegation: delegationPublicView(delegation),
          })
        }
        const confirmation = await fetchAionUiOn(
          delegationTargetMachineId(delegation),
          `${dispatchPath}/complete`,
          {
            method: 'POST',
            body: { conversationId: scope.conversationId },
          },
        )
        const requestedAt = new Date().toISOString()
        const updated = await updateAiDelegation(delegation.id, {
          explicitCompletionRequestedAt: requestedAt,
          explicitCompletionTurnId: confirmation.turnId ?? null,
          explicitCompletionRequestedBy: user.id,
        })
        return sendJson(response, 202, {
          accepted: confirmation.accepted === true,
          required: true,
          turnId: confirmation.turnId ?? null,
          delegation: delegationPublicView(updated),
          instruction: '현재 턴의 최종 답변을 마치면 AionCore가 위임 완료를 확정하고 상위 AI 재개 절차를 진행합니다.',
        })
      } catch (error) {
        const code = error?.code ?? 'AI_DELEGATION_EXPLICIT_COMPLETION_FAILED'
        const turnNotActive = code === 'EXTERNAL_DISPATCH_COMPLETION_TURN_NOT_ACTIVE'
        return sendJson(response, error?.status === 404 ? 404 : 409, {
          error: turnNotActive
            ? `현재 AI 대화에 진행 중인 턴이 없어 완료 신호를 연결할 수 없습니다. 실제 작업 턴의 최종 답변 전에 호출하세요. (${code})`
            : `AionCore가 현재 AI 위임의 명시적 완료 신호를 받지 못했습니다. (${code})`,
          code,
        })
      }
    }

    if (aiDelegationRecoveryRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 위임을 복구할 수 있습니다.' })
      const parentMapId = decodeURIComponent(aiDelegationRecoveryRoute[1])
      const delegationId = decodeURIComponent(aiDelegationRecoveryRoute[2])
      const requestScope = integrationRequestScope(request)
      const source = delegationSourceForRequest(requestScope, parentMapId)
      const humanAction = !hasValidIntegrationBearer(request) && Boolean(getSignedInUser(request))
      if (!isValidMapId(parentMapId) || !isValidAiDelegationId(delegationId) || (!source && !humanAction)) {
        return sendJson(response, 400, { error: '복구할 AI 위임의 문서, 대화 또는 위임 ID가 올바르지 않습니다.' })
      }

      let delegation = aiDelegations.get(delegationId)
      if (!delegation || (delegation.parentMapId ?? delegation.mapId) !== parentMapId) {
        return sendJson(response, 404, { error: '복구할 AI 위임을 찾을 수 없습니다.' })
      }
      const mapId = delegation.mapId
      if (!await aionCoreSupportsExplicitCompletionAfterInterruption(delegationTargetMachineId(delegation))) {
        return sendJson(response, 503, {
          error: '현재 실행 중인 AionCore가 중단 후 명시적 완료 신호를 지원하지 않습니다. AionCore를 최신 빌드로 재기동해 주세요.',
          code: 'AIONCORE_EXPLICIT_COMPLETION_UNAVAILABLE',
        })
      }
      if (!humanAction && delegation.parentCardId !== source.cardId) {
        return sendJson(response, 403, {
          error: '이 위임을 관리하는 상위 카드에서만 복구할 수 있습니다.',
          code: 'AI_DELEGATION_RECOVERY_ORIGIN_MISMATCH',
        })
      }
      const recoveryAvailability = aiDelegationRecoveryAvailability(delegation)
      const retryableParentWakeFailure = ['parent-wake-failed', 'failed', 'waiting-usage-limit', 'waiting-rate-limit', 'waiting-model-capacity'].includes(delegation.state)
        && recoveryAvailability?.recoveryAvailable === true
        && recoveryAvailability.recommendedAction === 'resume-existing'
      if (!['recovery-required', 'integration-recovery-required', 'waiting-child-resume'].includes(delegation.state)
        && !retryableParentWakeFailure && !delegation.pendingRecovery) {
        return sendJson(response, 409, {
          error: `현재 위임 상태(${delegation.state})는 명시적인 재시작 복구 대상이 아닙니다.`,
          code: 'AI_DELEGATION_RECOVERY_NOT_REQUIRED',
          delegation: delegationPublicView(delegation),
        })
      }

      const body = await readJsonBody(request)
      const instruction = String(body.instruction ?? '').trim()
      const sourceRevision = Number(body.sourceRevision)
      if (!instruction || instruction.length > 100_000
        || !Number.isInteger(sourceRevision) || sourceRevision < 1) {
        return sendJson(response, 400, { error: '복구 지시와 최신 문서 version이 필요합니다.' })
      }
      const missingDispatchLink = delegation.state === 'recovery-required' && !delegation.targetConversationId
        && delegation.strategy === 'new' && Boolean(delegation.workspaceLease && delegation.pendingSelection && delegation.childOperationId)
      await validateAiDelegationAction(request, delegation, body, true, { requireConversationLinks: !missingDispatchLink })
      if (delegation.pendingRecovery) {
        try {
          const updated = await settlePendingAiRecovery(delegation)
          return sendJson(response, 202, { delegation: delegationPublicView(updated), repeated: true, recovery: { operationId: updated.recoveryOperationId, attempt: updated.recoveryAttempt, reusedConversation: true, reusedWorkspace: Boolean(updated.workspaceLease) } })
        } catch {
          return sendJson(response, 409, { error: '이전 복구 요청의 전달 여부를 확인하지 못했습니다. 중복 실행을 막기 위해 새 요청을 만들지 않았습니다. 상태 다시 확인이 필요합니다.', code: 'AI_DELEGATION_RECOVERY_DISPATCH_UNCERTAIN' })
        }
      }
      const competing = activeAiDelegationsForConversation(aiDelegations.values(), { mapId, targetCardId: delegation.targetCardId, targetConversationId: delegation.targetConversationId, excludeId: delegation.id })
      if (competing.length) return sendJson(response, 409, { error: '같은 대화에서 다른 위임이 진행 중입니다.', code: 'AI_DELEGATION_ALREADY_ACTIVE' })

      let map = await readMap(mapId)
      let parentMap = parentMapId === mapId ? map : await readMap(parentMapId)
      const parentCard = parentMap?.nodes.find((node) => node.id === delegation.parentCardId)
      const targetCard = map?.nodes.find((node) => node.id === delegation.targetCardId)
      if (!map || map.trashedAt || !parentMap || parentMap.trashedAt || !parentCard || !targetCard) {
        return sendJson(response, 404, { error: '상위 카드 또는 위임 대상 카드를 찾을 수 없습니다.' })
      }
      if (delegation.groupId && await groupProjects.authorizeDelegation(parentMap, parentCard.id, map, targetCard.id) !== delegation.groupId) return sendJson(response, 409, { error: '그룹 소속 또는 총괄 문서가 변경되었습니다.' })
      if (parentMap.version !== sourceRevision) {
        return sendJson(response, 409, {
          error: `문서가 변경되었습니다. 최신 버전 ${parentMap.version}을 다시 확인해 주세요.`,
          currentVersion: parentMap.version,
        })
      }
      if (missingDispatchLink) {
        try {
          const restored = await restoreConfirmedAiDelegationDispatch(delegation, map, parentMap, user)
          delegation = restored.delegation
          map = restored.map
          if (parentMapId === mapId) parentMap = map
        } catch (error) {
          return sendJson(response, error.status ?? 409, { error: error.message, code: error.code ?? 'AI_DELEGATION_RECOVERY_UNCONFIRMED', details: error.details })
        }
      }
      const restoredTargetCard = map.nodes.find((node) => node.id === delegation.targetCardId)
      if (!isAiConversationLinked(restoredTargetCard.data, delegation.targetConversationId)) {
        return sendJson(response, 409, { error: '위임 대상 카드와 기존 AI 대화의 연결을 확인할 수 없습니다.' })
      }

      const linked = aiConversationLinksFromData(restoredTargetCard.data)
        .find((candidate) => candidate.conversationId === delegation.targetConversationId)
      let selection
      try {
        const conversation = await fetchAiConversationRuntime(delegation.targetConversationId)
        const runtime = normalizeAiConversationRuntime(delegation.targetConversationId, conversation)
        if (runtime.state !== 'idle') {
          return sendJson(response, 409, {
            error: `대상 대화가 ${runtime.state} 상태이므로 지금 복구할 수 없습니다.`,
            runtime,
          })
        }
        const recovered = aiConversationLinkFromAionUiConversation(conversation)
            selection = aiDelegationSelectionFromSource({
          ...recovered,
          ...linked,
          agent: linked?.agent ?? recovered?.agent,
          model: linked?.model ?? recovered?.model,
          mode: linked?.mode ?? recovered?.mode,
          thoughtLevel: linked?.thoughtLevel ?? recovered?.thoughtLevel,
          skills: linked?.skills?.length ? linked.skills : recovered?.skills,
          mcpServers: linked?.mcpServers?.length ? linked.mcpServers : recovered?.mcpServers,
          workspace: delegation.workspaceLease?.projectRoot ?? linked?.workspace ?? recovered?.workspace,
        })
      } catch (error) {
        return sendJson(response, 503, { error: `이어갈 AionUi 대화 상태를 확인하지 못했습니다: ${error?.message ?? String(error)}` })
      }
      if (!selection) return sendJson(response, 409, { error: '복구할 AI 대화의 실행 환경을 확인하지 못했습니다.' })

      let workspaceLease = delegation.recoveryWorkspaceLease ?? delegation.workspaceLease ?? null
      let reactivatedWorkspaceLease = false
      let replacedWorkspaceLease = Boolean(delegation.recoveryWorkspaceLease && delegation.recoveryWorkspaceLease.leaseId !== delegation.workspaceLease?.leaseId)
      if (workspaceLease?.leaseId) {
        try {
          const scope = { mapId, cardId: targetCard.id, conversationId: delegation.targetConversationId }
          if (retryableParentWakeFailure && delegation.workspaceResult?.status === 'failed-clean' && !delegation.recoveryWorkspaceLease) {
            const replacement = await workspacePoolManager.acquire({
              ...scope, cardLabel: targetCard.data.label, workspaceHint: workspaceLease.projectRoot,
              replacesLeaseId: workspaceLease.leaseId,
            })
            if (!replacement) throw new Error('복구할 작업공간 풀이 등록되어 있지 않습니다.')
            workspaceLease = await workspacePoolManager.reuseLease(replacement.leaseId, scope)
            replacedWorkspaceLease = true
          } else workspaceLease = await (retryableParentWakeFailure
            ? workspacePoolManager.reactivateQuarantinedLease(workspaceLease.leaseId, {
                mapId,
                cardId: targetCard.id,
                conversationId: delegation.targetConversationId,
                failureCategory: recoveryAvailability.failureCategory,
              })
            : workspacePoolManager.reuseLease(workspaceLease.leaseId, {
                mapId,
                cardId: targetCard.id,
                conversationId: delegation.targetConversationId,
              }))
          reactivatedWorkspaceLease = retryableParentWakeFailure && !replacedWorkspaceLease
          selection.workspace = workspaceLease.projectRoot
          await updateAiDelegation(delegation.id, { recoveryWorkspaceLease: workspaceLease })
        } catch (error) {
          return sendJson(response, 409, {
            error: `기존 작업공간 lease를 복구하지 못했습니다: ${error?.message ?? String(error)}`,
            code: error?.code ?? 'AI_DELEGATION_WORKSPACE_RECOVERY_FAILED',
          })
        }
      }

      const { token: attributionToken, attribution } = issueDelegatedAttribution({
        mapId,
        cardId: targetCard.id,
        conversationId: delegation.targetConversationId,
        selection,
        startedBy: delegation.startedBy ?? user.id,
        homeMachineId: delegationTargetMachineId(delegation),
      })
      try {
        await persistAiAttributions()
      } catch (error) {
        aiAttributions.delete(sessionTokenKey(attributionToken))
        if (reactivatedWorkspaceLease || replacedWorkspaceLease) {
          try {
            await finalizeDelegationWorkspace({ ...delegation, workspaceLease }, 'failed', delegation.childError ?? delegation.workspaceResult?.childError)
          } catch {
            // Preserve the attribution persistence error below.
          }
        }
        return sendJson(response, 503, {
          error: `AI 위임 복구 귀속을 저장하지 못했습니다: ${error?.message ?? String(error)}`,
          code: 'AI_DELEGATION_RECOVERY_ATTRIBUTION_FAILED',
        })
      }

      const recoveryAttempt = Number(delegation.recoveryAttempt ?? 0) + 1
      const integrationRecovery = delegation.state === 'integration-recovery-required'
      const operationId = boundedAionOperationId(
        delegation.id,
        `${integrationRecovery ? 'integrate-' : ''}recover-${recoveryAttempt}`,
      )
      const recoveryContext = { ...delegation, workspaceLease }
      const recoveryConversationDisplay = await resolveAiConversationDisplay(
        delegation.targetConversationId,
        delegationTargetMachineId(delegation),
      )
      const replacementNotice = replacedWorkspaceLease
        ? '이전 작업공간은 변경 없이 반납되어 MindNProgress가 복구용 작업공간을 새로 배정했습니다. 과거 대화에 남은 경로·브랜치·lease 대신 이번 전문의 할당된 작업공간과 .ai-session.json을 사용하세요.\n\n'
        : ''
      const requestedInstruction = replacementNotice + (integrationRecovery
        ? `${delegation.workspaceResult?.status === 'checkpoint-required'
            ? workspaceCheckpointInstruction(delegation, delegation.workspaceResult)
            : workspaceConflictInstruction(delegation, delegation.workspaceResult)}\n\n${delegationRecoveryInstruction(recoveryContext, instruction, recoveryAvailability, recoveryConversationDisplay.displayLabel)}`
        : delegationRecoveryInstruction(recoveryContext, instruction, recoveryAvailability, recoveryConversationDisplay.displayLabel))
      const delegatedInstruction = buildDelegatedInstruction({
        mapId,
        cardId: targetCard.id,
        editorId: delegation.startedBy ?? user.id,
        attributionToken,
        instruction: requestedInstruction,
        workspaceLease,
      })

      let dispatch
      await updateAiDelegation(delegation.id, {
        pendingRecovery: { operationId, attempt: recoveryAttempt, sourceState: delegation.state, integrationRecovery, workspaceLease, requestedAt: new Date().toISOString() },
        attemptHistory: aiDelegationAttemptHistory(delegation, '사용자가 승인 범위의 기존 작업 재개 요청'),
      })
      try {
        dispatch = await fetchAionUiOn(delegationTargetMachineId(delegation), '/api/internal/external-conversation-dispatches', {
          method: 'POST',
          timeoutMs: 30_000,
          body: {
            operationId,
            actorConversationId: delegation.parentConversationId,
            strategy: 'resume',
            explicitCompletionAfterInterruption: true,
            targetConversationId: delegation.targetConversationId,
            ...(workspaceLease ? { workspaceLease } : {}),
            instruction: delegatedInstruction,
          },
        })
      } catch (error) {
        for (let attempt = 0; attempt < 10 && !dispatch; attempt += 1) {
          if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, 500))
          try {
            dispatch = await fetchAionUiOn(delegationTargetMachineId(delegation), `/api/internal/external-conversation-dispatches/${encodeURIComponent(operationId)}`)
          } catch {
            // The recovery dispatch may have started even when its POST response was lost.
          }
        }
        if (!dispatch) {
          // 접수 여부가 불명확하면 대화 귀속과 lease를 보존한다. 토큰 삭제나 새 실행으로
          // 진행 중일 수 있는 작업을 손상시키지 않고, 저장된 operation의 조회만 허용한다.
          await updateAiDelegation(delegation.id, { recoveryDispatchError: error?.message ?? '복구 전달 확인 대기' })
          return sendJson(response, error?.status === 409 ? 409 : 503, {
            error: `AionUi에 복구 작업을 전달하지 못했습니다: ${error?.message ?? String(error)}`,
          })
        }
      }

      if (!aiDelegationWorkspaceLeaseMatches(workspaceLease, dispatch?.workspaceLease ?? null)
          || String(dispatch?.conversationId ?? '').trim() !== delegation.targetConversationId) {
        aiAttributions.delete(sessionTokenKey(attributionToken))
        await persistAiAttributions()
        try {
          if (workspaceLease?.leaseId) await workspacePoolManager.quarantine(
            workspaceLease.leaseId,
            'AionCore가 사용량 제한 복구에 사용한 대화 또는 작업공간 lease가 기존 위임과 일치하지 않습니다.',
          )
        } catch {
          // The response below remains the primary recovery failure.
        }
        return sendJson(response, 409, {
          error: 'AionCore가 사용량 제한 복구에 사용한 대화 또는 작업공간 lease가 기존 위임과 일치하지 않습니다.',
          code: 'AI_DELEGATION_RECOVERY_EXECUTION_MISMATCH',
        })
      }

      attribution.conversationId = delegation.targetConversationId
      const now = new Date().toISOString()
      const nextState = integrationRecovery
        ? integrationDelegationState(dispatch.state)
        : (dispatch.state === 'waiting_resource'
            ? 'waiting-resource'
            : dispatch.state === 'waiting_resume' ? 'waiting-child-resume' : 'starting')
      const updated = await updateAiDelegation(delegation.id, {
        state: nextState,
        pendingRecovery: null,
        recoveryWorkspaceLease: null,
        recoveryDispatchError: null,
        childOperationId: integrationRecovery ? delegation.childOperationId : operationId,
        integrationOperationId: integrationRecovery ? operationId : delegation.integrationOperationId,
        recoveryAttempt,
        recoveryOperationId: operationId,
        recoveryInstructionPreview: instruction.replace(/\s+/g, ' ').slice(0, 240),
        recoveryInstructionHash: createHash('sha256').update(instruction).digest('hex'),
        recoveryRequestedAt: now,
        recoveryRequiredAt: null,
        recoverySourceState: delegation.state,
        recoveryFailureCategory: retryableParentWakeFailure
          ? recoveryAvailability.failureCategory
          : delegation.recoveryFailureCategory,
        childError: integrationRecovery ? delegation.childError : null,
        integrationError: integrationRecovery ? null : delegation.integrationError,
        childTurnId: integrationRecovery ? delegation.childTurnId : (dispatch.turnId ?? null),
        integrationTurnId: integrationRecovery ? (dispatch.turnId ?? null) : delegation.integrationTurnId,
        ...(retryableParentWakeFailure ? {
          childStatus: null,
          parentError: null,
          parentDispatchState: null,
          parentTurnId: null,
          completedAt: null,
          childCompletedAt: null,
          workspaceResult: null,
          workspaceError: null,
        } : {}),
        ...(integrationRecovery ? {} : {
          childResultSnapshot: null,
          childResultHash: null,
          childResultTurnId: null,
          childResultCapturedAt: null,
          childResultCaptureAttemptedAt: null,
          reportReceipt: null, reportWaitReason: null,
          reportPayloadHash: null,
          reportResultAvailability: null,
          reportResultHash: null,
          reportResultTurnId: null,
          reportPreparedAt: null,
        }),
        workspaceLease,
      })
      return sendJson(response, 202, {
        delegation: delegationPublicView(updated),
        recovery: { operationId, attempt: recoveryAttempt, reusedConversation: true, reusedWorkspace: Boolean(workspaceLease) && !replacedWorkspaceLease, replacedWorkspace: replacedWorkspaceLease },
      })
    }

    if (groupDocumentInstructionsRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendGroupDocumentInstructionResponse(
        response, 403, 'GROUP_DOCUMENT_INSTRUCTION_EDITOR_REQUIRED', '편집자만 그룹 문서 지시 내역을 확인할 수 있습니다.',
      )
      const parentMapId = decodeURIComponent(groupDocumentInstructionsRoute[1])
      if (!isValidMapId(parentMapId)) return sendGroupDocumentInstructionResponse(
        response, 400, 'GROUP_DOCUMENT_INSTRUCTION_MAP_INVALID', '총괄 문서 ID가 올바르지 않습니다.',
      )
      const targetMapId = String(url.searchParams.get('targetMapId') ?? '').trim()
      const includeContent = url.searchParams.get('includeContent') === 'true'
      const instructions = [...groupDocumentInstructions.values()]
        .filter((instruction) => instruction.parentMapId === parentMapId
          && (!targetMapId || instruction.targetMapId === targetMapId))
        .sort((first, second) => String(second.createdAt).localeCompare(String(first.createdAt)))
        .map((instruction) => groupDocumentInstructionPublicView(instruction, { includeContent }))
      return sendGroupDocumentInstructionResponse(
        response, 200, 'GROUP_DOCUMENT_INSTRUCTION_LISTED', '그룹 문서 지시 내역을 조회했습니다.',
        { parentMapId, instructions },
      )
    }

    if (groupDocumentInstructionsRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendGroupDocumentInstructionResponse(
        response, 403, 'GROUP_DOCUMENT_INSTRUCTION_EDITOR_REQUIRED', '편집자만 그룹 문서 지시를 전달할 수 있습니다.',
      )
      const parentMapId = decodeURIComponent(groupDocumentInstructionsRoute[1])
      const requestScope = integrationRequestScope(request)
      const source = delegationSourceForRequest(requestScope, parentMapId)
      if (!isValidMapId(parentMapId) || !source) return sendGroupDocumentInstructionResponse(
        response, requestScope.conversationId ? 409 : 400,
        requestScope.conversationId ? 'GROUP_DOCUMENT_INSTRUCTION_ORIGIN_NOT_FOUND' : 'GROUP_DOCUMENT_INSTRUCTION_SCOPE_REQUIRED',
        requestScope.conversationId
          ? '현재 AionUi 대화가 시작된 그룹 총괄 루트 카드를 확인할 수 없습니다.'
          : '현재 그룹 총괄 루트 카드의 문서와 대화 범위가 필요합니다.',
      )
      const body = await readJsonBody(request)
      const id = String(body.idempotencyKey ?? '').trim()
      const targetMapId = String(body.targetMapId ?? '').trim()
      const strategy = String(body.strategy ?? '').trim()
      const requestedConversationId = String(body.conversationId ?? '').trim()
      const conversationAssessmentId = String(body.conversationAssessmentId ?? '').trim()
      const instructionType = String(body.instructionType ?? '').trim()
      const approvalScope = String(body.approvalScope ?? '').trim()
      const approvalEvidence = String(body.approvalEvidence ?? '').trim()
      const instructionText = String(body.instruction ?? '').trim()
      const decisionReason = String(body.decisionReason ?? '').trim()
      const sourceRevision = Number(body.sourceRevision)
      const targetRevision = Number(body.targetRevision)
      const groupProjectVersion = Number(body.groupProjectVersion)
      const requestedReplyTarget = normalizeGroupDocumentReplyTarget(body.replyTarget)
      if (!isValidGroupDocumentInstructionId(id)
        || !isValidMapId(targetMapId) || targetMapId === parentMapId
        || !['resume', 'new'].includes(strategy)
        || (strategy === 'resume' && !validAiConversationId(requestedConversationId))
        || (conversationAssessmentId && !/^[a-f0-9]{64}$/.test(conversationAssessmentId))
        || !GROUP_DOCUMENT_INSTRUCTION_TYPES.includes(instructionType)
        || !GROUP_DOCUMENT_INSTRUCTION_SCOPES.includes(approvalScope)
        || !approvalEvidence || approvalEvidence.length > 10_000
        || !instructionText || instructionText.length > 100_000
        || !decisionReason || decisionReason.length > 1_000
        || !Number.isInteger(sourceRevision) || sourceRevision < 1
        || !Number.isInteger(targetRevision) || targetRevision < 1
        || !Number.isInteger(groupProjectVersion) || groupProjectVersion < 1
        || !requestedReplyTarget) {
        return sendGroupDocumentInstructionResponse(
          response, 400, 'GROUP_DOCUMENT_INSTRUCTION_REQUEST_INVALID', '그룹 문서 지시 값이 올바르지 않습니다.',
        )
      }
      if (containsApprovalEvidenceDuplicate({ approvalEvidence, instruction: instructionText })) {
        return sendGroupDocumentInstructionResponse(
          response,
          400,
          'GROUP_DOCUMENT_INSTRUCTION_DUPLICATE_APPROVAL_EVIDENCE',
          '승인 근거 전문이 실행 지시에 중복되어 있습니다. approvalEvidence에는 승인 발언·출처·승인 범위만, instruction에는 실행 계획·제외 범위·완료 및 회신 조건만 작성해 다시 요청하세요.',
        )
      }
      return groupProjects.exclusive(async () => {
        const [parentMap, targetMap] = await Promise.all([readMap(parentMapId), readMap(targetMapId)])
        const parentCard = parentMap?.nodes.find((node) => node.id === source.cardId)
        const targetCard = documentRoot(targetMap)
        if (!parentMap || parentMap.trashedAt || !targetMap || targetMap.trashedAt || !parentCard || !targetCard) {
          return sendGroupDocumentInstructionResponse(
            response, 404, 'GROUP_DOCUMENT_INSTRUCTION_CARD_NOT_FOUND', '총괄 문서 또는 대상 문서의 원본 루트 카드를 찾을 수 없습니다.',
          )
        }
        const groupId = await groupProjects.authorizeDocumentInstruction(parentMap, parentCard.id, targetMap, targetCard.id)
        if (!groupId) return sendGroupDocumentInstructionResponse(
          response, 400, 'GROUP_DOCUMENT_INSTRUCTION_TARGET_OUTSIDE_GROUP',
          '그룹 문서 지시는 등록된 총괄 문서의 루트 AI가 같은 그룹의 다른 문서 원본 루트 AI에만 전달할 수 있습니다.',
        )
        const requestSignature = createGroupDocumentInstructionSignature({
          parentMapId,
          parentCardId: parentCard.id,
          targetMapId,
          targetRevision,
          groupProjectVersion,
          sourceRevision,
          strategy,
          conversationId: requestedConversationId,
          machineId: body.machineId,
          instructionType,
          approvalScope,
          approvalEvidence,
          instruction: instructionText,
          decisionReason,
          replyTarget: requestedReplyTarget,
          newConversation: body.newConversation,
        })
        const existing = groupDocumentInstructions.get(id)
        if (existing) {
          if (existing.requestSignature !== requestSignature) return sendGroupDocumentInstructionResponse(
            response, 409, 'GROUP_DOCUMENT_INSTRUCTION_IDEMPOTENCY_CONFLICT',
            '같은 idempotencyKey가 다른 그룹 문서 지시에 사용되었습니다.',
          )
          const reason = groupDocumentInstructionReason(existing)
          return sendGroupDocumentInstructionResponse(response, 200, 'GROUP_DOCUMENT_INSTRUCTION_REPEATED',
            `같은 지시 요청이 이미 접수되어 기존 상태를 반환했습니다. ${reason.message}`,
            { instruction: groupDocumentInstructionPublicView(existing, { includeContent: true }), repeated: true })
        }
        const groupContext = await groupProjects.context(groupId)
        if (parentMap.version !== sourceRevision || targetMap.version !== targetRevision
          || groupContext.project.version !== groupProjectVersion) {
          return sendGroupDocumentInstructionResponse(
            response, 409, 'GROUP_DOCUMENT_INSTRUCTION_REVISION_CONFLICT',
            '그룹 기준 또는 문서 버전이 변경되었습니다. 최신 그룹 문맥과 두 문서를 다시 확인한 뒤 지시 전문을 검토하세요.',
            { current: { sourceRevision: parentMap.version, targetRevision: targetMap.version, groupProjectVersion: groupContext.project.version } },
          )
        }
        const parentAttribution = delegationParentAttribution(request, source, parentCard, user)
        if (!parentAttribution?.conversationId
          || (source.conversationId && !isAiConversationLinked(parentCard.data, source.conversationId))) {
          return sendGroupDocumentInstructionResponse(
            response, 409, 'GROUP_DOCUMENT_INSTRUCTION_ORIGIN_LINK_MISSING',
            '현재 AI 대화와 그룹 총괄 루트 카드의 연결을 확인할 수 없습니다.',
          )
        }

        let targetHomeMachineId
        try {
          targetHomeMachineId = strategy === 'resume'
            ? conversationHomeMachineId(requestedConversationId)
            : resolveTargetMachineForUser(user, body.machineId).machineId
          if (strategy === 'resume') {
            const requestedMachineId = String(body.machineId ?? '').trim()
            const normalizedRequestedMachineId = normalizeMachineId(requestedMachineId)
            if (requestedMachineId && (!normalizedRequestedMachineId || normalizedRequestedMachineId !== targetHomeMachineId)) {
              return sendGroupDocumentInstructionResponse(
                response, 409, 'GROUP_DOCUMENT_INSTRUCTION_MACHINE_MISMATCH',
                '기존 문서 AI 대화는 생성된 머신에서만 이어갈 수 있습니다.',
              )
            }
            resolveTargetMachineForUser(user, targetHomeMachineId)
          }
        } catch (error) {
          if (error instanceof SubMachinePayloadError) return sendGroupDocumentInstructionResponse(
            response, 400, 'GROUP_DOCUMENT_INSTRUCTION_MACHINE_INVALID', error.message,
          )
          throw error
        }

        let selection
        if (strategy === 'resume') {
          const linked = aiConversationLinksFromData(targetCard.data)
            .find((candidate) => candidate.conversationId === requestedConversationId)
          if (!linked) return sendGroupDocumentInstructionResponse(
            response, 400, 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_INVALID',
            '이어갈 대화는 대상 문서의 원본 루트 카드에 연결된 conversationId여야 합니다.',
          )
          try {
            const conversation = await fetchAiConversationRuntime(requestedConversationId)
            const contextHealth = await inspectAiConversationContextHealth(requestedConversationId, conversation, targetHomeMachineId)
            if (!conversationAssessmentId) return sendGroupDocumentInstructionResponse(
              response, 409, 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_ASSESSMENT_REQUIRED',
              '기존 문서 AI 대화 이어가기는 최신 문맥 상태 평가가 필요합니다. 대상 루트 카드의 대화 후보를 다시 조회하세요.',
              { contextHealth },
            )
            if (conversationAssessmentId !== contextHealth.assessmentId) return sendGroupDocumentInstructionResponse(
              response, 409, 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_ASSESSMENT_STALE',
              '대상 문서 AI 대화가 후보 조회 이후 변경되었습니다. 최신 문맥 상태를 다시 확인하세요.',
              { contextHealth },
            )
            if (!contextHealth.resumeAllowed) return sendGroupDocumentInstructionResponse(
              response, 409, 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_CONTEXT_UNAVAILABLE',
              contextHealth.message,
              { contextHealth },
            )
            const recovered = aiConversationLinkFromAionUiConversation(conversation)
            selection = aiDelegationSelectionFromSource({
              ...recovered,
              ...linked,
              agent: linked.agent ?? recovered?.agent,
              model: linked.model ?? recovered?.model,
              mode: linked.mode ?? recovered?.mode,
              thoughtLevel: linked.thoughtLevel ?? recovered?.thoughtLevel,
              mcpServers: linked.mcpServers?.length ? linked.mcpServers : recovered?.mcpServers,
              skills: linked.skills?.length ? linked.skills : recovered?.skills,
              workspace: recovered?.workspace ?? linked.workspace,
            })
          } catch {
            return sendGroupDocumentInstructionResponse(
              response, 503, 'GROUP_DOCUMENT_INSTRUCTION_CONVERSATION_UNAVAILABLE',
              '이어갈 대상 문서 AI 대화의 실행 환경을 확인하지 못했습니다.',
            )
          }
        } else {
          try {
            selection = await delegationCreateSelection(targetCard, body.newConversation, parentAttribution, targetHomeMachineId)
          } catch (error) {
            return sendGroupDocumentInstructionResponse(
              response, 400, 'GROUP_DOCUMENT_INSTRUCTION_SELECTION_INVALID', error.message,
            )
          }
        }
        if (!selection) return sendGroupDocumentInstructionResponse(
          response, 409, 'GROUP_DOCUMENT_INSTRUCTION_SELECTION_UNRESOLVED',
          '대상 문서 루트 AI의 종류와 모델 정보를 확인하지 못했습니다.',
        )

        const now = new Date().toISOString()
        const replyTarget = {
          mode: requestedReplyTarget.mode,
          defaultConversationId: parentAttribution.conversationId,
          explicitConversationId: requestedReplyTarget.conversationId,
          effectiveConversationId: requestedReplyTarget.conversationId ?? parentAttribution.conversationId,
          evidence: requestedReplyTarget.evidence,
        }
        const storedInstruction = {
          id,
          requestSignature,
          groupId,
          groupProjectVersion,
          parentMapId,
          parentCardId: parentCard.id,
          parentCardLabel: parentCard.data?.label ?? parentCard.id,
          parentConversationId: parentAttribution.conversationId,
          parentHomeMachineId: conversationHomeMachineId(parentAttribution.conversationId, parentAttribution),
          targetMapId,
          targetCardId: targetCard.id,
          targetCardLabel: targetCard.data?.label ?? targetCard.id,
          targetRevision,
          sourceRevision,
          targetHomeMachineId,
          requestedConversationId: strategy === 'resume' ? requestedConversationId : null,
          conversationAssessmentId: strategy === 'resume' ? conversationAssessmentId : null,
          strategy,
          instructionType,
          approvalScope,
          instructionPreview: instructionText.replace(/\s+/g, ' ').slice(0, 240),
          instructionHash: createHash('sha256').update(instructionText).digest('hex'),
          approvalEvidencePreview: approvalEvidence.replace(/\s+/g, ' ').slice(0, 240),
          approvalEvidenceHash: createHash('sha256').update(approvalEvidence).digest('hex'),
          decisionReason,
          replyTarget,
          state: 'queued',
          reasonCode: 'GROUP_DOCUMENT_INSTRUCTION_QUEUED',
          message: '그룹 문서 지시 전문을 내구 대기열에 저장했으며 대상 문서 루트 AI에 전달을 시도합니다.',
          pendingInstruction: instructionText,
          pendingApprovalEvidence: approvalEvidence,
          pendingSelection: selection,
          startedBy: parentAttribution.startedBy ?? user.id,
          createdAt: now,
          updatedAt: now,
        }
        groupDocumentInstructions.set(id, storedInstruction)
        await persistGroupDocumentInstructions()
        broadcastEvent({ type: 'group-document-instruction-changed', instruction: groupDocumentInstructionPublicView(storedInstruction) })
        const delivered = await dispatchGroupDocumentInstruction(storedInstruction, user)
        const reason = groupDocumentInstructionReason(delivered)
        return sendGroupDocumentInstructionResponse(
          response, delivered.state === 'failed' || delivered.state === 'expired' ? 409 : 202,
          reason.reasonCode,
          reason.message,
          { instruction: groupDocumentInstructionPublicView(delivered, { includeContent: true }), repeated: false },
        )
      })
    }

    if (aiDelegationsRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 위임 목록을 확인할 수 있습니다.' })
      const mapId = decodeURIComponent(aiDelegationsRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '문서 ID가 올바르지 않습니다.' })
      const parentCardId = String(url.searchParams.get('parentCardId') ?? '').trim()
      const targetCardId = String(url.searchParams.get('targetCardId') ?? '').trim()
      const delegations = [...aiDelegations.values()]
        .filter((delegation) => (delegation.mapId === mapId || delegation.parentMapId === mapId)
          && (!parentCardId || delegation.parentCardId === parentCardId)
          && (!targetCardId || delegation.targetCardId === targetCardId))
        .sort((first, second) => String(second.createdAt).localeCompare(String(first.createdAt)))
        .map((delegation) => delegationPublicView(delegation, url.searchParams.get('includeResult') === 'true'))
      return sendJson(response, 200, { mapId, delegations })
    }

    if (aiDelegationsRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendAiDelegationResponse(
        response, 403, 'AI_DELEGATION_EDITOR_REQUIRED', '편집자만 AI 작업을 위임할 수 있습니다.',
      )
      const parentMapId = decodeURIComponent(aiDelegationsRoute[1])
      const requestScope = integrationRequestScope(request)
      const source = delegationSourceForRequest(requestScope, parentMapId)
      if (!isValidMapId(parentMapId) || !source) {
        if (requestScope.conversationId) {
          return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_ORIGIN_NOT_FOUND',
            '현재 AionUi 대화가 시작된 MindNProgress 카드를 확인할 수 없습니다. 카드의 AI 대화 연결 상태를 확인해 주세요.', {
            code: 'AI_DELEGATION_ORIGIN_NOT_FOUND',
            conversationId: requestScope.conversationId,
          })
        }
        return sendAiDelegationResponse(
          response, 400, 'AI_DELEGATION_SCOPE_REQUIRED', '현재 상위 카드의 문서와 카드 범위가 필요합니다.',
        )
      }
      const body = await readJsonBody(request)
      const mapId = body.targetMapId === undefined ? parentMapId : String(body.targetMapId)
      if (!isValidMapId(mapId)) return sendAiDelegationResponse(
        response, 400, 'AI_DELEGATION_TARGET_MAP_INVALID', '올바르지 않은 대상 문서 ID입니다.',
      )
      const crossDocument = mapId !== parentMapId
      if (crossDocument && !allowLegacyGroupDelegationCreation) return sendAiDelegationResponse(
        response,
        409,
        'AI_DELEGATION_CROSS_DOCUMENT_REPLACED',
        '새 교차 문서 AI 위임은 지원하지 않습니다. 그룹 총괄 문서 AI는 대상 문서 루트 AI에 그룹 문서 지시 전문을 전달해야 합니다.',
        {
          instructionTool: 'mindnprogress_send_group_document_instruction',
          targetMapId: mapId,
        },
      )
      const runDelegation = async () => {
      const id = String(body.idempotencyKey ?? '').trim()
      const targetCardId = String(body.targetCardId ?? '').trim()
      const strategy = String(body.strategy ?? '').trim()
      const conversationId = String(body.conversationId ?? '').trim()
      const conversationAssessmentId = String(body.conversationAssessmentId ?? '').trim()
      const instruction = String(body.instruction ?? '').trim()
      const decisionReason = String(body.decisionReason ?? '').trim()
      const sourceRevision = Number(body.sourceRevision)
      if (!isValidAiDelegationId(id)
        || !targetCardId || targetCardId.length > 120
        || !['resume', 'new'].includes(strategy)
        || (conversationAssessmentId && !/^[a-f0-9]{64}$/.test(conversationAssessmentId))
        || !instruction || instruction.length > 100_000
        || !decisionReason || decisionReason.length > 1_000
        || !Number.isInteger(sourceRevision) || sourceRevision < 1) {
        return sendAiDelegationResponse(
          response, 400, 'AI_DELEGATION_REQUEST_INVALID', 'AI 작업 위임 값이 올바르지 않습니다.',
        )
      }

      const parentHomeMachineId = conversationHomeMachineId(source.conversationId, source)
      let targetHomeMachineId
      try {
        if (strategy === 'resume') {
          targetHomeMachineId = conversationHomeMachineId(conversationId)
          const requestedResumeMachineId = String(body.machineId ?? '').trim()
          const normalizedResumeMachineId = normalizeMachineId(requestedResumeMachineId)
          if (requestedResumeMachineId && !normalizedResumeMachineId) {
            throw new SubMachinePayloadError('실행 머신 ID가 올바르지 않습니다.')
          }
          if (normalizedResumeMachineId && normalizedResumeMachineId !== targetHomeMachineId) {
            return sendAiDelegationResponse(response, 409, 'AI_CONVERSATION_MACHINE_MISMATCH',
              '기존 대화는 생성된 머신에서만 이어갈 수 있습니다.', {
              code: 'AI_CONVERSATION_MACHINE_MISMATCH',
              homeMachineId: targetHomeMachineId,
            })
          }
          resolveTargetMachineForUser(user, targetHomeMachineId)
        } else {
          targetHomeMachineId = resolveTargetMachineForUser(user, body.machineId).machineId
        }
      } catch (error) {
        if (error instanceof SubMachinePayloadError) return sendAiDelegationResponse(
          response, 400, 'AI_DELEGATION_MACHINE_INVALID', error.message,
        )
        throw error
      }
      if (!await aionCoreSupportsExplicitCompletionAfterInterruption(targetHomeMachineId)) {
        const message = `${machineLabel(targetHomeMachineId)}의 AionCore가 중단 후 명시적 완료 신호를 지원하지 않습니다. AionCore를 최신 빌드로 재기동해 주세요.`
        return sendAiDelegationResponse(response, 503, 'AIONCORE_EXPLICIT_COMPLETION_UNAVAILABLE', message, {
          code: 'AIONCORE_EXPLICIT_COMPLETION_UNAVAILABLE',
        })
      }

      const requestSignature = createAiDelegationRequestSignature({
        mapId,
        ...(crossDocument ? { parentMapId, targetRevision: body.targetRevision } : {}),
        parentCardId: source.cardId,
        targetCardId,
        strategy,
        conversationId,
        machineId: targetHomeMachineId === machineRegistry.mainMachineId ? null : targetHomeMachineId,
        instruction,
        decisionReason,
        sourceRevision,
        newConversation: body.newConversation,
      })
      const existingDelegation = aiDelegations.get(id)
      if (existingDelegation) {
        if (existingDelegation.requestSignature !== requestSignature) {
          return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_IDEMPOTENCY_CONFLICT',
            '같은 idempotencyKey가 다른 AI 위임 요청에 사용되었습니다.')
        }
        return sendAiDelegationResponse(response, 200, 'AI_DELEGATION_REPEATED',
          '같은 위임 요청이 이미 접수되어 기존 상태를 반환했습니다. 작업을 다시 실행하지 않았습니다.', {
            delegation: delegationPublicView(existingDelegation), repeated: true,
          })
      }

      const map = await readMap(mapId)
      const parentMap = crossDocument ? await readMap(parentMapId) : map
      const parentCard = parentMap?.nodes.find((node) => node.id === source.cardId)
      const targetCard = map?.nodes.find((node) => node.id === targetCardId)
      if (!map || map.trashedAt || !parentMap || parentMap.trashedAt || !parentCard || !targetCard) {
        return sendAiDelegationResponse(response, 404, 'AI_DELEGATION_CARD_NOT_FOUND',
          '상위 카드 또는 위임 대상 카드를 찾을 수 없습니다.')
      }
      const parentAttribution = delegationParentAttribution(request, source, parentCard, user)
      if (!parentAttribution?.conversationId
        || (source.conversationId && !isAiConversationLinked(parentCard.data, source.conversationId))) {
        return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_ORIGIN_LINK_MISSING',
          '현재 AI 대화와 대화가 시작된 카드의 연결을 확인할 수 없습니다.', {
          code: 'AI_DELEGATION_ORIGIN_LINK_MISSING',
          conversationId: source.conversationId,
          sourceCardId: source.cardId,
        })
      }
      const groupId = crossDocument ? await groupProjects.authorizeDelegation(parentMap, parentCard.id, map, targetCard.id) : null
      if (crossDocument ? !groupId : !isHierarchyDescendant(map, parentCard.id, targetCard.id)) {
        const message = crossDocument
            ? '문서 간 위임은 등록된 그룹 총괄 문서의 루트에서 같은 그룹에 속한 다른 문서의 원본 루트에만 할 수 있습니다.'
            : `위임 기준 카드 "${parentCard.data?.label ?? parentCard.id}"(${parentCard.id})의 계층상 하위 카드에만 AI 작업을 위임할 수 있습니다. 대상은 "${targetCard.data?.label ?? targetCard.id}"(${targetCard.id})입니다.`
        return sendAiDelegationResponse(response, 400, 'AI_DELEGATION_TARGET_OUTSIDE_SOURCE', message, {
          code: 'AI_DELEGATION_TARGET_OUTSIDE_SOURCE',
          sourceCardId: parentCard.id,
          targetCardId: targetCard.id,
        })
      }
      const groupScope = groupId ? { groupId, parentMapId, targetRevision: body.targetRevision, coordinationOnly: true, groupProjectVersion: (await groupProjects.context(groupId)).project.version } : {}
      if (crossDocument && !Number.isInteger(body.targetRevision)) return sendAiDelegationResponse(
        response, 400, 'AI_DELEGATION_TARGET_REVISION_REQUIRED', '대상 문서의 최신 targetRevision이 필요합니다.',
      )
      const targetVersionMismatch = crossDocument && body.targetRevision !== map.version
      if (parentMap.version !== sourceRevision || targetVersionMismatch) {
        let recoveredDispatch = null
        try {
          const candidate = await fetchAionUiOn(targetHomeMachineId, `/api/internal/external-conversation-dispatches/${encodeURIComponent(id)}`)
          const recoveredConversationId = String(candidate?.conversationId ?? '').trim()
          const linkedToTarget = /^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(recoveredConversationId)
            && isAiConversationLinked(targetCard.data, recoveredConversationId)
          if (linkedToTarget && (strategy === 'new' || recoveredConversationId === conversationId)) {
            recoveredDispatch = candidate
          }
        } catch {
          // AionCore에도 실행 기록이 없으면 일반적인 문서 버전 충돌로 처리합니다.
        }
        if (recoveredDispatch) {
          const now = new Date().toISOString()
          const targetConversationId = String(recoveredDispatch.conversationId).trim()
          let recoveredWorkspaceLease = recoveredDispatch.workspaceLease ?? null
          let workspaceRecoveryError = null
          if (recoveredWorkspaceLease?.leaseId) {
            try {
              recoveredWorkspaceLease = await workspacePoolManager.reuseLease(recoveredWorkspaceLease.leaseId, {
                mapId,
                cardId: targetCard.id,
                conversationId: targetConversationId,
              })
            } catch (error) {
              workspaceRecoveryError = error?.message ?? String(error)
              await workspacePoolManager.quarantine(
                recoveredWorkspaceLease.leaseId,
                `AionCore에 남은 위임의 실제 작업공간 lease를 복구하지 못했습니다: ${workspaceRecoveryError}`,
              )
            }
          }
          const delegation = {
            id,
            requestSignature,
            mapId,
            ...groupScope,
            parentCardId: parentCard.id,
            parentCardLabel: parentCard.data?.label ?? parentCard.id,
            targetCardId: targetCard.id,
            targetCardLabel: targetCard.data?.label ?? targetCard.id,
            parentConversationId: parentAttribution.conversationId,
            parentHomeMachineId,
            targetConversationId,
            targetHomeMachineId,
            childOperationId: id,
            strategy,
            decisionReason,
            sourceRevision,
            instructionPreview: instruction.replace(/\s+/g, ' ').slice(0, 240),
            instructionHash: createHash('sha256').update(instruction).digest('hex'),
            ...(workspaceRecoveryError
              ? {
                  state: 'recovery-required',
                  childStatus: 'interrupted-by-workspace-conflict',
                  childTurnId: recoveredDispatch.turnId ?? null,
                  childError: `AionCore에 남은 위임의 실제 작업공간 lease를 복구하지 못했습니다: ${workspaceRecoveryError}`,
                  recoveryRequiredAt: now,
                }
              : initialAiDelegationRuntime(recoveredDispatch, now)),
            workspaceLease: recoveredWorkspaceLease,
            workspaceError: workspaceRecoveryError,
            linkError: null,
            startedBy: parentAttribution.startedBy ?? user.id,
            createdAt: now,
            updatedAt: now,
            recoveredAt: now,
          }
          aiDelegations.set(id, delegation)
          await persistAiDelegations()
          const recoveredDelegation = ['completed', 'failed'].includes(delegation.childStatus)
            ? await captureAiDelegationChildResult(delegation)
            : delegation
          broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(recoveredDelegation) })
          return sendAiDelegationResponse(response, 202, 'AI_DELEGATION_RECOVERED',
            '이미 AionCore에 전달된 위임을 복구해 기존 실행 상태를 반환했습니다. 작업을 다시 실행하지 않았습니다.', {
            delegation: delegationPublicView(recoveredDelegation),
            mapVersion: map.version,
            repeated: true,
            recovered: true,
          })
        }
        const currentVersion = targetVersionMismatch ? map.version : parentMap.version
        return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_VERSION_CONFLICT',
          `문서가 변경되었습니다. 최신 버전 ${currentVersion}을 다시 확인해 주세요.`, { currentVersion })
      }
      let selection = null
      let targetConversationId = conversationId
      if (strategy === 'resume') {
        if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(targetConversationId)
          || !isAiConversationLinked(targetCard.data, targetConversationId)) {
          return sendAiDelegationResponse(response, 400, 'AI_DELEGATION_RESUME_CONVERSATION_INVALID',
            '이어갈 대화는 대상 카드에 연결된 conversationId여야 합니다.')
        }
        const resumesInterruptedDelegation = activeAiDelegationsForConversation(aiDelegations.values(), {
          mapId,
          targetCardId: targetCard.id,
          targetConversationId,
          excludeId: id,
        }).some((delegation) => delegation.state === 'waiting-child-resume')
        const linked = aiConversationLinksFromData(targetCard.data)
          .find((candidate) => candidate.conversationId === targetConversationId)
        try {
          const conversation = await fetchAiConversationRuntime(targetConversationId)
          const runtime = normalizeAiConversationRuntime(targetConversationId, conversation)
          if (runtime.state !== 'idle') {
            return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_CONVERSATION_BUSY',
              `대화가 ${runtime.state} 상태이므로 지금 이어갈 수 없습니다.`, { runtime })
          }
          if (!resumesInterruptedDelegation) {
            const contextHealth = await inspectAiConversationContextHealth(targetConversationId, conversation, targetHomeMachineId)
            if (!conversationAssessmentId) {
              return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_CONVERSATION_ASSESSMENT_REQUIRED',
                '일반적인 기존 대화 이어가기는 최신 문맥 상태 평가가 필요합니다. 대화 후보를 다시 조회해 assessmentId를 전달하세요.', {
                contextHealth,
              })
            }
            if (conversationAssessmentId !== contextHealth.assessmentId) {
              return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_CONVERSATION_ASSESSMENT_STALE',
                '대화 내용이나 문맥 상태가 후보 조회 이후 변경되었습니다. 최신 후보 평가를 다시 확인하세요.', {
                contextHealth,
              })
            }
            if (!contextHealth.resumeAllowed) {
              const reasonCode = contextHealth.state === 'saturated'
                ? 'AI_DELEGATION_CONVERSATION_CONTEXT_SATURATED'
                : 'AI_DELEGATION_CONVERSATION_CONTEXT_UNKNOWN'
              return sendAiDelegationResponse(response, 409, reasonCode, contextHealth.message, { contextHealth })
            }
          }
          const recovered = aiConversationLinkFromAionUiConversation(conversation)
          selection = aiDelegationSelectionFromSource({
            ...recovered,
            ...linked,
            agent: linked?.agent ?? recovered?.agent,
            model: linked?.model ?? recovered?.model,
            mode: linked?.mode ?? recovered?.mode,
            thoughtLevel: linked?.thoughtLevel ?? recovered?.thoughtLevel,
            skills: linked?.skills?.length ? linked.skills : recovered?.skills,
            mcpServers: linked?.mcpServers?.length ? linked.mcpServers : recovered?.mcpServers,
            workspace: recovered?.workspace ?? linked?.workspace,
          })
        } catch {
          return sendAiDelegationResponse(response, 503, 'AI_DELEGATION_CONVERSATION_RUNTIME_UNAVAILABLE',
            '이어갈 AionUi 대화 상태를 확인하지 못했습니다.')
        }
      } else {
        try {
          selection = await delegationCreateSelection(targetCard, body.newConversation, parentAttribution, targetHomeMachineId)
        } catch (error) {
          return sendAiDelegationResponse(response, 400, 'AI_DELEGATION_SELECTION_INVALID', error.message)
        }
      }
      if (!selection) return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_SELECTION_UNRESOLVED',
        '위임 대화의 AI 종류와 모델 정보를 확인하지 못했습니다.')

      let resumedDelegation = null
      if (crossDocument && strategy === 'new') {
        const activeTarget = [...aiDelegations.values()].find((item) => item.mapId === mapId && item.targetCardId === targetCard.id && !aiDelegationIsTerminal(item))
        if (activeTarget) return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_ALREADY_ACTIVE',
          '이 문서 루트에 아직 끝나지 않은 위임이 있습니다. 기존 위임을 확인하세요.', {
            code: 'AI_DELEGATION_ALREADY_ACTIVE', delegation: delegationPublicView(activeTarget),
          })
        const workStates = await aiConversationWorkStates(mapId, [targetCard.id])
        if (workStates?.cards.some((card) => !['idle', 'unlinked'].includes(card.state))) return sendAiDelegationResponse(
          response, 409, 'AI_DELEGATION_TARGET_BUSY',
          '문서 루트의 AI가 작업 중이거나 상태를 확인할 수 없습니다. 기존 대화를 먼저 확인하세요.',
        )
      }
      if (strategy === 'resume') {
        const activeDelegations = activeAiDelegationsForConversation(aiDelegations.values(), {
          mapId,
          targetCardId: targetCard.id,
          targetConversationId,
          excludeId: id,
        })
        let parentTurnId = null
        if (activeDelegations.some((delegation) => delegation.state === 'waking-parent')) {
          try {
            const parentConversation = await fetchAiConversationRuntime(parentAttribution.conversationId)
            const parentRuntime = normalizeAiConversationRuntime(parentAttribution.conversationId, parentConversation)
            if (parentRuntime.state === 'running') parentTurnId = parentRuntime.turnId
          } catch {
            // 상위 대화의 현재 turn을 확증하지 못하면 기존 위임을 그대로 활성 상태로 취급합니다.
          }
        }
        const blockingDelegations = activeDelegations.filter((delegation) => aiDelegationBlocksResume(delegation, {
          parentConversationId: parentAttribution.conversationId,
          parentTurnId,
        }))
        const nonResumable = blockingDelegations.find((delegation) => delegation.state !== 'waiting-child-resume')
        if (nonResumable) {
          return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_ALREADY_ACTIVE',
            '같은 카드와 AI 대화에 아직 끝나지 않은 위임이 있습니다.', {
            code: 'AI_DELEGATION_ALREADY_ACTIVE',
            delegation: delegationPublicView(nonResumable),
          })
        }
        if (blockingDelegations.length > 1) {
          return sendAiDelegationResponse(response, 409, 'AI_DELEGATION_RESUME_AMBIGUOUS',
            '같은 카드와 AI 대화에 재개 대기 중인 위임이 여러 개 있어 자동으로 선택할 수 없습니다.', {
            code: 'AI_DELEGATION_RESUME_AMBIGUOUS',
            delegations: blockingDelegations.map(delegationPublicView),
          })
        }
        resumedDelegation = blockingDelegations[0] ?? null
      }

      const workspacePoolResolution = crossDocument ? { known: true, workspaceHint: selection.workspace, expectsWorkspacePool: false } : await resolveAiDelegationWorkspacePool({
        selection,
        targetCard,
        parentAttribution,
        requested: body.newConversation,
      })
      if (!workspacePoolResolution.known && !resumedDelegation?.workspaceLease?.leaseId) {
        return sendAiDelegationResponse(response, 503, 'AI_DELEGATION_WORKSPACE_SCOPE_UNKNOWN',
          '현재 AI 대화의 작업공간이 등록된 pool 대상인지 확인하지 못했습니다. AionUi 대화의 workspace 정보를 확인해 주세요.', {
          code: 'AI_DELEGATION_WORKSPACE_SCOPE_UNKNOWN',
        })
      }
      const workspacePoolHint = workspacePoolResolution.workspaceHint
        ?? resumedDelegation?.workspaceLease?.projectRoot
        ?? null
      const expectsWorkspacePool = !crossDocument && Boolean(workspacePoolResolution.expectsWorkspacePool
        || resumedDelegation?.workspaceLease?.leaseId)
      if (expectsWorkspacePool && targetHomeMachineId !== machineRegistry.mainMachineId) {
        return sendAiDelegationResponse(response, 409, 'AI_WORKSPACE_REMOTE_ROUTING_NOT_SUPPORTED',
          '등록된 Unity 작업공간 풀 위임의 서브 머신 라우팅은 Tier 2에서 지원합니다. 이번 위임은 메인 머신을 선택해 주세요.', {
          code: 'AI_WORKSPACE_REMOTE_ROUTING_NOT_SUPPORTED',
          targetHomeMachineId,
        })
      }
      if (expectsWorkspacePool) {
        const now = new Date().toISOString()
        let integrationChanges = { dirty: false, paths: [] }
        try {
          integrationChanges = await workspacePoolManager.integrationTrackedChanges()
        } catch (error) {
          console.warn('[AI delegation integration workspace preflight]', error)
        }
        const waitingForIntegrationClean = integrationChanges.dirty === true
        const workspacePoolSnapshot = workspacePoolManager.publicSnapshot()
        const workerCounts = workspacePoolSnapshot.workspaces
          .filter((workspace) => workspace.role === 'worker')
          .reduce((counts, workspace) => {
            counts.total += 1
            counts[workspace.status] = (counts[workspace.status] ?? 0) + 1
            return counts
          }, { total: 0, idle: 0, leased: 0, quarantined: 0 })
        const workspaceWaitReasonCode = waitingForIntegrationClean
          ? integrationWorktreeDirtyReasonCode
          : 'AI_WORKSPACE_ALLOCATION_PENDING'
        const workspaceWaitMessage = waitingForIntegrationClean
          ? `${integrationWorktreeDirtyMessage} 변경을 정리하면 같은 위임이 자동으로 시작되므로 재위임하지 마세요.`
          : workerCounts.idle > 0
            ? `위임을 접수했고 작업공간을 비동기로 배정하고 있습니다. 조회 시점 기준 유휴 worker가 ${workerCounts.idle}개이므로 전체 작업공간 점유 상태가 아닙니다.`
            : '위임을 접수했고 작업공간 배정을 시작했습니다. 조회 시점 기준 유휴 worker는 0개지만 실제 용량 부족 여부는 배정 시도 후 확정됩니다. 같은 작업을 다시 위임하지 마세요.'
        const waitingDelegation = {
          id,
          requestSignature,
          mapId,
          parentCardId: parentCard.id,
          parentCardLabel: parentCard.data?.label ?? parentCard.id,
          targetCardId: targetCard.id,
          targetCardLabel: targetCard.data?.label ?? targetCard.id,
          parentConversationId: parentAttribution.conversationId,
          parentHomeMachineId,
          targetConversationId,
          targetHomeMachineId,
          childOperationId: id,
          strategy,
          conversationAssessmentId: strategy === 'resume' ? conversationAssessmentId : null,
          decisionReason,
          sourceRevision,
          instructionPreview: instruction.replace(/\s+/g, ' ').slice(0, 240),
          instructionHash: createHash('sha256').update(instruction).digest('hex'),
          state: waitingForIntegrationClean ? 'waiting-integration-clean' : 'waiting-workspace',
          resource: {
            kind: waitingForIntegrationClean ? 'integration_workspace' : 'workspace_pool',
            key: waitingForIntegrationClean
              ? workspacePoolSnapshot.integrationWorkspaceId
              : workspacePoolSnapshot.poolId,
            projectRoot: workspacePoolHint,
          },
          startedBy: parentAttribution.startedBy ?? user.id,
          pendingInstruction: instruction,
          pendingSelection: selection,
          pendingWorkspaceHint: workspacePoolHint,
          ...(resumedDelegation ? { resumesDelegationId: resumedDelegation.id } : {}),
          workspaceWaitStartedAt: now,
          workspaceWaitObservedAt: now,
          workspaceWaitWorkerCounts: workerCounts,
          workspaceWaitReasonCode,
          workspaceWaitMessage,
          ...(waitingForIntegrationClean ? {
            workspaceWaitError: integrationWorktreeDirtyMessage,
            integrationCleanTrackedChanges: integrationChanges.paths,
            integrationCleanWaitStartedAt: now,
          } : {}),
          createdAt: now,
          updatedAt: now,
        }
        aiDelegations.set(id, waitingDelegation)
        await persistAiDelegations()
        broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(waitingDelegation) })
        void runtimeLifecycle.track(() => pollAiDelegations()).catch((error) => console.warn('[AI delegation queue start]', error))
        return sendAiDelegationResponse(response, 202, workspaceWaitReasonCode, workspaceWaitMessage, {
          delegation: delegationPublicView(waitingDelegation),
          mapVersion: map.version,
          repeated: false,
          details: { observedAt: now, workerCounts },
        })
      }
      let workspaceLease = null
      if (expectsWorkspacePool
        && !await aionCoreSupportsWorkspaceLease(targetHomeMachineId)) {
        return sendAiDelegationResponse(response, 503, 'AIONCORE_WORKSPACE_LEASE_UNAVAILABLE',
          '현재 실행 중인 AionCore가 AI 작업공간 lease를 지원하지 않습니다. AionCore를 최신 빌드로 재기동해 주세요.', {
          code: 'AIONCORE_WORKSPACE_LEASE_UNAVAILABLE',
        })
      }
      try {
        workspaceLease = crossDocument ? null : resumedDelegation?.workspaceLease?.leaseId
          ? await workspacePoolManager.reuseLease(resumedDelegation.workspaceLease.leaseId, {
              mapId,
              cardId: targetCard.id,
              conversationId: targetConversationId,
            })
          : await workspacePoolManager.acquire({
              workspaceHint: workspacePoolHint ?? selection.workspace,
              mapId,
              cardId: targetCard.id,
              conversationId: strategy === 'resume' ? targetConversationId : '',
              cardLabel: targetCard.data?.label ?? targetCard.id,
            })
        if (workspaceLease) selection.workspace = workspaceLease.projectRoot
        if (expectsWorkspacePool && !workspaceLease) {
          throw aiDelegationDispatchError(
            '등록된 AI 작업공간 풀의 lease를 확보하지 못했습니다.',
            503,
            'AI_WORKSPACE_LEASE_REQUIRED',
          )
        }
      } catch (error) {
        if (error instanceof WorkspacePoolUnavailableError) {
          if (error.reasonCode === 'CAPACITY_EXHAUSTED' && expectsWorkspacePool) {
            const now = new Date().toISOString()
            const workspaceWaitMessage = '실제 배정 시도 결과 사용 가능한 worker가 없습니다. FIFO 대기열에 보존되었으므로 같은 작업을 다시 위임하지 마세요.'
            const waitingDelegation = {
              id,
              requestSignature,
              mapId,
              parentCardId: parentCard.id,
              parentCardLabel: parentCard.data?.label ?? parentCard.id,
              targetCardId: targetCard.id,
              targetCardLabel: targetCard.data?.label ?? targetCard.id,
              parentConversationId: parentAttribution.conversationId,
              parentHomeMachineId,
              targetConversationId,
              targetHomeMachineId,
              childOperationId: id,
              strategy,
              conversationAssessmentId: strategy === 'resume' ? conversationAssessmentId : null,
              decisionReason,
              sourceRevision,
              instructionPreview: instruction.replace(/\s+/g, ' ').slice(0, 240),
              instructionHash: createHash('sha256').update(instruction).digest('hex'),
              state: 'waiting-workspace',
              resource: {
                kind: 'workspace_pool',
                key: workspacePoolManager.publicSnapshot().poolId,
                projectRoot: workspacePoolHint,
              },
              startedBy: parentAttribution.startedBy ?? user.id,
              pendingInstruction: instruction,
              pendingSelection: selection,
              pendingWorkspaceHint: workspacePoolHint,
              ...(resumedDelegation ? { resumesDelegationId: resumedDelegation.id } : {}),
              workspaceWaitStartedAt: now,
              workspaceWaitReasonCode: 'CAPACITY_EXHAUSTED',
              workspaceWaitMessage,
              createdAt: now,
              updatedAt: now,
            }
            aiDelegations.set(id, waitingDelegation)
            await persistAiDelegations()
            broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(waitingDelegation) })
            return sendAiDelegationResponse(response, 202, 'CAPACITY_EXHAUSTED', workspaceWaitMessage, {
              delegation: delegationPublicView(waitingDelegation),
              mapVersion: map.version,
              repeated: false,
            })
          }
          return sendAiDelegationResponse(response, 409, error.reasonCode, error.message, {
            code: error.code,
            details: error.details,
          })
        }
        throw error
      }

      if (resumedDelegation) {
        resumedDelegation = await updateAiDelegation(resumedDelegation.id, {
          state: 'resuming',
          resumingByDelegationId: id,
          resumeRequestedAt: new Date().toISOString(),
        })
      }

      const { token: attributionToken, attribution } = issueDelegatedAttribution({
        mapId,
        cardId: targetCard.id,
        conversationId: strategy === 'resume' ? targetConversationId : null,
        selection,
        startedBy: parentAttribution.startedBy ?? user.id,
        homeMachineId: targetHomeMachineId,
      })
      await persistAiAttributions()
      const delegatedInstruction = buildDelegatedInstruction({
        mapId,
        cardId: targetCard.id,
        editorId: parentAttribution.startedBy ?? user.id,
        attributionToken,
        instruction: crossDocument ? `${DOCUMENT_COORDINATOR_INSTRUCTION}\n\n${instruction}` : instruction,
        workspaceLease,
      })

      const delegatedConversationTitle = strategy === 'new'
        ? formatAiConversationTitle(map.title, targetCard.data?.label ?? targetCard.id)
        : null
      let dispatch
      try {
        dispatch = await fetchAionUiOn(targetHomeMachineId, '/api/internal/external-conversation-dispatches', {
          method: 'POST',
          timeoutMs: 30_000,
          body: {
            operationId: id,
            actorConversationId: parentAttribution.conversationId,
            strategy,
            explicitCompletionAfterInterruption: true,
            ...(workspaceLease ? { workspaceLease } : {}),
            ...(strategy === 'resume' ? { targetConversationId } : {
              create: {
                agentId: selection.agent.id,
                title: delegatedConversationTitle,
                modelId: selection.model.id,
                mode: selection.mode?.id ?? null,
                thoughtLevel: selection.thoughtLevel?.id ?? null,
                enabledSkillIds: selection.enabledSkillIds,
                disabledBuiltinSkillIds: selection.disabledBuiltinSkillIds,
                mcpIds: selection.mcpIds,
                workspace: selection.workspace,
              },
            }),
            instruction: delegatedInstruction,
          },
        })
      } catch (error) {
        for (let attempt = 0; attempt < 10 && !dispatch; attempt += 1) {
          if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, 500))
          try {
            dispatch = await fetchAionUiOn(targetHomeMachineId, `/api/internal/external-conversation-dispatches/${encodeURIComponent(id)}`)
          } catch {
            // The POST may have reached AionCore even if its response was lost.
          }
        }
        if (!dispatch) {
          aiAttributions.delete(sessionTokenKey(attributionToken))
          const definitelyRejected = Number.isInteger(error?.status)
            && error.status >= 400 && error.status < 500 && error.status !== 409 && error.status !== 429
          await restoreAiDelegationResumeReservation(resumedDelegation, error)
          await Promise.all([
            persistAiAttributions(),
            workspaceLease && !resumedDelegation
              ? (definitelyRejected
                  ? workspacePoolManager.cancel(workspaceLease.leaseId, 'AionCore가 위임 요청을 실행 전에 거부했습니다.')
                  : workspacePoolManager.quarantine(workspaceLease.leaseId, 'AionUi 위임 요청의 실행 여부를 확인하지 못했습니다.'))
              : Promise.resolve(),
          ])
          const dispatchBusy = error?.status === 409
          const message = dispatchBusy
            ? '대상 AI 대화가 이미 작업 중이거나 같은 위임 요청이 준비 중입니다.'
            : 'AionUi에 AI 작업을 위임하지 못했습니다.'
          return sendAiDelegationResponse(
            response,
            dispatchBusy ? 409 : 503,
            dispatchBusy ? 'AI_DELEGATION_DISPATCH_BUSY' : 'AI_DELEGATION_DISPATCH_FAILED',
            message,
          )
        }
      }

      targetConversationId = String(dispatch.conversationId ?? '').trim()
      if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(targetConversationId)) {
        await restoreAiDelegationResumeReservation(resumedDelegation, 'AionUi가 유효한 위임 대화 ID를 반환하지 않았습니다.')
        if (workspaceLease && !resumedDelegation) {
          await workspacePoolManager.quarantine(workspaceLease.leaseId, 'AionUi가 유효한 위임 대화 ID를 반환하지 않았습니다.')
        }
        return sendAiDelegationResponse(response, 503, 'AI_DELEGATION_DISPATCH_CONVERSATION_INVALID',
          'AionUi가 위임 대화 ID를 반환하지 않았습니다.')
      }
      if (workspaceLease) {
        try {
          workspaceLease = await workspacePoolManager.bindConversation(workspaceLease.leaseId, targetConversationId)
            ?? workspaceLease
        } catch (error) {
          console.warn('[AI delegation workspace conversation binding]', JSON.stringify({
            mapId,
            cardId: targetCard.id,
            conversationId: targetConversationId,
            leaseId: workspaceLease.leaseId,
            error: error?.message ?? String(error),
          }))
        }
      }
      if (delegatedConversationTitle) {
        try {
          await protectAionUiConversationTitle(targetConversationId, delegatedConversationTitle, targetHomeMachineId)
        } catch (error) {
          console.warn('[AI delegation conversation title protection]', JSON.stringify({
            mapId,
            cardId: targetCard.id,
            conversationId: targetConversationId,
            error: error?.message ?? String(error),
          }))
        }
      }
      attribution.conversationId = targetConversationId
      rememberAiConversationOrigin({
        conversationId: targetConversationId,
        mapId,
        cardId: targetCard.id,
        startedBy: attribution.startedBy,
        linkedAt: new Date().toISOString(),
        homeMachineId: targetHomeMachineId,
      })
      aiConversationAttributions.set(conversationAttributionKey(mapId, targetCard.id), {
        mapId,
        cardId: targetCard.id,
        conversationId: targetConversationId,
        authorName: attribution.authorName,
        agentId: attribution.agentId,
        agentName: attribution.agentName,
        modelId: attribution.modelId,
        modelName: attribution.modelName,
        providerId: attribution.providerId,
        homeMachineId: targetHomeMachineId,
        startedBy: attribution.startedBy,
        linkedAt: new Date().toISOString(),
        refreshedAt: new Date().toISOString(),
      })
      await Promise.all([persistAiAttributions(), persistAiConversationAttributions(), persistAiConversationOrigins()])

      let updatedMap = map
      let linkError = null
      if (strategy === 'new') {
        const latestMap = await readMap(mapId)
        const latestTargetCard = latestMap?.nodes.find((node) => node.id === targetCard.id)
        if (!latestMap || latestMap.trashedAt || !latestTargetCard) {
          linkError = '새 대화는 생성됐지만 대상 카드가 변경되어 연결하지 못했습니다.'
        } else {
          const conversationLink = normalizeAiConversationLink({
            conversationId: targetConversationId,
            homeMachineId: targetHomeMachineId,
            agent: selection.agent,
            model: selection.model,
            providerId: selection.providerId,
            mode: selection.mode,
            thoughtLevel: selection.thoughtLevel,
            skills: selection.enabledSkillIds.map((skillId) => ({ id: skillId, label: skillId })),
            mcpServers: selection.mcpIds.map((mcpId) => ({ id: mcpId, label: mcpId })),
            workspace: selection.workspace,
            requestPreview: instruction,
            startedBy: { id: attribution.startedBy, label: users.find((candidate) => candidate.id === attribution.startedBy)?.name ?? attribution.startedBy },
            startedAt: new Date().toISOString(),
            linkedAt: new Date().toISOString(),
          })
          try {
            updatedMap = await saveMap(mapId, {
              nodes: latestMap.nodes.map((node) => node.id === targetCard.id ? {
                ...node,
                data: {
                  ...node.data,
                  aiConversationId: targetConversationId,
                  aiConversations: appendAiConversationLink(node.data, conversationLink),
                },
              } : node),
              edges: latestMap.edges,
            }, user, latestMap.title, latestMap.color, 'content')
            broadcastEvent({
              type: 'ai-conversation-linked', mapId, nodeId: targetCard.id,
              conversationId: targetConversationId, conversation: conversationLink,
              sourceClientId: null, updatedAt: updatedMap.updatedAt, updatedBy: publicUser(user),
            })
          } catch (error) {
            linkError = '새 대화는 생성됐지만 대상 카드의 대화 목록에 연결하지 못했습니다.'
            console.warn('[AI delegation conversation link]', error)
          }
        }
      }

      const now = new Date().toISOString()
      const delegation = {
        id,
        requestSignature,
        mapId,
        ...groupScope,
        parentCardId: parentCard.id,
        parentCardLabel: parentCard.data?.label ?? parentCard.id,
        targetCardId: targetCard.id,
        targetCardLabel: targetCard.data?.label ?? targetCard.id,
        parentConversationId: parentAttribution.conversationId,
        parentHomeMachineId,
        targetConversationId,
        targetHomeMachineId,
        childOperationId: id,
        strategy,
        conversationAssessmentId: strategy === 'resume' ? conversationAssessmentId : null,
        decisionReason,
        sourceRevision,
        instructionPreview: instruction.replace(/\s+/g, ' ').slice(0, 240),
        instructionHash: createHash('sha256').update(instruction).digest('hex'),
        ...initialAiDelegationRuntime(dispatch, now),
        linkError,
        startedBy: attribution.startedBy,
        workspaceLease,
        ...(resumedDelegation ? { resumesDelegationId: resumedDelegation.id } : {}),
        createdAt: now,
        updatedAt: now,
      }
      if (resumedDelegation) {
        const superseded = {
          ...resumedDelegation,
          state: 'superseded',
          supersededByDelegationId: id,
          supersededAt: now,
          resumingByDelegationId: null,
          updatedAt: now,
        }
        aiDelegations.set(superseded.id, superseded)
        broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(superseded) })
      }
      aiDelegations.set(id, delegation)
      await persistAiDelegations()
      broadcastEvent({ type: 'ai-delegation-changed', delegation: delegationPublicView(delegation) })
      const responseReasonCode = linkError
        ? 'AI_DELEGATION_ACCEPTED_WITH_LINK_WARNING'
        : 'AI_DELEGATION_ACCEPTED'
      const responseMessage = linkError
        ? `${linkError} 위임 실행은 시작됐으며 카드 연결 상태를 확인해 주세요.`
        : 'AI 작업 위임을 접수했고 대상 대화에서 실행을 시작했습니다.'
      return sendAiDelegationResponse(response, 202, responseReasonCode, responseMessage, {
        delegation: delegationPublicView(delegation),
        mapVersion: updatedMap.version,
        repeated: false,
      })
      }
      return await (crossDocument ? groupProjects.exclusive(runDelegation) : runDelegation())
    }

    const cardAiConversationOpenRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/cards\/([^/]+)\/ai-conversations\/([^/]+)\/open-url$/)
    if (cardAiConversationOpenRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화를 열 수 있습니다.' })
      const mapId = decodeURIComponent(cardAiConversationOpenRoute[1])
      const cardId = decodeURIComponent(cardAiConversationOpenRoute[2])
      const conversationId = decodeURIComponent(cardAiConversationOpenRoute[3])
      if (!isValidMapId(mapId)
        || !cardId || cardId.length > 120
        || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(conversationId)) {
        return sendJson(response, 400, { error: '문서, 카드 또는 대화 ID가 올바르지 않습니다.' })
      }
      const map = await readMap(mapId)
      const card = map?.nodes.find((node) => node.id === cardId)
      if (!map || map.trashedAt || !card || !isAiConversationLinked(card.data, conversationId)) {
        return sendJson(response, 404, { error: '카드에 연결된 AI 대화를 찾을 수 없습니다.' })
      }
      const linkedConversation = aiConversationLinksFromData(card.data)
        .find((link) => link.conversationId === conversationId)
      const homeMachineId = conversationHomeMachineId(conversationId, linkedConversation)
      if (!machineAccessibleByUser(user, homeMachineId)) {
        return sendJson(response, 403, { error: '이 대화가 저장된 서브 머신을 사용할 권한이 없습니다.' })
      }
      try {
        return sendJson(response, 200, {
          conversationId,
          homeMachineId,
          homeMachineLabel: machineLabel(homeMachineId),
          homeMachineRole: homeMachineId === machineRegistry.mainMachineId ? 'main' : 'sub',
          openUrl: createAionUiConversationWebUrl(aionUiWebBaseUrlForMachine(homeMachineId), conversationId),
        })
      } catch (error) {
        if (error instanceof SubMachinePayloadError) {
          return sendJson(response, 503, { error: error.message })
        }
        console.error('[AionUi conversation open URL]', error)
        return sendJson(response, 503, { error: 'AionUi 대화 주소를 만들지 못했습니다.' })
      }
    }

    const cardAiConversationItemRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/cards\/([^/]+)\/ai-conversations\/([^/]+)$/)
    if (cardAiConversationItemRoute && request.method === 'DELETE') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화 연결을 삭제할 수 있습니다.' })
      const mapId = decodeURIComponent(cardAiConversationItemRoute[1])
      const cardId = decodeURIComponent(cardAiConversationItemRoute[2])
      const conversationId = decodeURIComponent(cardAiConversationItemRoute[3])
      if (!isValidMapId(mapId)
        || !cardId || cardId.length > 120
        || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(conversationId)) {
        return sendJson(response, 400, { error: '문서, 카드 또는 대화 ID가 올바르지 않습니다.' })
      }
      const map = await readMap(mapId)
      const card = map?.nodes.find((node) => node.id === cardId)
      if (!map || map.trashedAt || !card) return sendJson(response, 404, { error: '카드를 찾을 수 없습니다.' })
      if (!isAiConversationLinked(card.data, conversationId)) {
        return sendJson(response, 404, { error: '카드에 연결된 AI 대화를 찾을 수 없습니다.' })
      }

      const remainingLinks = removeAiConversationLink(card.data, conversationId)
      const latestConversationId = remainingLinks.at(-1)?.conversationId ?? null
      const nextData = { ...card.data }
      if (remainingLinks.length > 0) nextData.aiConversations = remainingLinks
      else delete nextData.aiConversations
      if (latestConversationId) nextData.aiConversationId = latestConversationId
      else delete nextData.aiConversationId
      const updatedMap = await saveMap(mapId, {
        nodes: map.nodes.map((node) => node.id === cardId ? { ...node, data: nextData } : node),
        edges: map.edges,
      }, user, map.title, map.color, 'content')

      const attributionKey = conversationAttributionKey(mapId, cardId)
      if (aiConversationAttributions.get(attributionKey)?.conversationId === conversationId) {
        aiConversationAttributions.delete(attributionKey)
      }
      for (const [tokenHash, attribution] of aiAttributions.entries()) {
        if (attribution.mapId === mapId && attribution.cardId === cardId && attribution.conversationId === conversationId) {
          aiAttributions.delete(tokenHash)
        }
      }
      const origin = aiConversationOrigins.get(conversationId)
      if (origin?.mapId === mapId && origin.cardId === cardId) aiConversationOrigins.delete(conversationId)
      await Promise.all([persistAiAttributions(), persistAiConversationAttributions(), persistAiConversationOrigins()])
      broadcastMapChange(request, mapId, 'content', user)
      return sendJson(response, 200, {
        map: updatedMap,
        card: updatedMap.nodes.find((node) => node.id === cardId),
        removedConversationId: conversationId,
        latestConversationId,
      })
    }

    const cardAiConversationsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/cards\/([^/]+)\/ai-conversations$/)
    if (cardAiConversationsRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화 목록을 확인할 수 있습니다.' })
      const mapId = decodeURIComponent(cardAiConversationsRoute[1])
      const cardId = decodeURIComponent(cardAiConversationsRoute[2])
      if (!isValidMapId(mapId) || !cardId || cardId.length > 120) {
        return sendJson(response, 400, { error: '문서와 카드 ID가 올바르지 않습니다.' })
      }
      const map = await readMap(mapId)
      const card = map?.nodes.find((node) => node.id === cardId)
      if (!map || map.trashedAt || !card) return sendJson(response, 404, { error: '카드를 찾을 수 없습니다.' })
      const currentAttribution = aiConversationAttributions.get(conversationAttributionKey(mapId, cardId))
      const links = aiConversationLinksFromData(card.data).map((link) => {
        const homeMachineId = conversationHomeMachineId(link.conversationId, link)
        if (link.conversationId !== currentAttribution?.conversationId) {
          return normalizeAiConversationLink({ ...link, homeMachineId })
        }
        return normalizeAiConversationLink({
          ...link,
          homeMachineId,
          agent: link.agent ?? (currentAttribution.agentId ? {
            id: currentAttribution.agentId,
            label: currentAttribution.agentName ?? currentAttribution.agentId,
          } : null),
          model: link.model ?? (currentAttribution.modelId ? {
            id: currentAttribution.modelId,
            label: currentAttribution.modelName ?? currentAttribution.modelId,
          } : null),
          providerId: link.providerId ?? currentAttribution.providerId,
          startedBy: link.startedBy ?? (currentAttribution.startedBy ? {
            id: currentAttribution.startedBy,
            label: users.find((candidate) => candidate.id === currentAttribution.startedBy)?.name ?? currentAttribution.startedBy,
          } : null),
          startedAt: link.startedAt ?? currentAttribution.linkedAt,
          linkedAt: link.linkedAt ?? currentAttribution.linkedAt,
        })
      }).filter(Boolean)
      const observedAt = new Date().toISOString()
      const conversations = await Promise.all(links.map(async (link) => {
        if (!machineAccessibleByUser(user, link.homeMachineId)) {
          return {
            ...link,
            homeMachineLabel: machineLabel(link.homeMachineId),
            homeMachineRole: link.homeMachineId === machineRegistry.mainMachineId ? 'main' : 'sub',
            accessible: false,
            available: false,
            name: '',
            modifiedAt: null,
            runtime: normalizeAiConversationRuntime(link.conversationId, null, observedAt),
            contextHealth: assessAiConversationContextHealth({
              conversationId: link.conversationId,
              runtimeState: 'unknown',
              messageCount: null,
              messageCountExact: false,
              ...aiConversationDelegationContextStats(link.conversationId),
            }, observedAt),
          }
        }
        try {
          const conversation = await fetchAiConversationRuntime(link.conversationId)
          if (!conversation || String(conversation.id) !== link.conversationId) throw new Error('AIONUI_CONVERSATION_NOT_FOUND')
          const recoveredLink = aiConversationLinkFromAionUiConversation(conversation)
          const enrichedLink = normalizeAiConversationLink({
            ...link,
            agent: link.agent ?? recoveredLink?.agent,
            model: link.model ?? recoveredLink?.model,
            providerId: link.providerId ?? recoveredLink?.providerId,
            mode: link.mode ?? recoveredLink?.mode,
            thoughtLevel: link.thoughtLevel ?? recoveredLink?.thoughtLevel,
            skills: link.skills.length > 0 ? link.skills : recoveredLink?.skills,
            mcpServers: link.mcpServers.length > 0 ? link.mcpServers : recoveredLink?.mcpServers,
            workspace: link.workspace ?? recoveredLink?.workspace,
            startedAt: link.startedAt ?? recoveredLink?.startedAt,
          }) ?? link
          const contextHealth = await inspectAiConversationContextHealth(link.conversationId, conversation, enrichedLink.homeMachineId)
          return {
            ...enrichedLink,
            homeMachineLabel: machineLabel(enrichedLink.homeMachineId),
            homeMachineRole: enrichedLink.homeMachineId === machineRegistry.mainMachineId ? 'main' : 'sub',
            accessible: true,
            available: true,
            name: String(conversation.name ?? ''),
            startedAt: enrichedLink.startedAt ?? normalizedIsoDate(conversation.created_at),
            modifiedAt: normalizedIsoDate(conversation.modified_at, enrichedLink.linkedAt ?? null),
            runtime: normalizeAiConversationRuntime(link.conversationId, conversation, observedAt),
            contextHealth,
          }
        } catch {
          return {
            ...link,
            homeMachineLabel: machineLabel(link.homeMachineId),
            homeMachineRole: link.homeMachineId === machineRegistry.mainMachineId ? 'main' : 'sub',
            accessible: true,
            available: false,
            name: '',
            modifiedAt: null,
            runtime: normalizeAiConversationRuntime(link.conversationId, null, observedAt),
            contextHealth: assessAiConversationContextHealth({
              conversationId: link.conversationId,
              runtimeState: 'unknown',
              messageCount: null,
              messageCountExact: false,
              ...aiConversationDelegationContextStats(link.conversationId),
            }, observedAt),
          }
        }
      }))
      conversations.sort((first, second) => String(second.startedAt ?? second.linkedAt ?? '')
        .localeCompare(String(first.startedAt ?? first.linkedAt ?? '')))
      return sendJson(response, 200, {
        mapId,
        cardId,
        latestConversationId: card.data?.aiConversationId ?? null,
        conversations,
      })
    }

    if (aionUiConversationTranscriptRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화 전체 내용을 조회할 수 있습니다.' })
      const conversationId = decodeURIComponent(aionUiConversationTranscriptRoute[1])
      if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(conversationId)) {
        return sendJson(response, 400, { error: '올바르지 않은 AionUi 대화 ID입니다.' })
      }
      const scope = integrationRequestScope(request)
      if (!isValidMapId(scope.mapId) || !scope.cardId) {
        return sendJson(response, 400, { error: '대화가 연결된 문서와 카드 범위가 필요합니다.' })
      }
      const map = await readMap(scope.mapId)
      const card = map?.nodes.find((node) => node.id === scope.cardId)
      if (!map || map.trashedAt || !card || !isAiConversationLinked(card.data, conversationId)) {
        return sendJson(response, 404, { error: '카드에 연결된 AI 대화를 찾을 수 없습니다.' })
      }
      const linkedConversation = aiConversationLinksFromData(card.data)
        .find((link) => link.conversationId === conversationId)
      const homeMachineId = conversationHomeMachineId(conversationId, linkedConversation)
      if (!machineAccessibleByUser(user, homeMachineId)) {
        return sendJson(response, 403, { error: '이 대화가 저장된 서브 머신을 사용할 권한이 없습니다.' })
      }
      const requestedLimit = Number(url.searchParams.get('limit') ?? 50)
      const before = String(url.searchParams.get('before') ?? '').trim()
      if (!Number.isInteger(requestedLimit) || requestedLimit < 1 || requestedLimit > 200 || before.length > 1_000) {
        return sendJson(response, 400, { error: '대화 전문 페이지의 limit 또는 before 값이 올바르지 않습니다.' })
      }
      try {
        const messageQuery = new URLSearchParams({ limit: String(requestedLimit), content_mode: 'full' })
        if (before) messageQuery.set('before', before)
        const [conversation, messagePage] = await Promise.all([
          fetchAionUiOn(homeMachineId, `/api/conversations/${encodeURIComponent(conversationId)}`),
          fetchAionUiOn(homeMachineId, `/api/conversations/${encodeURIComponent(conversationId)}/messages?${messageQuery}`, { timeoutMs: 30_000 }),
        ])
        if (!conversation || conversation.id !== conversationId) {
          return sendJson(response, 404, { error: 'AionUi 대화를 찾을 수 없습니다.' })
        }
        const messages = Array.isArray(messagePage?.items) ? messagePage.items : []
        const exportedAt = new Date().toISOString()
        const exported = buildAionUiConversationTranscript(conversation, messages, exportedAt)
        return sendJson(response, 200, {
          conversation: {
            id: conversation.id,
            name: String(conversation.name ?? ''),
            type: String(conversation.type ?? ''),
            createdAt: conversation.created_at ?? null,
            modifiedAt: conversation.modified_at ?? null,
          },
          card: { mapId: map.id, cardId: card.id, label: card.data?.label ?? card.id },
          homeMachineId,
          homeMachineLabel: machineLabel(homeMachineId),
          exportedAt,
          messageCount: messages.length,
          exportedMessageCount: exported.exportedMessageCount,
          truncated: messagePage?.has_more_before === true || messagePage?.has_more_after === true,
          page: {
            limit: requestedLimit,
            before: before || null,
            oldestCursor: messagePage?.oldest_cursor ?? null,
            newestCursor: messagePage?.newest_cursor ?? null,
            hasMoreBefore: messagePage?.has_more_before === true,
            hasMoreAfter: messagePage?.has_more_after === true,
            nextBefore: messagePage?.has_more_before === true ? messagePage?.oldest_cursor ?? null : null,
          },
          coverage: {
            complete: messagePage?.has_more_before !== true && messagePage?.has_more_after !== true,
            message: messagePage?.has_more_before === true
              ? '더 오래된 메시지가 있습니다. page.nextBefore를 before로 전달해 이어서 조회하세요.'
              : messagePage?.has_more_after === true
                ? '이 페이지보다 최신 메시지가 있어 현재 응답은 전체 전문이 아닙니다.'
                : '이 페이지에 대화의 전체 메시지 범위가 포함되었습니다.',
          },
          transcript: exported.transcript,
        })
      } catch (error) {
        console.error('[AionUi conversation transcript]', error)
        return sendJson(response, 503, { error: 'AionUi 대화 전체 내용을 가져오지 못했습니다.' })
      }
    }

    const aionUiConversationAttributionRoute = url.pathname.match(/^\/api\/integrations\/aionui\/conversations\/([^/]+)\/attribution$/)
    if (aionUiConversationAttributionRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화 정보를 갱신할 수 있습니다.' })
      const conversationId = decodeURIComponent(aionUiConversationAttributionRoute[1])
      if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(conversationId)) {
        return sendJson(response, 400, { error: '올바르지 않은 AionUi 대화 ID입니다.' })
      }
      const body = await readJsonBody(request)
      const mapId = String(body.mapId ?? '').trim().slice(0, 120)
      const cardId = String(body.cardId ?? '').trim().slice(0, 120)
      if (!isValidMapId(mapId) || !cardId) return sendJson(response, 400, { error: '문서와 카드 ID가 필요합니다.' })
      const map = await readMap(mapId)
      const card = map?.nodes.find((node) => node.id === cardId)
      if (!map || map.trashedAt || !card || !isAiConversationLinked(card.data, conversationId)) {
        return sendJson(response, 404, { error: '연결된 AI 대화의 문서 또는 카드를 찾을 수 없습니다.' })
      }
      const linkedConversation = aiConversationLinksFromData(card.data)
        .find((link) => link.conversationId === conversationId)
      if (!machineAccessibleByUser(user, conversationHomeMachineId(conversationId, linkedConversation))) {
        return sendJson(response, 403, { error: '이 대화가 저장된 서브 머신을 사용할 권한이 없습니다.' })
      }
      try {
        const result = await refreshConversationAttribution(mapId, cardId, conversationId, user.id, linkedConversation, {
          makeCurrent: card.data?.aiConversationId === conversationId,
        })
        return sendJson(response, 200, result)
      } catch (error) {
        console.error('[AionUi conversation attribution refresh]', error)
        return sendJson(response, 503, { error: 'AionUi에서 AI 종류와 모델을 확인하지 못했습니다.' })
      }
    }

    // 분산 작업은 사용자가 계정 설정에서 켤 때만 동작한다. 끈 상태에서는 메인 머신만 대상으로 남는다.
    if (url.pathname === '/api/account/distributed-work') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 분산 작업 설정을 사용할 수 있습니다.' })

      if (request.method === 'GET') {
        return sendJson(response, 200, {
          settings: userDistributedWork(user),
          targets: distributedWorkTargets(machineRegistry, distributedWorkSettings.get(user.id), machineViewer(user)),
        })
      }

      if (request.method === 'PUT') {
        const body = await readJsonBody(request)
        if (typeof body?.enabled !== 'boolean') {
          return sendJson(response, 400, { error: '분산 작업 사용 여부가 올바르지 않습니다.' })
        }
        const requested = normalizeDistributedWorkSettings(body)
        if (requested.enabled && requested.defaultMachineId) {
          const machine = findMachine(machineRegistry, requested.defaultMachineId)
          if (!machine || !machineTargetableBy(machineRegistry, machine, machineViewer(user))) {
            return sendJson(response, 400, { error: '선택한 기본 머신을 사용할 수 없습니다.' })
          }
        }
        distributedWorkSettings.set(user.id, requested)
        await persistDistributedWorkSettings()
        return sendJson(response, 200, {
          settings: userDistributedWork(user),
          targets: distributedWorkTargets(machineRegistry, requested, machineViewer(user)),
        })
      }

      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    // AionUi는 짧게 살아 있는 일회용 코드로 영구 Runner 토큰을 한 번만 교환한다.
    // 이 요청 자체에는 브라우저 세션이 없지만, 256-bit 코드를 가진 클라이언트만 성공한다.
    if (request.method === 'POST' && url.pathname === '/api/machines/runner/pairing/exchange') {
      const body = await readJsonBody(request)
      let pairing
      try {
        pairing = machinePairingStore.consume(body?.pairingCode)
      } catch (error) {
        if (error instanceof MachinePairingError) {
          return sendJson(response, 401, { error: error.message, reasonCode: error.reasonCode })
        }
        throw error
      }

      const machine = findMachine(machineRegistry, pairing.machineId)
      const requestingUser = users.find((candidate) => candidate.id === pairing.requestedByUserId)
      if (!machine
        || machine.machineId === machineRegistry.mainMachineId
        || !machine.enabled
        || !requestingUser
        || !canEdit(requestingUser)
        || !machineManageableBy(machineRegistry, machine.machineId, machineViewer(requestingUser))) {
        return sendJson(response, 409, { error: '페어링할 수 있는 서브 머신이 아닙니다.', reasonCode: 'PAIRING_MACHINE_UNAVAILABLE' })
      }

      const token = `mnprn_${randomBytes(32).toString('base64url')}`
      clearRunnerRuntimeRouting(machine.machineId)
      machineRegistry = setMachineToken(machineRegistry, machine.machineId, token)
      machineOperationQueue.wake(machine.machineId)
      await persistMachineRegistry()
      return sendJson(response, 200, {
        schemaVersion: 1,
        apiUrl: runnerApiBaseUrl,
        machineId: machine.machineId,
        label: machine.label,
        token,
      })
    }

    // Runner는 사용자 세션이 아니라 머신 토큰으로 인증한다.
    const machineRunnerClaimRoute = url.pathname.match(/^\/api\/machines\/([^/]+)\/runner\/operations\/claim$/)
    if (request.method === 'POST' && machineRunnerClaimRoute) {
      const runnerToken = runnerBearerToken(request)
      const machine = requireRunnerMachine(request, response, machineRunnerClaimRoute[1])
      if (!machine) return
      const body = await readJsonBody(request)
      const waitMs = Math.max(0, Math.min(machineOperationLongPollMs, Math.trunc(Number(body?.waitMs)) || machineOperationLongPollMs))
      noteRunnerCallbackBaseUrl(machine.machineId, body?.callbackBaseUrl)
      noteRunnerObservedAddress(machine.machineId, request)
      await noteMachineSeen(machine.machineId)

      // long-poll 도중 Runner가 끊기면 깨어난 이 요청이 오퍼레이션을 가져가 버린다.
      // 전달되지 못한 응답의 오퍼레이션은 대기열로 되돌려야 다음 Runner가 받을 수 있다.
      let claimed = []
      let delivered = false
      const releaseClaimed = () => {
        if (delivered || claimed.length === 0) return
        const operationIds = claimed.map((operation) => operation.operationId)
        claimed = []
        machineOperationQueue.release(machine.machineId, operationIds)
      }
      response.once('finish', () => { delivered = true })
      response.once('close', releaseClaimed)

      claimed = await machineOperationQueue.waitForClaim(machine.machineId, {
        limit: Number(body?.limit) || 1,
        waitMs,
        // 토큰 재발급·폐기 중 깨어난 구 Runner가 새 작업을 가져가지 못하게 한다.
        shouldClaim: () => verifyMachineToken(machineRegistry, machine.machineId, runnerToken),
      })
      // 대기 중에 이미 close가 발생했다면 위 핸들러는 빈 목록을 보았으므로 여기서 되돌린다.
      // 요청 스트림은 본문을 다 읽으면 정상적으로 destroy되므로 판단 근거로 쓸 수 없다.
      if (response.destroyed || response.writableEnded || request.socket?.destroyed === true) {
        releaseClaimed()
        return
      }
      if (!verifyMachineToken(machineRegistry, machine.machineId, runnerToken)) {
        return sendJson(response, 401, { error: 'Runner 인증에 실패했습니다.' })
      }
      return sendJson(response, 200, { operations: claimed })
    }

    const machineRunnerResultRoute = url.pathname.match(/^\/api\/machines\/([^/]+)\/runner\/operations\/([^/]+)\/result$/)
    if (request.method === 'POST' && machineRunnerResultRoute) {
      const machineId = normalizeMachineId(machineRunnerResultRoute[1])
      const operationId = machineRunnerResultRoute[2]
      const operationToken = String(request.headers['x-mnp-operation-token'] ?? '')
      const currentTokenIsValid = verifyMachineToken(machineRegistry, machineId, runnerBearerToken(request))
      const operationTokenIsValid = machineOperationQueue.verifyResultToken(machineId, operationId, operationToken)
      if (!currentTokenIsValid && !operationTokenIsValid) {
        return sendJson(response, 401, { error: 'Runner 결과 인증에 실패했습니다.' })
      }
      const body = await readJsonBody(request)
      try {
        const settled = machineOperationQueue.settle(machineId, operationId, body)
        return sendJson(response, 200, settled)
      } catch (error) {
        if (error instanceof MachineOperationError) return sendJson(response, 409, { error: error.message, reasonCode: error.reasonCode })
        throw error
      }
    }

    const machineRunnerHeartbeatRoute = url.pathname.match(/^\/api\/machines\/([^/]+)\/runner\/heartbeat$/)
    if (request.method === 'POST' && machineRunnerHeartbeatRoute) {
      const machine = requireRunnerMachine(request, response, machineRunnerHeartbeatRoute[1])
      if (!machine) return
      const body = await readJsonBody(request)
      noteRunnerCallbackBaseUrl(machine.machineId, body?.callbackBaseUrl)
      noteRunnerObservedAddress(machine.machineId, request)
      await noteMachineSeen(machine.machineId)
      return sendJson(response, 200, {
        machineId: machine.machineId,
        label: machine.label,
        longPollMs: machineOperationLongPollMs,
        queue: machineOperationQueue.snapshot(machine.machineId),
        serverStartedAt,
      })
    }

    // Runner를 거쳐 그 머신의 AionUi까지 실제로 닿는지 확인한다.
    const machineProbeRoute = url.pathname.match(/^\/api\/machines\/([^/]+)\/probe$/)
    if (request.method === 'POST' && machineProbeRoute) {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 머신 연결을 확인할 수 있습니다.' })

      const machineId = normalizeMachineId(machineProbeRoute[1])
      const machine = findMachine(machineRegistry, machineId)
      if (!machine) return sendJson(response, 404, { error: '등록된 머신을 찾지 못했습니다.' })
      if (!machineTargetableBy(machineRegistry, machine, machineViewer(user))
        && !machineManageableBy(machineRegistry, machineId, machineViewer(user))) {
        return sendJson(response, 403, { error: '본인 소유 머신만 연결을 확인할 수 있습니다.' })
      }

      const startedAt = Date.now()
      try {
        const snapshot = await fetchAionUiOn(machineId, '/api/internal/conversation-runtimes/active', { timeoutMs: 5_000 })
        return sendJson(response, 200, {
          machineId,
          reachable: true,
          elapsedMs: Date.now() - startedAt,
          conversationCount: Array.isArray(snapshot?.items) ? snapshot.items.length : null,
        })
      } catch (error) {
        return sendJson(response, 200, {
          machineId,
          reachable: false,
          elapsedMs: Date.now() - startedAt,
          reasonCode: error instanceof MachineOperationError ? error.reasonCode : null,
          error: error instanceof Error ? error.message : 'AionUi에 연결하지 못했습니다.',
        })
      }
    }

    const machinePairingRoute = url.pathname.match(/^\/api\/machines\/([^/]+)\/pairing$/)
    if (request.method === 'POST' && machinePairingRoute) {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 Runner를 연결할 수 있습니다.' })
      const machineId = normalizeMachineId(machinePairingRoute[1])
      if (!machineManageableBy(machineRegistry, machineId, machineViewer(user))) {
        return sendJson(response, 403, { error: '본인이 등록한 서브 머신의 Runner만 연결할 수 있습니다.' })
      }
      const machine = findMachine(machineRegistry, machineId)
      if (!machine || machine.machineId === machineRegistry.mainMachineId || !machine.enabled) {
        return sendJson(response, 409, { error: '활성화된 서브 머신만 Runner를 연결할 수 있습니다.' })
      }

      const pairing = machinePairingStore.issue({ machineId, requestedByUserId: user.id })
      return sendJson(response, 200, {
        machineId,
        expiresAt: pairing.expiresAt,
        launchUrl: createAionUiRunnerPairingUrl(runnerApiBaseUrl, pairing.code, machineId),
      })
    }

    // 기존 CLI Runner와의 호환을 위해 직접 토큰 API는 유지하되 UI에서는 노출하지 않는다.
    const machineTokenRoute = url.pathname.match(/^\/api\/machines\/([^/]+)\/token$/)
    if (machineTokenRoute) {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 Runner 토큰을 다룰 수 있습니다.' })
      if (!machineManageableBy(machineRegistry, machineTokenRoute[1], machineViewer(user))) {
        return sendJson(response, 403, { error: '본인이 등록한 서브 머신의 Runner 토큰만 다룰 수 있습니다.' })
      }

      if (request.method === 'POST') {
        const machineId = normalizeMachineId(machineTokenRoute[1])
        machinePairingStore.revokeMachine(machineId)
        const token = `mnprn_${randomBytes(32).toString('base64url')}`
        clearRunnerRuntimeRouting(machineId)
        try {
          machineRegistry = setMachineToken(machineRegistry, machineId, token)
        } catch (error) {
          if (error instanceof SubMachinePayloadError) return sendJson(response, 400, { error: error.message })
          throw error
        }
        // 대기 중인 구 토큰 long-poll을 즉시 깨워 재인증시킨다.
        machineOperationQueue.wake(machineId)
        await persistMachineRegistry()
        return sendJson(response, 200, { machineId, token })
      }

      if (request.method === 'DELETE') {
        const machineId = normalizeMachineId(machineTokenRoute[1])
        machinePairingStore.revokeMachine(machineId)
        clearRunnerRuntimeRouting(machineId)
        try {
          machineRegistry = setMachineToken(machineRegistry, machineId, null)
        } catch (error) {
          if (error instanceof SubMachinePayloadError) return sendJson(response, 400, { error: error.message })
          throw error
        }
        // 토큰을 폐기하면 그 머신으로 향하던 요청은 더 이상 전달될 수 없다.
        machineOperationQueue.cancelMachine(machineId, 'Runner 토큰이 폐기되었습니다.')
        await persistMachineRegistry()
        return sendJson(response, 200, machineRegistryResponse(user))
      }

      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    // 머신 목록은 편집자가 모두 조회하지만, 등록과 삭제는 소유자와 관리자만 할 수 있다.
    if (url.pathname === '/api/machines') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 머신 목록을 사용할 수 있습니다.' })

      if (request.method === 'GET') {
        return sendJson(response, 200, machineRegistryResponse(user))
      }

      if (request.method === 'POST') {
        const body = await readJsonBody(request)
        const targetMachineId = normalizeMachineId(body?.machineId)
        const existingMachine = findMachine(machineRegistry, targetMachineId)
        // 이미 등록된 머신을 고치는 경우에는 소유자와 관리자만 허용한다.
        if (existingMachine
          && !machineManageableBy(machineRegistry, targetMachineId, machineViewer(user))) {
          return sendJson(response, 403, { error: '본인이 등록한 서브 머신만 수정할 수 있습니다.' })
        }
        try {
          machineRegistry = upsertSubMachine(machineRegistry, {
            ...body,
            // 기존 머신은 소유자 변경을 명시한 경우에만 이전한다.
            ownerUserId: existingMachine
              ? (user.role === 'admin' && body?.ownerUserId ? body.ownerUserId : existingMachine.ownerUserId)
              : (user.role === 'admin' && body?.ownerUserId ? body.ownerUserId : user.id),
          })
        } catch (error) {
          if (error instanceof SubMachinePayloadError) return sendJson(response, 400, { error: error.message })
          throw error
        }
        await persistMachineRegistry()
        return sendJson(response, 200, machineRegistryResponse(user))
      }

      if (request.method === 'DELETE') {
        const body = await readJsonBody(request)
        const removedMachineId = normalizeMachineId(body?.machineId)
        if (findMachine(machineRegistry, removedMachineId)
          && !machineManageableBy(machineRegistry, removedMachineId, machineViewer(user))) {
          return sendJson(response, 403, { error: '본인이 등록한 서브 머신만 삭제할 수 있습니다.' })
        }
        try {
          machineRegistry = removeSubMachine(machineRegistry, body?.machineId)
        } catch (error) {
          if (error instanceof SubMachinePayloadError) return sendJson(response, 400, { error: error.message })
          throw error
        }
        machinePairingStore.revokeMachine(removedMachineId)
        clearRunnerRuntimeRouting(removedMachineId)
        // 등록이 사라진 머신으로 향하던 요청은 영원히 전달될 수 없으므로 즉시 실패로 확정한다.
        machineOperationQueue.cancelMachine(removedMachineId)
        // 삭제한 머신을 기본값으로 쓰던 사용자는 조회 시 자동으로 해제되지만 저장값도 함께 정리한다.
        for (const [userId, settings] of distributedWorkSettings.entries()) {
          if (settings.defaultMachineId !== removedMachineId) continue
          distributedWorkSettings.set(userId, { ...settings, defaultMachineId: null })
        }
        await Promise.all([persistMachineRegistry(), persistDistributedWorkSettings()])
        return sendJson(response, 200, machineRegistryResponse(user))
      }

      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    if (url.pathname === '/api/integrations/aionui/dialog-preferences') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화 시작 화면을 설정할 수 있습니다.' })
      if (request.method === 'GET') return sendJson(response, 200, { userId: user.id, sections: aiDialogPreferences.get(user.id) })
      if (request.method !== 'PATCH') return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
      const body = await readJsonBody(request)
      if (body?.expectedUserId !== user.id) return sendJson(response, 409, { error: '로그인 계정이 변경되었습니다. 대화 시작 창을 다시 열어 주세요.' })
      if (Object.keys(body).some(key => !['expectedUserId', 'sections'].includes(key))) return sendJson(response, 400, { error: '지원하지 않는 화면 설정입니다.' })
      try {
        return sendJson(response, 200, { userId: user.id, sections: await aiDialogPreferences.patch(user.id, body.sections) })
      } catch (error) {
        return sendJson(response, error.status ?? 500, { error: error.status ? error.message : '계정의 접힘 상태를 저장하지 못했습니다.' })
      }
    }

    if (url.pathname === '/api/integrations/aionui/workspaces') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 작업공간 이력을 사용할 수 있습니다.' })

      if (!['GET', 'POST', 'DELETE'].includes(request.method)) return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
      const body = request.method === 'GET' ? {} : await readJsonBody(request)
      if (body?.expectedUserId !== undefined && body.expectedUserId !== user.id) {
        return sendJson(response, 409, { error: '로그인 계정이 변경되었습니다. 대화 시작 창을 다시 열어 주세요.' })
      }
      const queryMachineId = url.searchParams.get('machineId')
      if (queryMachineId && body?.machineId && queryMachineId !== body.machineId) {
        return sendJson(response, 400, { error: '작업공간 이력의 머신 정보가 일치하지 않습니다.' })
      }
      let machineId
      try {
        // 머신을 보내지 않는 구버전 클라이언트는 메인 이력만 사용한다.
        machineId = resolveTargetMachineForUser(user, body?.machineId || queryMachineId || machineRegistry.mainMachineId).machineId
      } catch (error) {
        return sendJson(response, 400, { error: error.message })
      }
      const historyKey = JSON.stringify([user.id, machineId])
      const result = (workspaces) => ({ userId: user.id, machineId, workspaces })

      if (request.method === 'GET') {
        return sendJson(response, 200, result(aiWorkspaceHistories.get(historyKey) ?? []))
      }

      if (request.method === 'POST') {
        const currentWorkspaces = aiWorkspaceHistories.get(historyKey) ?? []

        if (typeof body?.workspace === 'string') {
          const workspace = body.workspace.trim()
          if (!workspace || workspace.length > AI_WORKSPACE_MAX_LENGTH) {
            return sendJson(response, 400, { error: '추가할 작업공간이 올바르지 않습니다.' })
          }
          const workspaces = rememberAiWorkspace(currentWorkspaces, workspace)
          aiWorkspaceHistories.set(historyKey, workspaces)
          await persistAiWorkspaceHistories()
          return sendJson(response, 200, result(workspaces))
        }

        if (body?.migration === true) {
          if (!Array.isArray(body.workspaces) || body.workspaces.length > AI_WORKSPACE_HISTORY_LIMIT
            || body.workspaces.some((workspace) => typeof workspace !== 'string'
              || !workspace.trim()
              || workspace.trim().length > AI_WORKSPACE_MAX_LENGTH)) {
            return sendJson(response, 400, { error: '가져올 작업공간 이력이 올바르지 않습니다.' })
          }
          if (aiWorkspaceHistories.has(historyKey)) return sendJson(response, 200, result(currentWorkspaces))
          const workspaces = normalizeAiWorkspaceHistory(body.workspaces)
          aiWorkspaceHistories.set(historyKey, workspaces)
          await persistAiWorkspaceHistories()
          return sendJson(response, 200, result(workspaces))
        }

        return sendJson(response, 400, { error: '추가할 작업공간이 올바르지 않습니다.' })
      }

      if (request.method === 'DELETE') {
        const workspace = typeof body.workspace === 'string' ? body.workspace.trim() : ''
        if (!workspace || workspace.length > AI_WORKSPACE_MAX_LENGTH) {
          return sendJson(response, 400, { error: '삭제할 작업공간이 올바르지 않습니다.' })
        }
        const workspaces = removeAiWorkspace(aiWorkspaceHistories.get(historyKey) ?? [], workspace)
        aiWorkspaceHistories.set(historyKey, workspaces)
        await persistAiWorkspaceHistories()
        return sendJson(response, 200, result(workspaces))
      }

      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    if (request.method === 'GET' && url.pathname === '/api/integrations/aionui/directories') {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 작업공간을 탐색할 수 있습니다.' })
      if (!isLocalLoopbackRequest(request)) {
        return sendJson(response, 403, {
          code: 'REMOTE_CLIENT',
          error: '작업공간 탐색은 서버와 같은 PC에서만 할 수 있습니다. 경로를 직접 입력해 주세요.',
        })
      }

      const requestedPath = (url.searchParams.get('path') ?? '').trim()
      if (requestedPath.length > AI_WORKSPACE_MAX_LENGTH) {
        return sendJson(response, 400, { error: '탐색할 경로가 너무 깁니다.' })
      }
      if (!requestedPath) return sendJson(response, 200, await listWorkspaceRoots())

      try {
        return sendJson(response, 200, await listWorkspaceDirectory(requestedPath))
      } catch (error) {
        if (error?.code === 'ENOENT') return sendJson(response, 404, { error: '폴더를 찾을 수 없습니다.' })
        if (error?.code === 'ENOTDIR') return sendJson(response, 400, { error: '폴더가 아닙니다.' })
        if (error?.code === 'EACCES' || error?.code === 'EPERM') {
          return sendJson(response, 403, { error: '이 폴더를 읽을 권한이 없습니다.' })
        }
        console.error('[workspace browse]', error)
        return sendJson(response, 500, { error: '폴더 목록을 불러오지 못했습니다.' })
      }
    }

    if (['/api/integrations/aionui/workspace-context', '/api/integrations/aionui/workspace-settings'].includes(url.pathname)) {
      const user = requireSignedInUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 작업공간을 설정할 수 있습니다.' })
      try {
        const body = request.method === 'POST' ? await readJsonBody(request) : Object.fromEntries(url.searchParams)
        const { machineId, machine, targets } = resolveTargetMachineForUser(user, body.machineId)
        if (request.method === 'POST' && url.pathname.endsWith('/workspace-settings')) {
          const setting = await aiWorkspaceSettings.save({ ...body, machineId }, publicUser(user))
          return sendJson(response, 200, { setting })
        }
        if (request.method !== 'GET' || !url.pathname.endsWith('/workspace-context')) return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
        return sendJson(response, 200, { ...await aiWorkspaceSettings.context({ mapId: body.mapId, groupId: body.groupId, machineId }),
          machines: targets.machines, machineRole: machine.role, workspaceBrowseAvailable: machine.role === 'main' && isLocalLoopbackRequest(request) })
      } catch (error) { return sendJson(response, error.status ?? 500, { error: error.message }) }
    }

    if (request.method === 'GET' && url.pathname === '/api/integrations/aionui/options') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '편집자만 AI 대화를 시작할 수 있습니다.' })

      let resolvedTarget = null
      try {
        resolvedTarget = resolveTargetMachineForUser(user, url.searchParams.get('machineId'))
        const { machineId, machine, targets } = resolvedTarget
        const workspaceContext = await aiWorkspaceSettings.context({ mapId: url.searchParams.get('mapId') || '', machineId })
        const workspaceOptions = { defaultWorkspace: workspaceContext.workspace, workspaceContext }
        const [agents, providers, skills, mcpServers] = await Promise.all([
          fetchAionUiOn(machineId, '/api/agents/management'),
          fetchAionUiOn(machineId, '/api/providers'),
          fetchAionUiOn(machineId, '/api/skills'),
          fetchAionUiOn(machineId, '/api/mcp/servers'),
        ])
        const normalizedAgents = (Array.isArray(agents) ? agents : [])
          .filter((agent) => agent?.enabled !== false && agent?.installed === true)
          .map((agent) => normalizeAionUiAgent(agent, Array.isArray(providers) ? providers.filter((item) => item?.enabled !== false) : []))
          .filter((agent) => agent.models.length > 0 || agent.backend === 'aionrs')
        const normalizedSkills = normalizeAionUiSkills(skills)
        const normalizedMcpServers = normalizeAionUiMcpServers(mcpServers)
        return sendJson(response, 200, {
          connected: true,
          machineId,
          machineLabel: machine.label,
          machineRole: machine.role,
          machines: targets.machines,
          aionUiUrl: machine.role === 'main' ? activeAionUiBaseUrl : null,
          protocol: 'aionui://conversation/new',
          ...workspaceOptions,
          workspaceBrowseAvailable: machine.role === 'main' && isLocalLoopbackRequest(request),
          agents: normalizedAgents,
          skills: normalizedSkills,
          mcpServers: normalizedMcpServers,
        })
      } catch (error) {
        if (error instanceof SubMachinePayloadError) return sendJson(response, 400, { error: error.message })
        console.error('[AionUi integration]', error)
        return sendJson(response, error.status ?? 503, {
          error: error.status === 409 ? error.message : 'AionUi에 연결할 수 없습니다. AionUi가 실행 중인지 확인해 주세요.',
          connected: false,
          ...(resolvedTarget ? {
            machineId: resolvedTarget.machineId,
            machineLabel: resolvedTarget.machine.label,
            machineRole: resolvedTarget.machine.role,
            machines: resolvedTarget.targets.machines,
            protocol: 'aionui://conversation/new',
            defaultWorkspace: '',
            workspaceBrowseAvailable: false,
            agents: [],
            skills: [],
            mcpServers: [],
          } : {}),
        })
      }
    }

    if (request.method === 'POST' && url.pathname === '/api/account/password') {
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: '공개 뷰어 계정은 비밀번호를 변경할 수 없습니다.' })
      const body = await readJsonBody(request)
      const currentPassword = String(body.currentPassword ?? '')
      const newPassword = String(body.newPassword ?? '')
      if (!currentPassword) return sendJson(response, 400, { error: '현재 비밀번호를 입력해 주세요.' })
      if (newPassword.length < 8) return sendJson(response, 400, { error: '새 비밀번호는 8자 이상이어야 합니다.' })
      if (newPassword.length > 128) return sendJson(response, 400, { error: '새 비밀번호는 128자 이하여야 합니다.' })
      const currentHash = hashPassword(currentPassword, user.salt)
      if (!timingSafeEqual(user.passwordHash, currentHash)) {
        return sendJson(response, 401, { error: '현재 비밀번호가 올바르지 않습니다.' })
      }
      if (timingSafeEqual(user.passwordHash, hashPassword(newPassword, user.salt))) {
        return sendJson(response, 400, { error: '현재 비밀번호와 다른 비밀번호를 입력해 주세요.' })
      }
      user.salt = randomBytes(16).toString('hex')
      user.passwordHash = hashPassword(newPassword, user.salt)
      user.updatedAt = new Date().toISOString()
      const currentToken = parseCookies(request).get('mnp_session') ?? null
      await invalidateUserSessions(user.id, currentToken)
      await persistUsers()
      return sendJson(response, 200, { ok: true })
    }

    if (url.pathname === '/api/admin/editors') {
      const admin = requireAdmin(request, response)
      if (!admin) return
      if (request.method === 'GET') {
        const editors = users.filter((candidate) => candidate.role === 'editor').map(accountUser)
        return sendJson(response, 200, { editors })
      }
      if (request.method === 'POST') {
        const body = await readJsonBody(request)
        const name = String(body.name ?? '').trim().slice(0, 60)
        const email = String(body.email ?? '').trim().toLowerCase().slice(0, 160)
        const suppliedPassword = String(body.password ?? '')
        if (name.length < 2) return sendJson(response, 400, { error: '이름을 2자 이상 입력해 주세요.' })
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return sendJson(response, 400, { error: '올바른 이메일을 입력해 주세요.' })
        if (users.some((candidate) => candidate.email.toLowerCase() === email)) return sendJson(response, 409, { error: '이미 사용 중인 이메일입니다.' })
        if (suppliedPassword && suppliedPassword.length < 8) return sendJson(response, 400, { error: '비밀번호는 8자 이상이어야 합니다.' })
        const generatedPassword = suppliedPassword || temporaryPassword()
        const salt = randomBytes(16).toString('hex')
        const now = new Date().toISOString()
        const editor = {
          id: `user-editor-${Date.now().toString(36)}-${randomBytes(3).toString('hex')}`,
          name,
          email,
          role: 'editor',
          active: true,
          createdAt: now,
          updatedAt: now,
          lastLoginAt: null,
          createdBy: admin.id,
          salt,
          passwordHash: hashPassword(generatedPassword, salt),
        }
        users.push(editor)
        await persistUsers()
        return sendJson(response, 201, {
          editor: accountUser(editor),
          temporaryPassword: suppliedPassword ? null : generatedPassword,
        })
      }
      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    const editorPasswordRoute = url.pathname.match(/^\/api\/admin\/editors\/([^/]+)\/reset-password$/)
    if (editorPasswordRoute && request.method === 'POST') {
      const admin = requireAdmin(request, response)
      if (!admin) return
      const editorId = decodeURIComponent(editorPasswordRoute[1])
      const editor = users.find((candidate) => candidate.id === editorId && candidate.role === 'editor')
      if (!editor) return sendJson(response, 404, { error: '편집자 계정을 찾을 수 없습니다.' })
      const password = temporaryPassword()
      editor.salt = randomBytes(16).toString('hex')
      editor.passwordHash = hashPassword(password, editor.salt)
      editor.updatedAt = new Date().toISOString()
      await invalidateUserSessions(editor.id)
      await persistUsers()
      return sendJson(response, 200, { editor: accountUser(editor), temporaryPassword: password })
    }

    const editorAccountRoute = url.pathname.match(/^\/api\/admin\/editors\/([^/]+)$/)
    if (editorAccountRoute) {
      const admin = requireAdmin(request, response)
      if (!admin) return
      const editorId = decodeURIComponent(editorAccountRoute[1])
      const editor = users.find((candidate) => candidate.id === editorId && candidate.role === 'editor')
      if (!editor) return sendJson(response, 404, { error: '편집자 계정을 찾을 수 없습니다.' })

      if (request.method === 'PATCH') {
        const body = await readJsonBody(request)
        const name = body.name === undefined ? editor.name : String(body.name).trim().slice(0, 60)
        const email = body.email === undefined ? editor.email : String(body.email).trim().toLowerCase().slice(0, 160)
        const active = body.active === undefined ? editor.active !== false : body.active === true
        if (name.length < 2) return sendJson(response, 400, { error: '이름을 2자 이상 입력해 주세요.' })
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return sendJson(response, 400, { error: '올바른 이메일을 입력해 주세요.' })
        if (users.some((candidate) => candidate.id !== editor.id && candidate.email.toLowerCase() === email)) {
          return sendJson(response, 409, { error: '이미 사용 중인 이메일입니다.' })
        }
        const wasActive = editor.active !== false
        editor.name = name
        editor.email = email
        editor.active = active
        editor.updatedAt = new Date().toISOString()
        if (!active) {
          await invalidateUserSessions(editor.id)
          if (wasActive) await decommissionEditorMachines(editor.id)
        }
        await persistUsers()
        return sendJson(response, 200, { editor: accountUser(editor) })
      }

      if (request.method === 'DELETE') {
        users = users.filter((candidate) => candidate.id !== editor.id)
        await invalidateUserSessions(editor.id)
        await decommissionEditorMachines(editor.id, { remove: true })
        for (const key of aiWorkspaceHistories.keys()) {
          if (JSON.parse(key)[0] === editor.id) aiWorkspaceHistories.delete(key)
        }
        distributedWorkSettings.delete(editor.id)
        await persistAiWorkspaceHistories()
        await persistDistributedWorkSettings()
        await persistUsers()
        return sendJson(response, 200, { deletedId: editor.id })
      }
      return sendJson(response, 405, { error: '지원하지 않는 요청입니다.' })
    }

    if (request.method === 'GET' && url.pathname === '/api/events') {
      const user = requireUser(request, response)
      if (!user) return
      const clientId = String(url.searchParams.get('clientId') ?? '').slice(0, 120) || `stream-${randomBytes(8).toString('hex')}`
      const requestedMapId = String(url.searchParams.get('mapId') ?? '')
      const mapId = isValidMapId(requestedMapId) ? requestedMapId : null
      response.writeHead(200, {
        'Content-Type': 'text/event-stream; charset=utf-8',
        'Cache-Control': 'no-cache, no-transform',
        Connection: 'keep-alive',
        'X-Accel-Buffering': 'no',
      })
      response.write(`data: ${JSON.stringify({ type: 'connected', user: publicUser(user), clientId, mapId })}\n\n`)
      eventClients.set(response, {
        clientId,
        mapId,
        user: publicUser(user),
        localLoopback: isLocalLoopbackRequest(request),
        selectionDeviceKey: aiConversationSelectionDeviceKey(requestClientAddress(request)),
      })
      broadcastPresence(mapId)
      void runtimeLifecycle.track(() => refreshAiConversationRuntimeLibrary())
        .then((summaries) => {
          if (!eventClients.has(response)) return
          response.write(`data: ${JSON.stringify({ type: 'ai-conversation-runtime-summary-snapshot', summaries })}\n\n`)
          if (mapId) {
            const runtimes = aiConversationRuntimeSnapshot(mapId)
            response.write(`data: ${JSON.stringify({ type: 'ai-conversation-runtime-snapshot', mapId, runtimes })}\n\n`)
          }
        })
        .catch((error) => console.warn('[AI conversation runtime initial refresh]', error))
      const cleanup = () => removeEventClient(response)
      request.on('close', cleanup)
      request.on('aborted', cleanup)
      response.on('error', cleanup)
      return
    }

    if (request.method === 'POST' && url.pathname === '/api/presence/cursor') {
      const user = requireUser(request, response)
      if (!user) return
      const body = await readJsonBody(request)
      const mapId = String(body.mapId ?? '')
      const x = Number(body.x)
      const y = Number(body.y)
      if (!isValidMapId(mapId) || !Number.isFinite(x) || !Number.isFinite(y)) {
        return sendJson(response, 400, { error: '올바르지 않은 커서 위치입니다.' })
      }
      broadcastEvent({
        type: 'cursor',
        mapId,
        x,
        y,
        sourceClientId: requestClientId(request),
        user: publicUser(user),
        updatedAt: new Date().toISOString(),
      })
      return sendJson(response, 200, { ok: true })
    }

    if (request.method === 'GET' && url.pathname === '/api/notifications') {
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 200, { notifications: [] })
      await ensureScheduleNotifications(user)
      return sendJson(response, 200, { notifications: await listNotifications(user.id) })
    }

    if (request.method === 'POST' && url.pathname === '/api/notifications/read-all') {
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 200, { notifications: [] })
      const readAt = new Date().toISOString()
      const notifications = (await listNotifications(user.id)).map((notification) => ({
        ...notification,
        readAt: notification.readAt ?? readAt,
      }))
      await writeStoredArray(notificationFileForUser(user.id), notifications)
      broadcastEvent({ type: 'notifications-read', userId: user.id, notificationId: null, readAt }, (client) => client.user.id === user.id)
      return sendJson(response, 200, { notifications })
    }

    const notificationReadRoute = url.pathname.match(/^\/api\/notifications\/([^/]+)\/read$/)
    if (notificationReadRoute && request.method === 'PATCH') {
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 404, { error: '알림을 찾을 수 없습니다.' })
      const notificationId = decodeURIComponent(notificationReadRoute[1])
      const notifications = await listNotifications(user.id)
      const target = notifications.find((notification) => notification.id === notificationId)
      if (!target) return sendJson(response, 404, { error: '알림을 찾을 수 없습니다.' })
      const readAt = target.readAt ?? new Date().toISOString()
      const updated = notifications.map((notification) => notification.id === notificationId ? { ...notification, readAt } : notification)
      await writeStoredArray(notificationFileForUser(user.id), updated)
      broadcastEvent({ type: 'notifications-read', userId: user.id, notificationId, readAt }, (client) => client.user.id === user.id)
      return sendJson(response, 200, { notification: { ...target, readAt } })
    }

    if (request.method === 'POST' && url.pathname === '/api/auth/logout') {
      const token = parseCookies(request).get('mnp_session')
      if (token) {
        const session = sessions.get(sessionTokenKey(token))
        sessions.delete(sessionTokenKey(token))
        if (session?.persistent) await persistSessions()
      }
      return sendJson(response, 200, { ok: true }, {
        'Set-Cookie': 'mnp_session=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0',
      })
    }

    if (request.method === 'GET' && url.pathname === '/api/document-groups') {
      const user = requireUser(request, response)
      if (!user) return
      const mapIds = url.searchParams.getAll('mapId')
      if (!mapIds.length || mapIds.length > 60 || mapIds.some((id) => id.length > 120 || !isValidMapId(id))) {
        return sendJson(response, 400, { error: '그룹을 확인할 문서 ID를 1~60개 지정하세요.' })
      }
      return sendJson(response, 200, { documentGroups: await readDocumentGroups(mapIds) })
    }

    if (request.method === 'GET' && url.pathname === '/api/maps') {
      const user = requireUser(request, response)
      if (!user) return
      const maps = await listMaps()
      const documentLayout = await readDocumentLayout(maps.map((map) => map.id))
      let payload
      try {
        const documentGroups = await readDocumentGroups(maps.map((map) => map.id), { maps, layout: documentLayout })
        const groupsByMap = new Map(documentGroups.map((context) => [context.mapId, context]))
        payload = {
          maps: maps.map((map) => ({ ...map, ...documentGroupFields(groupsByMap.get(map.id)) })),
          documentLayout, documentGroups, documentGroupsStatus: 'available',
        }
      } catch {
        // 총괄 부가 정보 오류 때문에 기존 문서 목록까지 열리지 않는 회귀를 막는다.
        payload = { maps, documentLayout, documentGroupsStatus: 'unavailable',
          documentGroupsWarning: '문서 목록은 확인했지만 그룹 부가 정보를 확인하지 못했습니다. 소속 없음으로 판단하지 말고 그룹 정보를 다시 조회하세요.' }
      }
      return sendJson(response, 200, payload)
    }

    if (request.method === 'GET' && url.pathname === '/api/shared-knowledge/audit') {
      const user = requireUser(request, response)
      if (!user) return
      const requestedMapIdParameter = url.searchParams.get('mapId')
      const requestedMapId = requestedMapIdParameter?.trim() ?? ''
      if (requestedMapIdParameter !== null && !isValidMapId(requestedMapId)) {
        return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      }
      const summaries = await listMaps()
      const selectedSummaries = requestedMapId
        ? summaries.filter((summary) => summary.id === requestedMapId)
        : summaries
      if (requestedMapId && selectedSummaries.length === 0) {
        return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      }
      const maps = (await Promise.all(selectedSummaries.map((summary) => readMap(summary.id)))).filter(Boolean)
      return sendJson(response, 200, { audit: buildSharedKnowledgeAudit(maps) })
    }

    const sharedKnowledgeReviewContextRoute = url.pathname.match(
      /^\/api\/maps\/([^/]+)\/cards\/([^/]+)\/shared-knowledge-review-context$/,
    )
    if (sharedKnowledgeReviewContextRoute && request.method === 'GET') {
      const mapId = decodeURIComponent(sharedKnowledgeReviewContextRoute[1])
      const cardId = decodeURIComponent(sharedKnowledgeReviewContextRoute[2])
      if (!isValidMapId(mapId) || !cardId || cardId.length > 120) {
        return sendJson(response, 400, { error: '문서 또는 카드 ID가 올바르지 않습니다.' })
      }
      const user = requireUser(request, response)
      if (!user) return
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const rawCommentLimit = url.searchParams.get('commentLimit')
      const commentLimit = rawCommentLimit === null ? 10 : Number(rawCommentLimit)
      if (!Number.isInteger(commentLimit) || commentLimit < 0 || commentLimit > 20) {
        return sendJson(response, 400, { error: 'commentLimit은 0~20의 정수여야 합니다.' })
      }
      const includeCommentDetail = url.searchParams.get('includeCommentDetail') === 'true'
      try {
        const context = buildSharedKnowledgeReviewContext(map, cardId)
        const allComments = await listComments(mapId, cardId)
        const comments = commentLimit > 0
          ? [...allComments].reverse().slice(0, commentLimit).map((comment) => commentForResponse(comment, includeCommentDetail))
          : []
        return sendJson(response, 200, {
          context: {
            ...context,
            accessUrl: `${publicBaseUrl}/mindmap/${encodeURIComponent(mapId)}/${encodeURIComponent(cardId)}`,
            comments,
            commentsPage: {
              total: allComments.length,
              returned: comments.length,
              order: 'desc',
              includesDetail: includeCommentDetail,
            },
          },
        })
      } catch (error) {
        if (sendSharedKnowledgeMaintenanceError(response, error)) return
        throw error
      }
    }

    const sharedKnowledgeReviewsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/shared-knowledge\/reviews$/)
    if (sharedKnowledgeReviewsRoute && request.method === 'POST') {
      const mapId = decodeURIComponent(sharedKnowledgeReviewsRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 공유 지식 검토 결과를 저장할 수 없습니다.' })
      const existing = await readMap(mapId)
      if (!existing || existing.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const body = await readJsonBody(request)
      const baseVersion = Number(body.baseVersion)
      if (!Number.isInteger(baseVersion) || baseVersion < 1) {
        return sendJson(response, 400, { error: '검토 문맥에서 확인한 문서 버전을 입력해 주세요.' })
      }
      if (baseVersion !== existing.version) {
        return sendJson(response, 409, {
          error: '다른 사용자가 먼저 문서를 변경했습니다. 검토 후보와 문맥을 다시 조회해 주세요.',
          code: 'VERSION_CONFLICT',
          currentVersion: existing.version,
        })
      }

      let prepared
      try {
        prepared = prepareSharedKnowledgeReviewBatch(existing, body.patches)
      } catch (error) {
        if (sendSharedKnowledgeMaintenanceError(response, error)) return
        throw error
      }

      let map
      let verifiedChanges
      try {
        map = await saveMap(
          mapId,
          prepared.map,
          user,
          existing.title,
          existing.color,
          'shared-knowledge-review',
          {
            sharedKnowledgeReviewRequests: prepared.reviewRequests,
            expectedVersion: baseVersion,
            validatePayload: (payload) => {
              verifiedChanges = verifySharedKnowledgeReviewChanges(payload, prepared.changes)
            },
          },
        )
      } catch (error) {
        if (error?.code === 'VERSION_CONFLICT') {
          return sendJson(response, 409, {
            error: '다른 사용자가 먼저 문서를 변경했습니다. 검토 후보와 문맥을 다시 조회해 주세요.',
            code: 'VERSION_CONFLICT',
            currentVersion: error.currentVersion,
          })
        }
        if (sendSharedKnowledgeMaintenanceError(response, error)) return
        throw error
      }

      broadcastMapChange(request, mapId, 'shared-knowledge-reviewed', user)
      return sendJson(response, 200, {
        document: mapSummary(map),
        changes: verifiedChanges,
        atomic: true,
      })
    }

    const mapImageAssetRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/images\/([^/]+)$/)
    if (mapImageAssetRoute && request.method === 'GET') {
      const user = requireUser(request, response)
      if (!user) return
      const mapId = decodeURIComponent(mapImageAssetRoute[1])
      const assetId = decodeURIComponent(mapImageAssetRoute[2])
      if (!isValidMapId(mapId) || !isValidImageAssetId(assetId)) {
        return sendJson(response, 400, { error: '올바르지 않은 이미지 자산 경로입니다.' })
      }
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '이미지가 속한 문서를 찾을 수 없습니다.' })
      try {
        const content = await readFile(imageAssetFile(mapId, assetId))
        response.writeHead(200, {
          'Content-Type': imageAssetMimeType(assetId),
          'Content-Length': content.length,
          'Cache-Control': 'private, max-age=31536000, immutable',
          'Content-Disposition': 'inline',
          'X-Content-Type-Options': 'nosniff',
        })
        response.end(content)
        return
      } catch (error) {
        if (error?.code === 'ENOENT') return sendJson(response, 404, { error: '이미지 자산을 찾을 수 없습니다.' })
        throw error
      }
    }

    if (mapImageAssetRoute && request.method === 'DELETE') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 이미지 자산을 삭제할 수 없습니다.' })
      const mapId = decodeURIComponent(mapImageAssetRoute[1])
      const assetId = decodeURIComponent(mapImageAssetRoute[2])
      if (!isValidMapId(mapId) || !isValidImageAssetId(assetId)) {
        return sendJson(response, 400, { error: '올바르지 않은 이미지 자산 경로입니다.' })
      }
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '이미지가 속한 문서를 찾을 수 없습니다.' })
      const deletedNodeIds = map.nodes
        .filter((node) => node.data?.kind === 'image' && node.data?.image?.assetId === assetId)
        .map((node) => node.id)
      const deletedNodeIdSet = new Set(deletedNodeIds)
      let updatedMap = map
      if (deletedNodeIds.length > 0) {
        updatedMap = await saveMap(mapId, {
          nodes: map.nodes.filter((node) => !deletedNodeIdSet.has(node.id)),
          edges: map.edges.filter((edge) => !deletedNodeIdSet.has(edge.source) && !deletedNodeIdSet.has(edge.target)),
        }, user, undefined, undefined, 'content')
      }
      if (deletedNodeIds.length > 0) broadcastMapChange(request, mapId, 'content', user)
      return sendJson(response, 200, {
        deletedAssetId: null,
        retainedAssetId: assetId,
        assetDeletionDeferred: true,
        deletedNodeIds,
        map: updatedMap,
        summary: mapSummary(updatedMap),
      })
    }

    const mapImageUploadRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/images$/)
    if (mapImageUploadRoute && request.method === 'POST') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 이미지를 추가할 수 없습니다.' })
      const mapId = decodeURIComponent(mapImageUploadRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '이미지를 추가할 문서를 찾을 수 없습니다.' })
      const declaredSize = Number(request.headers['content-length'])
      if (Number.isFinite(declaredSize) && declaredSize > imageAssetMaxBytes) {
        return sendJson(response, 413, { error: `이미지는 ${Math.round(imageAssetMaxBytes / 1_000_000)}MB 이하만 추가할 수 있습니다.` })
      }
      const content = await readBinaryBody(request, imageAssetMaxBytes)
      const detectedType = detectImageAssetType(content)
      if (!detectedType) {
        return sendJson(response, 415, { error: 'PNG, JPEG, GIF 또는 WebP 이미지만 추가할 수 있습니다.' })
      }
      const assetId = `${randomBytes(16).toString('hex')}.${detectedType.extension}`
      const targetDirectory = imageAssetsDirectoryForMap(mapId)
      await mkdir(targetDirectory, { recursive: true })
      await writeFile(imageAssetFile(mapId, assetId), content, { flag: 'wx', mode: 0o600 })
      return sendJson(response, 201, {
        image: {
          assetId,
          mimeType: detectedType.mimeType,
        },
      })
    }

    if (request.method === 'GET' && url.pathname === '/api/maps/trash') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 휴지통을 볼 수 없습니다.' })
      return sendJson(response, 200, { maps: await listMaps({ trashedOnly: true }) })
    }

    if (request.method === 'DELETE' && url.pathname === '/api/maps/trash') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 휴지통 문서를 영구 삭제할 수 없습니다.' })
      const body = await readJsonBody(request)
      const trash = await listMaps({ trashedOnly: true })
      const requestedIds = body.all === true
        ? trash.map((map) => map.id)
        : Array.isArray(body.mapIds) ? [...new Set(body.mapIds)] : []
      if (requestedIds.length === 0) return sendJson(response, 400, { error: '영구 삭제할 휴지통 문서를 선택해 주세요.' })
      if (requestedIds.some((mapId) => typeof mapId !== 'string' || !isValidMapId(mapId))) {
        return sendJson(response, 400, { error: '올바르지 않은 문서 ID가 포함되어 있습니다.' })
      }
      const trashIds = new Set(trash.map((map) => map.id))
      if (requestedIds.some((mapId) => !trashIds.has(mapId))) {
        return sendJson(response, 404, { error: '휴지통에서 일부 문서를 찾을 수 없습니다. 목록을 새로고침해 주세요.' })
      }
      const deletedIds = await permanentlyDeleteTrashedMaps(requestedIds)
      if (!deletedIds) return sendJson(response, 409, { error: '휴지통 상태가 변경되었습니다. 목록을 새로고침해 주세요.' })
      broadcastEvent({
        type: 'map-changed',
        mapId: null,
        action: body.all === true ? 'trash-emptied' : 'trash-deleted',
        deletedIds,
        sourceClientId: requestClientId(request),
        updatedAt: new Date().toISOString(),
        updatedBy: publicUser(user),
      })
      return sendJson(response, 200, {
        deletedIds,
        trash: await listMaps({ trashedOnly: true }),
      })
    }

    if (request.method === 'POST' && url.pathname === '/api/maps') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) {
        return sendJson(response, 403, { error: '뷰어는 마인드맵을 생성할 수 없습니다.' })
      }
      const body = await readJsonBody(request)
      if (!isValidMap(body.map)) return sendJson(response, 400, { error: '올바르지 않은 마인드맵 데이터입니다.' })
      if (body.color !== undefined && !mapColors.includes(body.color)) return sendJson(response, 400, { error: '올바르지 않은 문서 색상입니다.' })
      const mapId = `map-${Date.now().toString(36)}-${randomBytes(3).toString('hex')}`
      const map = await saveMap(mapId, body.map, user, body.title, body.color)
      const maps = await listMaps()
      const documentLayout = await reconcileDocumentLayout(maps.map((item) => item.id))
      broadcastMapChange(request, mapId, 'created', user)
      return sendJson(response, 201, { map, summary: mapSummary(map), documentLayout })
    }

    if (request.method === 'PATCH' && url.pathname === '/api/maps/layout') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 문서 그룹과 순서를 변경할 수 없습니다.' })
      const body = await readJsonBody(request)
      return await groupProjects.exclusive(async () => {
      const maps = await listMaps()
      const mapIds = maps.map((map) => map.id)
      if (!isCompleteDocumentLayout(body.documentLayout, mapIds)) {
        return sendJson(response, 400, { error: '문서 그룹과 순서 데이터가 올바르지 않습니다.' })
      }
      const documentLayout = normalizeDocumentLayout(body.documentLayout, mapIds)
      await groupProjects.validateLayout(documentLayout)
      await writeDocumentLayout(documentLayout)
      broadcastEvent({
        type: 'map-changed',
        mapId: null,
        action: 'layout',
        sourceClientId: requestClientId(request),
        updatedAt: new Date().toISOString(),
        updatedBy: publicUser(user),
      })
      return sendJson(response, 200, { maps: await listMaps(), documentLayout })
      })
    }

    if (request.method === 'PATCH' && url.pathname === '/api/maps/order') {
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 문서 순서를 변경할 수 없습니다.' })
      const body = await readJsonBody(request)
      const requestedIds = Array.isArray(body.mapIds) ? [...new Set(body.mapIds)] : []
      const existingIds = (await listMaps()).map((map) => map.id)
      const hasSameMaps = requestedIds.length === existingIds.length
        && requestedIds.every((mapId) => typeof mapId === 'string' && existingIds.includes(mapId))
      if (!hasSameMaps) return sendJson(response, 400, { error: '문서 순서 데이터가 올바르지 않습니다.' })
      const orderIndex = new Map(requestedIds.map((mapId, index) => [mapId, index]))
      const currentLayout = await readDocumentLayout(existingIds)
      const groups = currentLayout.groups.map((group) => ({
        ...group,
        mapIds: [...group.mapIds].sort((first, second) => orderIndex.get(first) - orderIndex.get(second)),
      }))
      const groupsById = new Map(groups.map((group) => [group.id, group]))
      const documentLayout = {
        version: 1,
        groups,
        items: currentLayout.items
          .map((item, index) => ({
            item,
            index,
            order: item.type === 'map'
              ? orderIndex.get(item.id)
              : Math.min(...(groupsById.get(item.id)?.mapIds ?? []).map((mapId) => orderIndex.get(mapId)), Number.MAX_SAFE_INTEGER),
          }))
          .sort((first, second) => first.order - second.order || first.index - second.index)
          .map(({ item }) => item),
      }
      await writeDocumentLayout(documentLayout)
      broadcastEvent({
        type: 'map-changed',
        mapId: null,
        action: 'order',
        sourceClientId: requestClientId(request),
        updatedAt: new Date().toISOString(),
        updatedBy: publicUser(user),
      })
      return sendJson(response, 200, { maps: await listMaps(), documentLayout })
    }

    const commentStatsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/comments\/stats$/)
    if (commentStatsRoute && request.method === 'GET') {
      const mapId = decodeURIComponent(commentStatsRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      return sendJson(response, 200, { stats: buildNodeCommentStats(await listComments(mapId)) })
    }

    const commentReactionRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/comments\/([^/]+)\/reactions$/)
    if (commentReactionRoute && request.method === 'POST') {
      const mapId = decodeURIComponent(commentReactionRoute[1])
      const commentId = decodeURIComponent(commentReactionRoute[2])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: '공개 뷰어는 댓글 반응을 변경할 수 없습니다.' })
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const body = await readJsonBody(request)
      const emoji = String(body.emoji ?? '')
      if (!commentReactions.includes(emoji)) return sendJson(response, 400, { error: '지원하지 않는 댓글 반응입니다.' })
      const comments = await listComments(mapId)
      const target = comments.find((item) => item.id === commentId)
      if (!target) return sendJson(response, 404, { error: '댓글을 찾을 수 없습니다.' })
      const currentUsers = Array.isArray(target.reactions?.[emoji]) ? target.reactions[emoji] : []
      const reacted = currentUsers.includes(user.id)
      const comment = {
        ...target,
        reactions: {
          ...target.reactions,
          [emoji]: reacted ? currentUsers.filter((userId) => userId !== user.id) : [...currentUsers, user.id],
        },
      }
      await writeStoredArray(commentFileForMap(mapId), comments.map((item) => item.id === commentId ? comment : item))
      broadcastEvent({ type: 'comment-changed', mapId, nodeId: comment.nodeId, action: 'updated', comment })
      return sendJson(response, 200, { comment })
    }

    const commentResolveRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/comments\/([^/]+)\/resolve$/)
    if (commentResolveRoute && request.method === 'PATCH') {
      const mapId = decodeURIComponent(commentResolveRoute[1])
      const commentId = decodeURIComponent(commentResolveRoute[2])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: '공개 뷰어는 댓글 상태를 변경할 수 없습니다.' })
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const comments = await listComments(mapId)
      const target = comments.find((item) => item.id === commentId)
      if (!target) return sendJson(response, 404, { error: '댓글을 찾을 수 없습니다.' })
      if (!canEdit(user) && target.author.id !== user.id) {
        return sendJson(response, 403, { error: '댓글 작성자 또는 편집자만 해결 상태를 변경할 수 있습니다.' })
      }
      const body = await readJsonBody(request)
      const resolved = body.resolved === true
      const comment = {
        ...target,
        resolvedAt: resolved ? new Date().toISOString() : null,
        resolvedBy: resolved ? publicUser(user) : null,
      }
      await writeStoredArray(commentFileForMap(mapId), comments.map((item) => item.id === commentId ? comment : item))
      broadcastEvent({ type: 'comment-changed', mapId, nodeId: comment.nodeId, action: 'updated', comment })
      return sendJson(response, 200, { comment })
    }

    const commentItemRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/comments\/([^/]+)$/)
    if (commentItemRoute && request.method === 'PATCH') {
      const mapId = decodeURIComponent(commentItemRoute[1])
      const commentId = decodeURIComponent(commentItemRoute[2])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: '공개 뷰어는 댓글을 수정할 수 없습니다.' })
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const comments = await listComments(mapId)
      const target = comments.find((item) => item.id === commentId)
      if (!target) return sendJson(response, 404, { error: '댓글을 찾을 수 없습니다.' })
      if (!canEdit(user) && target.author.id !== user.id) {
        return sendJson(response, 403, { error: '댓글 작성자 또는 편집자만 댓글을 수정할 수 있습니다.' })
      }
      const body = await readJsonBody(request)
      if (typeof body.expectedText === 'string' && target.text !== body.expectedText) {
        return sendJson(response, 409, {
          error: '댓글 원문이 조회 이후 변경되었습니다. 최신 댓글을 다시 확인해 주세요.',
          currentComment: commentForResponse(target, true),
        })
      }
      const updatedContent = updateCommentContent(target, body)
      if (updatedContent.error) return sendJson(response, 400, { error: updatedContent.error })
      const comment = {
        ...updatedContent.content,
        updatedAt: new Date().toISOString(),
      }
      await writeStoredArray(commentFileForMap(mapId), comments.map((item) => item.id === commentId ? comment : item))
      broadcastEvent({ type: 'comment-changed', mapId, nodeId: comment.nodeId, action: 'updated', comment })
      return sendJson(response, 200, { comment })
    }

    if (commentItemRoute && request.method === 'DELETE') {
      const mapId = decodeURIComponent(commentItemRoute[1])
      const commentId = decodeURIComponent(commentItemRoute[2])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (isPublicViewer(user)) return sendJson(response, 403, { error: '공개 뷰어는 댓글을 삭제할 수 없습니다.' })
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const comments = await listComments(mapId)
      const comment = comments.find((item) => item.id === commentId)
      if (!comment) return sendJson(response, 404, { error: '댓글을 찾을 수 없습니다.' })
      if (!canEdit(user) && comment.author.id !== user.id) {
        return sendJson(response, 403, { error: '자신이 작성한 댓글만 삭제할 수 있습니다.' })
      }
      const deletedIds = new Set([commentId])
      let foundDescendant = true
      while (foundDescendant) {
        foundDescendant = false
        for (const item of comments) {
          if (item.parentId && deletedIds.has(item.parentId) && !deletedIds.has(item.id)) {
            deletedIds.add(item.id)
            foundDescendant = true
          }
        }
      }
      await writeStoredArray(commentFileForMap(mapId), comments.filter((item) => !deletedIds.has(item.id)))
      const notificationCleanupResults = await Promise.allSettled(users.map(async (recipient) => {
        const notifications = await listNotifications(recipient.id)
        const removedIds = notifications.filter((notification) => deletedIds.has(notification.commentId)).map((notification) => notification.id)
        if (removedIds.length === 0) return
        await writeStoredArray(notificationFileForUser(recipient.id), notifications.filter((notification) => !deletedIds.has(notification.commentId)))
        broadcastEvent({ type: 'notifications-removed', userId: recipient.id, notificationIds: removedIds }, (client) => client.user.id === recipient.id)
      }))
      reportRejectedSideEffects(notificationCleanupResults, 'Comment notification cleanup')
      broadcastEvent({ type: 'comment-changed', mapId, nodeId: comment.nodeId, action: 'deleted', commentIds: [...deletedIds] })
      return sendJson(response, 200, { deletedIds: [...deletedIds] })
    }

    const commentsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/comments$/)
    if (commentsRoute) {
      const mapId = decodeURIComponent(commentsRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })

      if (request.method === 'GET') {
        const nodeId = String(url.searchParams.get('nodeId') ?? '').slice(0, 120)
        const comments = await listComments(mapId, nodeId || undefined)
        const includeDetail = url.searchParams.get('includeDetail') !== 'false'
        const responseComments = comments.map((comment) => commentForResponse(comment, includeDetail))
        const limitValue = url.searchParams.get('limit')
        if (limitValue === null) return sendJson(response, 200, { comments: responseComments })
        const offset = Math.max(0, Number.parseInt(url.searchParams.get('offset') ?? '0', 10) || 0)
        const limit = Math.min(100, Math.max(1, Number.parseInt(limitValue, 10) || 50))
        const order = url.searchParams.get('order') === 'asc' ? 'asc' : 'desc'
        const ordered = order === 'asc' ? responseComments : [...responseComments].reverse()
        const page = ordered.slice(offset, offset + limit)
        const nextOffset = offset + page.length
        return sendJson(response, 200, {
          comments: page,
          total: responseComments.length,
          offset,
          limit,
          order,
          hasMore: nextOffset < comments.length,
          nextOffset: nextOffset < comments.length ? nextOffset : null,
        })
      }

      if (request.method === 'POST') {
        if (isPublicViewer(user)) return sendJson(response, 403, { error: '공개 뷰어는 댓글을 작성할 수 없습니다.' })
        const body = await readJsonBody(request)
        const nodeId = String(body.nodeId ?? '').slice(0, 120)
        const node = map.nodes.find((item) => item.id === nodeId)
        if (!node) return sendJson(response, 400, { error: '댓글을 남길 노드를 찾을 수 없습니다.' })
        const createdContent = createCommentContent(body)
        if (createdContent.error) return sendJson(response, 400, { error: createdContent.error })
        const comments = await listComments(mapId)
        const requestedParentId = typeof body.parentId === 'string' ? body.parentId : null
        const requestedParent = requestedParentId ? comments.find((item) => item.id === requestedParentId && item.nodeId === nodeId) : null
        if (requestedParentId && !requestedParent) return sendJson(response, 400, { error: '답글을 남길 댓글을 찾을 수 없습니다.' })
        const parent = requestedParent ? comments.find((item) => item.id === (requestedParent.parentId ?? requestedParent.id)) ?? requestedParent : null
        const comment = {
          id: `comment-${Date.now().toString(36)}-${randomBytes(4).toString('hex')}`,
          mapId,
          nodeId,
          ...createdContent.content,
          parentId: parent?.id ?? null,
          resolvedAt: null,
          resolvedBy: null,
          reactions: {},
          createdAt: new Date().toISOString(),
          author: publicUser(user),
        }
        await writeStoredArray(commentFileForMap(mapId), [...comments, comment])
        const notificationSummary = comment.summary ?? comment.text
        const mentionSource = [notificationSummary, comment.detail].filter(Boolean).join('\n')
        const mentionedIds = new Set(mentionedUsers(mentionSource).map((candidate) => candidate.id))
        const notificationResults = await Promise.allSettled(users
          .filter((recipient) => recipient.id !== user.id && recipient.active !== false && !isPublicViewer(recipient))
          .map((recipient) => createNotification(recipient, {
            type: mentionedIds.has(recipient.id) ? 'mention' : parent?.author.id === recipient.id ? 'reply' : 'comment',
            mapId,
            mapTitle: map.title,
            nodeId,
            nodeLabel: node.data.label,
            commentId: comment.id,
            message: notificationSummary.slice(0, 180),
            actor: publicUser(user),
          })))
        reportRejectedSideEffects(notificationResults, 'Comment notification creation')
        broadcastEvent({ type: 'comment-changed', mapId, nodeId, action: 'created', comment })
        return sendJson(response, 201, { comment })
      }
    }

    const revisionRestoreRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/history\/([^/]+)\/restore$/)
    if (revisionRestoreRoute && request.method === 'POST') {
      const mapId = decodeURIComponent(revisionRestoreRoute[1])
      const revisionId = decodeURIComponent(revisionRestoreRoute[2])
      if (!isValidMapId(mapId) || !isValidRevisionId(revisionId)) return sendJson(response, 400, { error: '올바르지 않은 변경 이력 요청입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 이전 버전을 복원할 수 없습니다.' })
      const current = await readMap(mapId)
      if (!current || current.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const revision = await readMapRevision(mapId, revisionId)
      if (!revision) return sendJson(response, 404, { error: '변경 이력을 찾을 수 없습니다.' })
      await writeDailyBackup(current, user, 'before-history-restore')
      await archiveMapRevision(current, user, 'history-restore')
      const map = {
        id: mapId,
        title: normalizeTitle(revision.map.title, current.title),
        color: normalizeMapColor(revision.map.color, current.color),
        nodes: revision.map.nodes,
        edges: revision.map.edges,
        updatedAt: new Date().toISOString(),
        updatedBy: publicUser(user),
        version: (current.version ?? 1) + 1,
        restoredFrom: revisionId,
      }
      await writeStoredMap(mapId, map)
      broadcastMapChange(request, mapId, 'history-restored', user)
      const historyPage = await listMapRevisions(mapId)
      return sendJson(response, 200, {
        map,
        summary: mapSummary(map),
        revisions: historyPage.revisions,
        historyHasMore: historyPage.hasMore,
        historyNextOffset: historyPage.nextOffset,
      })
    }

    const dailyBackupRestoreRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/backups\/daily\/(\d{4}-\d{2}-\d{2})\/restore$/)
    if (dailyBackupRestoreRoute && request.method === 'POST') {
      const mapId = decodeURIComponent(dailyBackupRestoreRoute[1])
      const date = dailyBackupRestoreRoute[2]
      if (!isValidMapId(mapId) || !isValidDailyBackupDate(date)) return sendJson(response, 400, { error: '올바르지 않은 일일 백업 요청입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 일일 백업을 복원할 수 없습니다.' })
      const current = await readMap(mapId)
      if (!current || current.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const backup = await readDailyBackup(mapId, date)
      if (!backup) return sendJson(response, 404, { error: '일일 백업을 찾을 수 없습니다.' })
      await writeDailyBackup(current, user, 'before-daily-restore')
      await archiveMapRevision(current, user, 'daily-backup-restore')
      const map = {
        id: mapId,
        title: normalizeTitle(backup.map.title, current.title),
        color: normalizeMapColor(backup.map.color, current.color),
        nodes: backup.map.nodes,
        edges: backup.map.edges,
        createdAt: current.createdAt ?? backup.map.createdAt ?? null,
        createdBy: current.createdBy ?? backup.map.createdBy ?? null,
        updatedAt: new Date().toISOString(),
        updatedBy: publicUser(user),
        version: (current.version ?? 1) + 1,
        restoredFromDailyBackup: date,
      }
      await writeStoredMap(mapId, map)
      broadcastMapChange(request, mapId, 'daily-backup-restored', user)
      const historyPage = await listMapRevisions(mapId)
      return sendJson(response, 200, {
        map,
        summary: mapSummary(map),
        dailyBackups: await listDailyBackups(mapId),
        revisions: historyPage.revisions,
        historyHasMore: historyPage.hasMore,
        historyNextOffset: historyPage.nextOffset,
      })
    }

    const dailyBackupPreviewRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/backups\/daily\/(\d{4}-\d{2}-\d{2})\/preview$/)
    if (dailyBackupPreviewRoute && request.method === 'GET') {
      const mapId = decodeURIComponent(dailyBackupPreviewRoute[1])
      const date = dailyBackupPreviewRoute[2]
      if (!isValidMapId(mapId) || !isValidDailyBackupDate(date)) return sendJson(response, 400, { error: '올바르지 않은 일일 백업 요청입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const backup = await readDailyBackup(mapId, date)
      if (!backup) return sendJson(response, 404, { error: '일일 백업을 찾을 수 없습니다.' })
      return sendJson(response, 200, {
        backup: {
          ...dailyBackupSummary(backup),
          map: backup.map,
        },
      })
    }

    const dailyBackupsRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/backups\/daily$/)
    if (dailyBackupsRoute && request.method === 'GET') {
      const mapId = decodeURIComponent(dailyBackupsRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      return sendJson(response, 200, { dailyBackups: await listDailyBackups(mapId) })
    }

    const historyRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/history$/)
    if (historyRoute && request.method === 'GET') {
      const mapId = decodeURIComponent(historyRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      const map = await readMap(mapId)
      if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      const offset = Number(url.searchParams.get('offset') ?? 0)
      const limit = Number(url.searchParams.get('limit') ?? 50)
      if (!Number.isInteger(offset) || offset < 0 || !Number.isInteger(limit) || limit < 1 || limit > 100) {
        return sendJson(response, 400, { error: '변경 이력 조회 범위가 올바르지 않습니다.' })
      }
      return sendJson(response, 200, await listMapRevisions(mapId, { offset, limit }))
    }

    const restoreRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/restore$/)
    if (restoreRoute && request.method === 'POST') {
      const mapId = decodeURIComponent(restoreRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 문서를 복원할 수 없습니다.' })
      const map = await restoreMap(mapId, user)
      if (!map) return sendJson(response, 404, { error: '휴지통에서 문서를 찾을 수 없습니다.' })
      const maps = await listMaps()
      const documentLayout = await reconcileDocumentLayout(maps.map((item) => item.id))
      broadcastMapChange(request, mapId, 'trash-restored', user)
      return sendJson(response, 200, {
        map,
        summary: mapSummary(map),
        maps,
        documentLayout,
        trash: await listMaps({ trashedOnly: true }),
      })
    }

    const aiConversationWorkStatesRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/ai-conversation-work-states$/)
    if (aiConversationWorkStatesRoute && request.method === 'GET') {
      const mapId = decodeURIComponent(aiConversationWorkStatesRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return
      const requestedCardIds = url.searchParams.getAll('cardId').map((cardId) => cardId.trim()).filter(Boolean)
      if (requestedCardIds.length > 200 || requestedCardIds.some((cardId) => cardId.length > 120)) {
        return sendJson(response, 400, { error: '조회할 카드 ID가 올바르지 않습니다.' })
      }
      const result = await aiConversationWorkStates(mapId, requestedCardIds)
      if (!result) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
      if (result.error === 'CARD_NOT_FOUND') {
        return sendJson(response, 404, {
          error: '카드를 찾을 수 없습니다.',
          missingCardIds: result.missingCardIds,
        })
      }
      return sendJson(response, 200, result)
    }

    const crossDocumentCardMoveRoute = url.pathname.match(/^\/api\/maps\/([^/]+)\/cards\/([^/]+)\/move$/)
    if (crossDocumentCardMoveRoute && request.method === 'POST') {
      const sourceMapId = decodeURIComponent(crossDocumentCardMoveRoute[1])
      const cardId = decodeURIComponent(crossDocumentCardMoveRoute[2])
      const user = requireUser(request, response)
      if (!user) return
      if (!canEdit(user)) return sendCardMoveResponse(response, 403, { error: '뷰어는 카드를 다른 문서로 이동할 수 없습니다.' })
      const body = await readJsonBody(request)
      const targetMapId = String(body.targetMapId ?? '').trim()
      const targetParentCardId = String(body.targetParentCardId ?? body.newParentCardId ?? '').trim()
      if (!isValidMapId(sourceMapId) || !isValidMapId(targetMapId)
        || !cardId || cardId.length > 120 || !targetParentCardId || targetParentCardId.length > 120) {
        return sendCardMoveResponse(response, 400, {
          error: '원본·대상 문서 ID와 이동할 카드·새 상위 카드 ID를 확인하세요.',
          code: 'CARD_MOVE_INVALID_REQUEST',
        })
      }
      const result = await moveCardAcrossDocuments({
        sourceMapId,
        cardId,
        targetMapId,
        targetParentCardId,
        sourceVersion: Number(body.sourceVersion),
        targetVersion: Number(body.targetVersion),
        user,
      })
      const changedMapIds = [...new Set([
        sourceMapId,
        targetMapId,
        ...result.operation.updatedReferenceMapIds,
      ])]
      for (const mapId of changedMapIds) broadcastMapChange(request, mapId, 'cross-document-card-move', user)
      const movedCard = result.targetMap.nodes.find((node) => node.id === cardId)
      const responseMode = body.responseMode === 'full' ? 'full' : 'affected'
      return sendCardMoveResponse(response, 200, {
        responseMode,
        atomic: true,
        operation: result.operation,
        sourceDocument: mapSummary(result.sourceMap),
        targetDocument: mapSummary(result.targetMap),
        sourceMapId,
        targetMapId,
        movedCardId: cardId,
        movedCardIds: result.operation.movedCardIds,
        card: movedCard,
        accessUrl: `${publicBaseUrl}/mindmap/${encodeURIComponent(targetMapId)}/${encodeURIComponent(cardId)}`,
        hierarchy: {
          previousParentCardId: result.operation.previousParentCardId,
          newParentCardId: targetParentCardId,
        },
        ...(responseMode === 'full' ? { sourceMap: result.sourceMap, targetMap: result.targetMap } : {}),
      })
    }

    const mapRoute = url.pathname.match(/^\/api\/maps\/([^/]+)$/)
    if (mapRoute) {
      const mapId = decodeURIComponent(mapRoute[1])
      if (!isValidMapId(mapId)) return sendJson(response, 400, { error: '올바르지 않은 문서 ID입니다.' })
      const user = requireUser(request, response)
      if (!user) return

      if (request.method === 'GET') {
        const map = await readMap(mapId)
        if (!map || map.trashedAt) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
        const resolved = await resolveReferencesForMap(map)
        const delegationOrigin = await resolveOrRememberDelegationSource(integrationRequestScope(request), mapId, map)
        const documentGroups = await readDocumentGroups([mapId])
        return sendJson(response, 200, {
          map: resolved.map,
          ...documentGroupFields(documentGroups[0]),
          documentGroups,
          referenceCommentStats: resolved.referenceCommentStats,
          unresolvedReferenceNodeIds: resolved.unresolvedReferenceNodeIds,
          ...(delegationOrigin ? { delegationOrigin } : {}),
        })
      }

      if (request.method === 'PUT') {
        if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 마인드맵을 변경할 수 없습니다.' })
        const existing = await readMap(mapId)
        if (existing?.trashedAt) return sendJson(response, 409, { error: '휴지통에 있는 문서는 변경할 수 없습니다.' })
        const body = await readJsonBody(request)
        if (!isValidMap(body.map)) return sendJson(response, 400, { error: '올바르지 않은 마인드맵 데이터입니다.' })
        const normalizedIncomingMap = reconcileSharedKnowledgeReviews(existing, normalizeMapForPersistence(body.map))
        const baseVersion = Number(body.baseVersion)
        if (existing && Number.isInteger(baseVersion) && baseVersion !== existing.version && body.force !== true) {
          return sendJson(response, 409, {
            error: '다른 사용자가 먼저 문서를 변경했습니다.',
            code: 'VERSION_CONFLICT',
            map: existing,
            summary: mapSummary(existing),
          })
        }
        const contentChanged = !existing || JSON.stringify({ nodes: existing.nodes, edges: existing.edges }) !== JSON.stringify({
          nodes: normalizedIncomingMap.nodes,
          edges: normalizedIncomingMap.edges,
        })
        if (!contentChanged && existing) return sendJson(response, 200, { map: existing, summary: mapSummary(existing) })
        const suppressedWorkNotificationNodeIds = new Set(
          (Array.isArray(body.suppressWorkNotificationNodeIds) ? body.suppressWorkNotificationNodeIds : [])
            .filter((nodeId) => typeof nodeId === 'string' && body.map.nodes.some((node) => node.id === nodeId))
            .slice(0, 100),
        )
        const map = await saveMap(mapId, normalizedIncomingMap, user, undefined, undefined, 'content')
        await createWorkChangeNotifications(existing, map, user, suppressedWorkNotificationNodeIds)
        await createWaitingReleaseNotifications(existing, map, user, {
          includeActor: hasValidIntegrationBearer(request),
        })
        if (contentChanged) broadcastMapChange(request, mapId, 'content', user)
        return sendJson(response, 200, { map, summary: mapSummary(map) })
      }

      if (request.method === 'PATCH') {
        if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 문서 정보를 변경할 수 없습니다.' })
        const existing = await readMap(mapId)
        if (!existing) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
        if (existing?.trashedAt) return sendJson(response, 409, { error: '휴지통에 있는 문서는 변경할 수 없습니다.' })
        const body = await readJsonBody(request)
        const hasTitle = typeof body.title === 'string'
        const hasColor = typeof body.color === 'string'
        if (!hasTitle && !hasColor) return sendJson(response, 400, { error: '변경할 문서 정보를 입력해 주세요.' })
        const baseVersion = Number(body.baseVersion)
        if (Number.isInteger(baseVersion) && baseVersion !== existing.version && body.force !== true) {
          return sendJson(response, 409, {
            error: '다른 사용자가 먼저 문서 정보를 변경했습니다.',
            code: 'VERSION_CONFLICT',
            map: existing,
            summary: mapSummary(existing),
          })
        }
        const title = hasTitle ? normalizeTitle(body.title, '') : existing.title
        if (!title) return sendJson(response, 400, { error: '문서 이름을 입력해 주세요.' })
        if (hasColor && !mapColors.includes(body.color)) return sendJson(response, 400, { error: '올바르지 않은 문서 색상입니다.' })
        const nextColor = hasColor ? body.color : existing.color
        const metadataChanged = title !== existing.title || nextColor !== existing.color
        const map = await saveMap(
          mapId,
          { nodes: existing.nodes, edges: existing.edges },
          user,
          title,
          nextColor,
          hasTitle && hasColor ? 'metadata' : hasTitle ? 'rename' : 'color',
        )
        if (metadataChanged) broadcastMapChange(request, mapId, hasTitle && hasColor ? 'metadata' : hasTitle ? 'rename' : 'color', user)
        return sendJson(response, 200, { map, summary: mapSummary(map) })
      }

      if (request.method === 'DELETE') {
        if (!canEdit(user)) return sendJson(response, 403, { error: '뷰어는 문서를 휴지통으로 이동할 수 없습니다.' })
        return await groupProjects.exclusive(async () => {
        groupProjects.assertCanTrash(mapId)
        const maps = await listMaps()
        if (maps.length <= 1) return sendJson(response, 409, { error: '마지막 문서는 휴지통으로 이동할 수 없습니다.' })
        const map = await trashMap(mapId, user)
        if (!map) return sendJson(response, 404, { error: '마인드맵을 찾을 수 없습니다.' })
        const remainingMaps = maps.filter((item) => item.id !== mapId)
        const documentLayout = await reconcileDocumentLayout(remainingMaps.map((item) => item.id))
        broadcastMapChange(request, mapId, 'trashed', user)
        return sendJson(response, 200, {
          trashedId: mapId,
          maps: await listMaps(),
          documentLayout,
          trash: await listMaps({ trashedOnly: true }),
        })
        })
      }
    }

    if (request.method === 'GET' && !url.pathname.startsWith('/api/')) {
      if (await serveStatic(request, response, url.pathname)) return
    }

    return sendJson(response, 404, { error: '요청한 경로를 찾을 수 없습니다.' })
  } catch (error) {
    if (error instanceof AiDelegationStatusLookupError) return sendJson(response, error.status, error.responseBody())
    if (error instanceof CrossDocumentCardMoveError) return sendJson(response, error.status, {
      error: error.message,
      code: error.code,
      ...(error.details ? { details: error.details } : {}),
    })
    if (error?.reconstructionError) return sendJson(response, error.status, { error: error.message, code: error.code, ...(error.details ? { details: error.details } : {}) })
    if (error?.groupProjectError) return sendJson(response, error.status, { error: error.message })
    if (error?.message === 'PAYLOAD_TOO_LARGE') return sendJson(response, 413, { error: '요청 데이터가 너무 큽니다.' })
    if (error instanceof SyntaxError) return sendJson(response, 400, { error: 'JSON 형식이 올바르지 않습니다.' })
    console.error(error)
    return sendJson(response, 500, { error: '서버 오류가 발생했습니다.' })
  } finally {
    releaseDocumentMutation?.()
    if (delegationActionId) aiDelegationActions.delete(delegationActionId)
  }
}))

runtimeLifecycle.interval(() => {
  broadcastEvent({ type: 'heartbeat', sentAt: new Date().toISOString() })
}, eventHeartbeatIntervalMs, 'Event heartbeat')

runtimeLifecycle.interval(() => refreshVisibleAiConversationRuntimes(), aiConversationRuntimePollIntervalMs, 'AI conversation runtime poll')

runtimeLifecycle.interval(() => pollAiDelegations(), aiDelegationPollIntervalMs, 'AI delegation poll')

runtimeLifecycle.interval(() => pollGroupDocumentInstructions(), aiDelegationPollIntervalMs, 'Group document instruction poll')

runtimeLifecycle.interval(() => doorayResponses.poll(), 3_000, 'Dooray response poll')

runtimeLifecycle.interval(() => ensureDailyBackups(), 60 * 60 * 1000, 'Daily backup scheduler')

// 제한 시간을 넘긴 서브 머신 요청을 재전달 없이 실패로 확정한다.
runtimeLifecycle.interval(() => {
  const expired = machineOperationQueue.sweep()
  if (expired > 0) console.warn(`[Machine operation sweep] ${expired}개 요청을 제한 시간 초과로 실패 처리했습니다.`)
}, 5_000, 'Machine operation sweep')

server.listen(port, host, () => {
  resolveRuntimeReady()
  console.log(`[Mind & Progress API] http://${host}:${port}`)
  console.log(`[Mind & Progress Public] ${publicBaseUrl}`)
  void runtimeLifecycle.track(() => recoverLinkedConversationAttributions()).catch((error) => {
    console.warn('[AI conversation attribution startup recovery]', error)
  })
})

